pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportionally to how much of the post-residual is used
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * use_ratio;
            // extra bonus if the pair leaves a tiny remainder (tight 2-step packing)
            let chain_left = post_residual - next_item_size;
            if chain_left <= 5 {
                score -= 100.0;
            }
        } else {
            // next item cannot use the post-residual: penalize proportionally to wasted dead space
            let waste = next_item_size - post_residual;
            score += 50.0 + waste as f64;
        }
    }

    // Reward filling bins whose residual is below the mean (consolidating slack),
    // penalize draining bins that are already slack-rich.
    let diff = mean_residual - post_residual as f64;
    score += 0.5 * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 80.0 + post_residual as f64 * 0.3;
    }

    // Mild pressure to close out nearly-full bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Penalize leaving large dead space, non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Slight preference for keeping the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 100.0 - (post_residual as f64) * 5.0;
    }

    // Class of residual modulo capacity fractions: residuals divisible by
    // common item sizes (10,20,25,50) are "usable" classes; reward them.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 20.0; }
        if r % 25 == 0 { score -= 15.0; }
        if r % 50 == 0 { score -= 15.0; }
        // Dead-space class: tiny unusable remainders.
        if r < 10 { score += 60.0; }
        // Integer-division threshold: residual in "half-bin" harmonic band.
        if r >= 45 && r <= 55 { score -= 25.0; }
        if r >= 90 { score -= 10.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: penalize leaving stranded space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 5.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good harmonic fit (large item, few fitting bins, early stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_bonus = (open_bins_count as f64) * 2.0;
        // Default: new bin is worse than reusing (penalty), unless item is huge.
        score += 40.0 - open_bonus;
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 120.0; // big item with only one fit: new bin may be better
        }
        if progress > 0.8 && mean_residual < item_size as f64 {
            score -= 50.0; // late stream, open bins are full-ish
        }
    }

    // Mild preference for tighter (fuller) bins overall.
    score += (bin_residual as f64) * 0.05;

    // Tie-break noise-free deterministic coupling with step index.
    score -= (step_index as f64 % 7.0) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest possible item (1),
    // but practically anything below a small threshold wastes capacity.
    let dead_threshold: f64 = 5.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 40.0; // near-zero gaps are worst
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the next item when it could have.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0; // keeps room for lookahead: good
        } else if pr > 0.0 && (n - pr) <= 10.0 {
            score += 12.0; // just barely breaks the next item's fit: bad
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // but if the fit creates a large dead gap while next item is big, soften
        if pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is loose.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - tightness) * 2.0;

    // Prefer filling bins with larger mean residual (consolidate space).
    score -= (mean_residual / bin_capacity as f64) * 3.0;

    // Mild preference to use existing bins vs new bin as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so it's only chosen when fits are truly bad.
        score += 20.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // modulo 10 (aligned with capacity fractions of C=100). Small residues that
    // cannot host the smallest item (size >= 1) are dead space -> penalize.
    let residue_class = post_residual % 10;
    if post_residual > 0 && residue_class != 0 {
        // Fractional dead space penalty: smaller unusable slivers hurt more.
        score += (10 - residue_class) as f64 * 0.8;
    }
    if post_residual < 10 && post_residual > 0 {
        score += 12.0; // near-dead sliver
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Integer-division thresholds: how many "typical" items (size ~ next_item_size)
    // could still fit in the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits = post_residual / next_item_size;
        score -= fits as f64 * 6.0;
        // If the next item exactly matches the leftover, strongly favor.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual - next_item_size < 10 {
            score -= 8.0; // leaves a small but possibly usable remainder
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; this bin becomes dead space after placement.
        score += 10.0;
    }

    // Last-chance bin: only one open bin fits the item -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class.
    if bin_residual == bin_capacity {
        // Compare against expected leftover quality: opening fresh is good only if
        // the item is large relative to capacity (harmonic class of item itself).
        let item_class = item_size / 10;
        score = 55.0 - (item_class as f64) * 4.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can also host the lookahead
        }
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // Stream progression: late in the stream, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= post_residual as f64 * progress * 0.5;
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creates gap the next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residuals are large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins tighter than the mean (consolidation of small residuals).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral baseline with slight opening cost,
    // so it only wins when existing bins score very poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 900.0;
        } else if post >= nxt && (post - nxt) <= 10.0 {
            score -= 400.0;
        } else if post >= nxt && (post - nxt) <= 25.0 {
            score -= 150.0;
        } else if post < nxt {
            // post-residual too small for next item: dead space unless tiny
            if post <= 10.0 {
                score -= 50.0; // harmless crumb
            } else {
                score += 0.5 * (post - nxt); // stranded space penalty
            }
        }
        // Prefer bins whose post-residual stays close to the stream's
        // typical residual so future items keep fitting.
        let dev = (post - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 200.0;
        if post_residual > 40 {
            score += 100.0; // still wasteful fit; soften the bonus
        }
    }

    // Penalize opening a new bin when good open options exist:
    // the new-bin candidate has bin_residual == bin_capacity; its post_residual
    // is large, so add pressure proportional to remaining stream length.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * (1.0 - progress);
        // But if next item is huge and this bin's post-residual would fit it
        // while no open bin could, opening can pay off (handled implicitly by
        // lookahead rewards above).
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 30.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are worthless.
    if post_residual < 10 {
        score += 45.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 18.0; // risky small gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins unless the current fit is poor
    // or the next item can use the fresh bin well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 55;
        let lookahead_ok = next_item_size == 0 || next_item_size as f64 >= post_residual as f64;
        if !poor_fit && !lookahead_ok {
            score += 40.0;
        } else {
            score += 5.0;
        }
    }

    // Lookahead synergy: prefer bins whose leftover accommodates the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 12.0;
        } else if gap < 10 {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 0.5;
    }

    // Deviation from mean residual: prefer bins tighter than average (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

