pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual classes mod 10 capture
    // "dead space" granularity. Small residuals that are not multiples of
    // common item sizes (10, 20, ...) are effectively unusable.
    let dead = post_residual < 10;
    let harmonic = post_residual % 10;

    // Penalize dead space heavily, especially near-harmonic waste.
    if dead {
        score += 40.0;
    } else {
        score += (harmonic as f64) * 0.6;
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that are multiples of 10 (likely reusable by future items).
    if !dead && harmonic == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // integer-division threshold on next_item_size vs post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Chain fit: next item leaves a harmonic residual too.
            let chain_residual = post_residual - next_item_size;
            if chain_residual % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // create dead space and the new bin offers better long-run utility.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive early in the stream or when many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 15.0 + progress * 10.0;
        if dead || post_residual < 5 {
            // current placement creates waste; new bin slightly better
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Mild preference for filling bins with larger residual more when many bins are open.
    score += mean_residual * 0.05 + open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 (or near
    // multiples of common item sizes) are more reusable; penalize odd residues.
    let r = post_residual;
    let class = r % 10;
    if class == 0 {
        score -= 12.0;
    } else if class <= 2 || class >= 8 {
        score += 6.0; // awkward sliver
    }

    // Integer-division thresholds: a residual that can exactly host the next
    // item is gold.
    if next_item_size > 0 {
        if r >= next_item_size {
            let slack = r - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack % 10 == 0 { score -= 5.0; }
        } else {
            score += 10.0; // next item cannot follow here
        }
    }

    // Fraction-of-capacity harmonic bands on the post residual.
    let frac = r as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 15.0; // near-dead bin
    } else if frac < 0.3 {
        score += 4.0;
    } else if frac > 0.6 {
        score -= 4.0; // roomy bin still useful
    }

