    }

    // Relative to mean residual: prefer bins that tighten the average residual spread.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are truly poor.
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    // Early in the stream, allow more bin openings (future packing flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (Best-Fit core)
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, higher = tighter
    score -= 6.0 * fit_ratio;

    // Penalize opening a new bin when open bins could fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0;
        // Early in stream, opening bins is cheaper (build diversity); later, avoid it
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If item is huge relative to capacity, new bin is natural anyway
        score -= 8.0 * (item_size as f64 / cap);
    } else if fitting_bins_count == 1 {
        // Last chance: strongly reward using this bin to avoid a new bin
        score -= 15.0;
    }

    // Lookahead (k=2): reward if next item fits into post_residual (good chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 4.0 * (nxt / cap);
        } else {
            // Next item won't chain here; penalize leaving awkward small gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 6.0; // dead space trap
            }
        }
    }

    // Global pressure: if many bins open with large mean residual, prefer consolidating
    let mean_r = mean_residual.max(0.0);
    if !is_new_bin {
        score -= 2.0 * (bin_residual as f64 - mean_r) / cap; // favor bins with below-average residual (fuller bins)
    }

    // Mild penalty for very large open-bin count (fragmentation control)
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Time horizon: late in stream, squeeze hard into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = fitting_bins_count;
    post_residual
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes: partition residual space into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Integer-division harmonic class of the post residual (quarters of capacity).
    let quarter = (post_residual * 4) / bin_capacity; // 0..=4 class
    // Penalize dead space in the awkward "small leftover" class (residual < 25% cap):
    // such slivers are rarely reusable.
    if quarter == 0 {
        score += 14.0;
    } else if quarter == 1 {
        score -= 3.0; // quarter-sized leftovers pair well with items in 10..30
    } else if quarter == 2 {
        score -= 6.0; // half-capacity residual is the most reusable class
    } else if quarter == 3 {
        score -= 4.0;
    }

    // Modulo coupling: exact-fill and near-exact-fit bonuses on modular arithmetic.
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual % 10 == 0 {
        score -= 6.0; // decadal residual aligns with typical item granularities
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 2.0; // odd slivers are harder to fill
    }

    // Lookahead harmonic check: does the next item land cleanly into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item divides the post residual into a nice class
            let next_post = post_residual - next_item_size;
            let next_quarter = (next_post * 4) / bin_capacity;
            score -= 4.0 + (3.0 - next_quarter.min(3) as f64) * 2.0;
            if next_post % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 5.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Avoid fragmenting when many bins are open and mean residual is already low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 6.0 * (0.5 + progress); // creating below-average residuals is bad late
    }

    // New-bin candidate handling: only prefer a fresh bin if this bin would leave
    // a worthless sliver and the item is small enough to stack later.
    if bin_residual == bin_capacity {
        let fresh_penalty = 25.0 - 10.0 * progress;
        // Fresh bin is attractive only if item is huge (fits nowhere well later).
        score = fresh_penalty + (cap - item_size as f64) * 0.1;
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, zero waste
    } else if post_residual < 10 {
        // unusable micro-gap: strong penalty so tight fits win over leaving crumbs
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // moderate gap: mildly penalize, it can still host small items
        score += 5.0;
    } else {
        // large residual is reusable: reward keeping it
        score -= (post_residual as f64) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 30.0; // sets up a near-perfect second fit
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's remainder; slight penalty for stranding space
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // candidate for a brand-new bin: penalize proportionally to open bins
        score += (open_bins_count as f64) * 3.0 + 15.0;
        // but if the item is large and mean residual across bins is small, a new bin is fine
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // using an existing bin relieves open-bin pressure slightly
        score -= 2.0;
    }

    // Late-stream consolidation: near the end, pack into existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64)).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits into the would-be post residual: strong lookahead reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Next item does NOT fit the residual: penalize leaving awkward dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Tight fits are good: small post_residual relative to capacity is rewarded.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Compare against mean residual of open bins: prefer bins with more room
    // than average when the fit is loose, avoid draining already-tight bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * open_bins_count as f64;

    // New empty bin candidate: penalize unless the current bin fit is poor
    // (large post_residual means the item barely fits anywhere useful).
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the current fit leaves a big awkward gap, opening fresh is fine.
        if post_residual as f64 > mean_residual {
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= pressure * (0.5 + 0.5 * progress);

    // Late in the stream, consolidate aggressively
    score -= 15.0 * progress * (mean_residual / bin_capacity as f64);

    // New-bin candidate: make empty bins less attractive unless the item is huge
    if bin_residual == bin_capacity {
        let huge = item_size as f64 > 0.8 * bin_capacity as f64;
        if huge && fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: late in the stream, dead space
    // becomes more costly (less chance to fill it), so amplify post_residual.
    let prog_term = progress * progress;
    score *= 1.0 + 0.8 * prog_term * norm_pr;

    // Smooth interaction: small post_residual is especially valuable when the
    // bin mean residual is high (this bin is a good consolidator).
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (mean_residual / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_fit = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: empty bin has large post_residual; add a
    // smooth opening cost so it is only chosen when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on
    // "useful" capacity fractions are rewarded, dead-space classes penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: residual divisible into small harmonics (5/10/20/25/50)
    if post_residual % 10 == 0 {
        score -= 12.0;
        if post_residual % 50 == 0 {
            score -= 8.0; // half-capacity class: very reusable
        }
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        // awkward class: penalize by how far from the nearest multiple of 10
        let off = (post_residual % 10).min(10 - post_residual % 10);
        score += off as f64 * 2.5;
    }

    // Integer-division threshold: residuals below the smallest item class (<=10)
    // are pure dead space.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead harmony: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect harmonic pair
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item cannot use this residual: dead space risk
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = (mean_residual / cap).min(1.0);
        score = cap * (0.35 + 0.5 * tight) - 60.0 * pressure;
    }

    // Slight preference for fuller bins overall
    score -= (bin_residual as f64 / cap) * 3.0;

    // Mild stream-progression damping of lookahead terms late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are almost unusable
    // since items are >= 1 but typically large; penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 20.0 * (1.0 - (post_residual - 10) as f64 / 10.0);
    }

    // Reward very tight fits (post_residual near zero without being dead space).
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are already open (pressure to consolidate).
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    score += 0.4 * open_bins_count as f64;

    // Slight preference for bins with lower residual relative to mean
    // (consolidate space into fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), slightly superlinear.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (perfect chaining) or fits in the leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect match: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward proportional to how much it consumes.
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * consumed;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            // more strongly when the leftover is small and unusable.
            let waste = post_residual as f64;
            score += 10.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // "tight" bins; placing here keeps large residuals for future big items.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and no open bin is a decent fit; also slightly discourage new
    // bins when many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        let mut new_bin_score = bin_capacity as f64;
        new_bin_score += 15.0 * (open_bins_count as f64).ln().max(0.0);
        // Progress factor: later in the stream, prefer consolidating.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 20.0 * progress;
        // If the item is big relative to capacity, a fresh bin is more acceptable.
        new_bin_score -= 30.0 * (item_size as f64 / bin_capacity as f64);
        // If lookahead item is huge, a fresh bin helps it fit later.
        if next_item_size > 50 {
            new_bin_score -= 15.0;
        }
        return new_bin_score;
    }

    // Mild preference for filling earlier-opened (tighter) bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: strongly reward small post_residual (perfect fits first).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item can exactly use the remaining space, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits too: mild reward proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64 / bin_capacity as f64) * 15.0;
        } else {
            // next item won't fit here: penalize wasting residual the next item could have used in a wider bin
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current placement would create large dead space or few alternatives exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; scales with how many bins already fit the item.
        let mut penalty = 12.0 + 8.0 * (fitting_bins_count as f64).min(5.0);
        // If the item would leave a large unusable-ish gap in any existing bin, soften the penalty.
        let gap = post_residual as f64 / bin_capacity as f64;
        penalty -= gap * 10.0;
        // Early in the stream, opening bins is cheaper (keeps flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += progress * 15.0;
        // Many open bins with slack: discourage adding more bins.
        if mean_residual > item_size as f64 {
            penalty += 6.0;
        }
        score += penalty;
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate slack).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    // Dead-space penalty: residual smaller than the smallest conceivable item (1..100 stream, min ~1)
    // is only truly dead if very small; penalize residuals in (0, 10) range lightly.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference for bins with more residual when everything else is equal
    // (keeps large holes available), but only if the item still fits comfortably.
    if item_size as f64 > 0.7 * bin_residual as f64 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;
    let fill = 1.0 - post_norm;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Reward tight fits with smooth polynomial term
    score -= 20.0 * fill * fill * fill * (1.0 + progress);

    // Penalize small dead space that is hard to reuse (smooth valley)
    score += 6.0 * post_norm * (1.0 - post_norm) * (1.0 - post_norm);

    // Lookahead: reward leaving room for the next item
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = post - next;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 0.05 * (-gap);
        }
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Slight preference for fuller bins relative to mean residual
    score -= 0.3 * (mean_residual - post);

    // Mild pressure to open fewer bins early
    score += 0.4 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: capacity fractions ---
    let frac = post_residual as f64 / bin_capacity as f64;

    // Class boundaries at 1/4, 1/3, 1/2 of capacity. Dead space in the
    // lowest class is nearly unusable for items >= 10, so penalize hard.
    if frac < 0.25 {
        score += 60.0 * (0.25 - frac);
    } else if frac < 0.3333 {
        score += 15.0 * (0.3333 - frac);
    } else if frac < 0.5 {
        score -= 10.0 * (frac - 0.3333);
    } else {
        // Large residual left: fine, but slight reward for keeping slack.
        score -= 5.0 * frac;
    }

    // --- Integer-division harmonic classes of post_residual ---
    // Residuals divisible into nice chunks (multiples of 10, 20, 25) pair
    // better with typical item sizes; reward exact class membership.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    // Awkward odd residuals (prime-ish, mod 7 == 3 or 5) tend to strand.
    if pr % 7 == 3 || pr % 7 == 5 {
        score += 8.0;
    }

    // --- Coupling with next item size (lookahead) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits perfectly in the post residual -> excellent.
            let slack = pr - next_item_size;
            score -= 25.0;
            if slack % 10 == 0 {
                score -= 10.0;
            }
            if slack == 0 {
                score -= 30.0; // perfect pairing: bin closes cleanly
            }
        } else if next_item_size <= pr + 10 {
            // Near miss: next item almost fits, mild penalty.
            score += 5.0;
        } else {
            // Next item cannot use this residual at all: residual is dead
            // for at least one step; penalize proportionally.
            score += 12.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; opening a new bin is costly.
        score -= 40.0;
    }

    // --- New bin candidate: only attractive when open bins fit badly ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin; cheaper late in the stream when
        // open-bin residuals are fragmented.
        score = 45.0 + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        } else if mean_residual < 0.35 * bin_capacity as f64 {
            score -= 20.0; // open bins are cramped; fresh bin is fine
        }
        return score;
    }

    // --- Tight fit reward: minimal waste relative to item size ---
    let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
    if waste_ratio < 0.1 {
        score -= 20.0; // near-perfect fill
    } else if waste_ratio > 2.0 {
        score += 6.0 * (waste_ratio - 2.0).min(4.0); // wasteful placement
    }

    // Mild global pressure: many open bins -> prefer consolidation.
    score += 0.5 * open_bins_count as f64;
    // Prefer bins below mean residual (fill the emptier ones first keeps
    // tight bins available for small items).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item
    // (or below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    let usable_threshold = next_item_size.max(min_item) as f64;

    if (post_residual as f64) < usable_threshold {
        // Dead space: gap too small to ever fit the upcoming item.
        score += 40.0 + (usable_threshold - post_residual as f64) * 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else {
        // Tight but usable fit: reward proportionally to snugness.
        score -= (usable_threshold - post_residual as f64).max(0.0) * 0.5;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly by rewarding reuse).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 + open_bins_count as f64 * 0.3 * (1.0 - progress);
    } else {
        // New bin candidate: penalize more when many bins are already open.
        score += 10.0 + open_bins_count as f64 * 0.5;
        // But if the item leaves a large residual that matches mean residual scale,
        // a fresh bin may be fine early in the stream.
        score -= progress * 5.0;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the fleet of open bins homogeneous).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here after placing current item: penalize tight fills.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // No lookahead: prefer tightest fit.
        score += 10.0;
    }

    // Reward small post_residual (tight packing), nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual; penalize loose bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress;

    // New empty bin candidate: penalize unless item is large or current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).max(1.0);
        // Penalty shrinks as stream progresses and mean residual grows (waste).
        score += 45.0 * (1.0 - 0.6 * progress) * (1.0 - (mean_residual / (bin_capacity as f64)).min(1.0)) / pressure.sqrt();
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for small leftover.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mild penalty for scattering across many open bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Time horizon: early stream, be conservative (favor packing into existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress) * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), smoothed by progress
    let mut score = pr;

    // Non-linear coupling: late in the stream, dead space matters more (quartic in progress)
    let urgency = progress * progress * progress * progress;
    score += urgency * norm_post * cap * 0.8;

    // Reward near-perfect fits: subtract a smooth quadratic bonus when post_residual is tiny
    let tightness = (1.0 - norm_post).max(0.0);
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, penalize alternatives strongly elsewhere
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - urgency);
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = 1.0 - (pr - nx) / cap;
            score -= 10.0 * slack * slack * (0.5 + 0.5 * progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Mild penalty when this bin's residual deviates from mean residual (fragmentation spreading)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 6.0;

    // Slight preference for using existing bins over opening new ones, stronger early
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * urgency);
    }

    // Smooth open-bin pressure: many open bins -> favor consolidation
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space classes are bad
    let dead_class = post_residual % 10;
    score += (dead_class as f64) * 3.0;

    // Penalize post_residual that is too small to ever fit a plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward post_residual that matches a harmonic fraction of capacity
    let fractions: [u32; 5] = [bin_capacity / 2, bin_capacity / 3, bin_capacity / 4, bin_capacity / 5, bin_capacity / 10];
    for f in fractions.iter() {
        if post_residual == *f {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize wasting the bin
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New bin candidate: only attractive when nothing fits well elsewhere
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if post_residual >= 50 {
            score -= 30.0;
        }
    }

    // Prefer tighter bins: closeness of item to residual
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Stream progression: early on, be more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual context: avoid bins far below mean when mean is large
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // absolute dead space: terrible
    } else if (post_residual as f64) < 25.0 {
        // small gap that only tiny items could use — penalize super-linearly
        score += (25.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual) nonlinearly
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 15.0;

    // Open-bin pressure: discourage proliferating bins, but only mildly,
    // so a good fit still beats opening a new bin.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Only prefer it if the item is large relative to capacity (good fill) or
    // no open bin fits well.
    if bin_residual == bin_capacity {
        // neutralize base reward so new bins aren't favored by tight-fit term
        score += 15.0;
        // opening a new bin is fine when item is big
        if item_size >= 60 {
            score -= 20.0;
        }
        // if next item is large too, fresh bin is useful
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post gap, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
        score -= 25.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use this gap; the gap becomes dead weight
        score += (post_residual as f64) * 0.3;
    }

    // Mean residual coupling: if open bins are already loose, prefer filling them
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: late in stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: bin becomes exactly filled next step
        } else if post_residual > next_item_size {
            // leftover after the next item would be placed
            let after = post_residual - next_item_size;
            score -= 30.0 * (1.0 - after as f64 / bin_capacity as f64);
            if after < 10 {
                score += 10.0; // tiny dead space after chain
            }
        } else {
            // next item cannot follow in this bin
            score += 15.0;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize deviating far from mean residual (keeps bin pool balanced).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference to fill nearly-full bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 6.0;

    // Time horizon: early in stream, be more willing to open new bins
    // (keep residuals large); late, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.25;
    score -= progress * 10.0 * tightness;

    // Global residual context: if mean residual is high, discourage
    // scattering; if low, prefer any bin that fits well.
    let mean_gap = (mean_residual - bin_residual as f64) / (bin_capacity as f64);
    score += 10.0 * mean_gap;

    // New-bin candidate calibration: an empty bin has large post_residual,
    // so it naturally scores high; ensure it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - pr / cap; // how full the bin becomes

    // Base: prefer small post_residual, smoothed non-linearly
    let mut score = (pr / cap).powi(2) * cap * 0.5 + pr * 0.3;

    // Reward tight fits with a smooth saturating term
    score -= tight.powi(3) * 12.0;

    // Stream progress coupling: late in the stream, favor tighter packing more strongly
    let late = progress * progress;
    score -= late * tight * 8.0;

    // Penalize leaving dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0) / cap;
        score += gap.powi(2) * 20.0 * (1.0 - late);
        // Bonus if next item fits exactly-ish in the post residual
        let fit_quality = 1.0 - ((pr - nx).abs() as f64 / cap);
        score -= fit_quality.max(0.0) * 4.0;
    }

    // Last-chance bin bonus: only fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 2.0;

    // New-bin candidate: keep it slightly unattractive unless residuals are large
    if bin_residual == bin_capacity {
        score += 6.0 - late * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: divide capacity into 8 fractions.
    let class = post_residual / (bin_capacity / 8);
    match class {
        0 => score -= 25.0,                       // near-perfect fit, dead space minimal
        1 => score -= 12.0,
        2 => score -= 5.0,
        3 => {}                                   // mid-range, neutral
        4 => score += 5.0,
        5 => score += 10.0,
        6 => score += 18.0,
        _ => score += 25.0,                       // large leftover, wasteful
    }

    // Modulo coupling: residuals divisible by common item sizes (10,20,25,50)
    // are more reusable — reward them.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 4.0; }
        if r % 25 == 0 { score -= 3.0; }
        if r % 50 == 0 { score -= 4.0; }
    } else {
        score -= 20.0; // perfect fill
    }

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual == next_item_size { score -= 15.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; leftover becomes dead space, penalize
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: mildly penalize opening a new bin early in the stream,
    // but allow it when mean residual across open bins is low (all bins tight).
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress; // later in stream, new bins are less costly
        if mean_residual < 15.0 { score -= 25.0; } // open bins nearly full, open new one
    }

    // Prefer bins with residual close to the item (tight packing).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    // Slight preference to keep number of open bins stable.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to hold even the smallest
    // plausible item are wasted capacity; penalize them sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0;
    }
    // Semi-dead zone: gaps below typical mid-size items are risky too.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage opening more,
    // encourage filling existing ones.
    score += 3.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open;
        // allow it when few bins are open or the item is huge.
        score += 20.0 + 4.0 * open_bins_count as f64;
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this placement; if next item is larger than the
    // post residual but smaller than bin residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is close to
    // (or below) the mean, avoiding isolation of large-residual bins.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Stream progression: early on, be more willing to open bins;
    // late in the stream, prioritize consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: make it attractive only when the item fits
    // very poorly in existing bins (large item, little usable residual space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress
        // (early stream: cheaper to open bins since more items remain to fill them).
        let progress = step_index as f64 / total_items as f64;
        let base = 30.0 + 40.0 * progress;
        // If item leaves a big hole in any existing bin, opening fresh is fine.
        let hole_penalty = (item_size as f64 / bin_capacity as f64) * 20.0;
        return base - hole_penalty;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect match: post_residual equals the next item's size -> subtract heavily.
        let match_gap = (post_residual as f64 - nxt).abs();
        score -= 12.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0) * 3.0;

        // If next item fits exactly in post_residual (gap 0), strong reward.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit in post_residual, penalize proportionally to waste.
        else if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // capacity; using them for a sloppy fit is costly.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slightly reward below-mean leftovers
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Tight fits (small post_residual) are good, but avoid residual < 10 (dead space
    // for the minimum item size) -> penalize unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space superlinearly (unusable gaps are costly).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Reward tight fits: item filling most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Perfect-fit bonus when residual becomes exactly 0.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 10.0;
        } else {
            // Post-residual too small for next item: penalize creating a trap.
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Time horizon: early in stream, be picky (penalize loose fits); late, be greedy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * fill_ratio * 8.0;

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score -= pressure.min(20.0) * 0.5;

    // New-bin candidate: make it mildly attractive only when it's a bad fit elsewhere
    // (empty bin has high post_residual, so base score already penalizes it),
    // but discourage opening new bins when several bins can fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * fitting_bins_count as f64;
        // Late in stream, opening fresh bins is less wasteful (distribution known).
        score -= progress * 10.0;
    }

    // Prefer bins whose residual is close to the item (best-fit core, amplified).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer low post-residual, with a smooth convex penalty on waste.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Tight-fit reward: strongly favor small post_residual via smooth saturating term.
    score -= 12.0 * (1.0 - norm_post).powi(6);

    // Stream-progress coupling: later in the stream, waste matters more (smooth ramp).
    score += post * 0.9 * progress * progress;

    // Dead-space avoidance: penalize residuals too small for the smallest plausible item (1..100).
    let dead = (6.0 - post).max(0.0);
    score += dead * dead * 1.5;

    // Lookahead: reward residuals that still fit the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (post - nx).max(0.0) / cap;
        let can_fit = (nx <= post) as i32 as f64;
        score -= 6.0 * can_fit * (1.0 - fits_next).powi(3);
        // Penalize leaving space that neither fits next item nor is tight.
        let miss = ((post - nx).max(0.0)) as f64;
        score += 0.05 * miss;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - norm_post);
    }

    // New-bin candidate: mildly discourage opening bins when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing), smooth.
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod 10 defines "usable" vs "dead" space.
    let pr = post_residual as i64;
    let class = pr % 10;
    // Class 0 leftovers are perfect (reusable by multiples of 10); small nonzero classes (1..3)
    // are near-dead space; large classes (7..9) are almost the next harmonic cell.
    let class_penalty = match class {
        0 => -14.0,
        1 => 16.0,
        2 => 12.0,
        3 => 8.0,
        4 => 0.0,
        5 => -6.0,
        6 => -4.0,
        7 => -10.0,
        8 => -12.0,
        9 => -11.0,
        _ => 0.0,
    };
    score += class_penalty as f64;

    // Integer-division threshold: leftover cells of size >= 10 are reusable slots.
    let slots = pr / 10;
    score -= 2.5 * slots as f64;

    // Tight fit reward: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 30.0 * fill_frac;

    // Lookahead coupling: does the leftover harmonically match the next item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr > 0 && (pr as f64) >= n {
            // Exact harmonic match: next item fills leftover to a multiple of 10.
            let rem = pr - next_item_size as i64;
            if rem % 10 == 0 {
                score -= 18.0;
            } else if rem < 10 {
                score += 6.0; // would strand sub-10 dead space
            } else {
                score -= 6.0;
            }
            // Reward proportional match within the same harmonic class.
            if (pr as i64 - next_item_size as i64).abs() <= 5 {
                score -= 4.0;
            }
        } else if pr > 0 {
            // Next item cannot use this leftover at all: leftover likely dead.
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste, prefer fullest packing.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: slight penalty to keep discrimination sharp.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item is large or leftovers would be awkward.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap > 0.5;
        let awkward = next_item_size > 0 && (post_residual as f64) < next_item_size as f64;
        if large_item || awkward {
            score -= 12.0;
        } else {
            score += 15.0; // prefer filling existing bins with small/medium items
        }
    }

    // Stream progression: early on, tolerate more open bins; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64 / 8.0);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are nearly worthless; punish them quadratically.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Fractional fill: reward high utilization non-linearly.
        let fill = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill * fill;
    }

    // Lookahead: if the next item fits the post-residual exactly, big bonus;
    // if it doesn't fit, penalize leaving a gap the next item can't use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins; few open bins -> new empty bin is relatively cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure; also bias by stream progress.
        let progress = step_index as f64 / total_items as f64;
        score = 55.0 + 18.0 * pressure + 10.0 * progress;
        // If nothing else fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        score += 6.0 * pressure;
        // Slight preference for bins tighter than average (mean_residual).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual by stream progression
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    // 2-step lookahead: perfect match of next item into post residual is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item completion
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead.min(next_item_size as f64);
        }
    }

    // Penalize residuals that become unusably small relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild penalty for opening new bins when plenty are open and fit is decent
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if no open bin fits well (post_residual large dead space)
        if next_item_size > 0 && post_residual > next_item_size + 40 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space relative to the smallest conceivable item (1..100 range).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't chain here; penalize more if we leave a large unusable gap.
        score += 8.0 * waste_frac;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: encourage compacting into the fullest bin.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 12.0 * fullness;
    }

    // New-bin candidate handling: opening a new bin should only win when current
    // fits are poor. Make the empty bin moderately attractive by default.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // But penalize opening new bins when good fits exist elsewhere.
        if fitting_bins_count > 0 {
            let best_possible = post_residual as f64; // post_residual == capacity - item here
            if best_possible > 20.0 {
                score += 15.0;
            }
        }
        // Late in the stream, prefer consolidating: new bins are costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state: many open bins with large mean residual -> encourage filling
    // existing bins harder rather than fragmenting.
    if open_bins_count > 4 && mean_residual > (item_size as f64) {
        score -= 6.0;
    }

    // Time-horizon coupling: early on, allow slight openness; late, compact hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * waste_frac * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual, modulated by stream progress.
    // Early in the stream, keep bins tight; later, waste is more forgivable.
    let mut score = post * (1.0 + 1.5 * norm_post) * (1.0 + 0.8 * progress);

    // Smooth coupling: prefer bins whose residual closely matches the item
    // (post_residual near zero) via a smooth "tight fit" reward.
    score -= 20.0 * (-post / 15.0).exp();

    // Dead-space coupling: penalize post-residual that is too small to be useful
    // for typical future items (smooth sigmoid around half-capacity).
    let usable = 1.0 / (1.0 + (-8.0 * (norm_post - 0.25)).exp());
    score += 12.0 * (1.0 - usable) * (1.0 - progress);

    // Lookahead: reward bins whose post-residual can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post >= nxt) as i32 as f64;
        let slack = ((post - nxt) / cap).max(0.0);
        score -= 15.0 * fits_next * (1.0 - slack).min(1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth scaling by inverse fitting count).
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual dispersion term: prefer bins deviating from the mean
    // (consolidate waste into few bins), smooth quadratic coupling.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin smoothly, unless the item
    // is large relative to the bin (poor fit elsewhere is implied by low score there).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * norm_item;
        // But late in the stream with many open bins, a fresh bin is cheap.
        score -= 20.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions (1/8 granularity)
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic class

    // Dead-space penalty: small residuals (< ~1/8 of capacity) are near-useless
    if class == 0 && post_residual > 0 {
        score += 30.0;
    } else if class == 1 {
        score += 12.0;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Lookahead coupling: does next item fit harmonically in the post residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, scaled by how tight the future fit is
            let tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 20.0 + 25.0 * tight;
            // harmonic pairing: next item exactly divides post residual
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            let gap = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tightest fits (post_residual already does this)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Integer-division threshold: residual classes divisible by common item sizes
    // (sizes 1..=100; common divisors 10, 20, 25, 50 keep bins reusable)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: mild penalty that grows with progress and open bins
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // but if current bin fit would be very poor, allow new bin
        if frac < 0.1 && post_residual > 0 {
            score -= 40.0;
        }
    }

    // Slight preference for bins with below-mean residual (concentrate filling)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit any item (min size 1,
    // but small gaps < ~10 are practically unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that cannot fit the lookahead item are semi-dead: penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead synergy: if the post residual exactly accommodates the next item,
    // reward it (chains well).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading; prefer filling
    // existing bins (a new bin has bin_residual == bin_capacity and large post_residual,
    // so this pressure also suppresses premature new-bin opening).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate guard: an empty bin should only win when it's genuinely
    // better; add a fixed opening tax.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves more slack: mild reward scaled by tightness.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack_after_next * 1.5;
        } else {
            // Next item will NOT fit here: penalize leaving residual that is
            // too small to be useful (dead space relative to next item).
            let wasted = post_residual as f64 / next_item_size as f64;
            score += (next_item_size - post_residual) as f64 * 0.8 + wasted * 10.0;
        }
    }

    // Penalize creating residuals that are unlikely to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // tiny dead space is nearly useless
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin offers
    // a good fit (post_residual large means poor fit into existing bins).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above good fits; discourage hoarding open bins
        // when mean residual is already high.
        score += 60.0 - mean_residual * 0.3;
        if open_bins_count == 0 {
            score -= 1000.0; // must use a bin if none open
        }
    }

    // Slight preference for tighter bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Late-stream pressure: consolidate toward the end to reduce bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but with diminishing returns so
    // near-perfect fits aren't over-favored vs. moderate fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small unusable dead space (dead-space valley).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for chain-fitting (post residual close to next item).
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 14.0;
            } else if gap < 10 {
                score -= 5.0;
            }
        } else {
            // Placement strands the next item: penalize proportionally.
            score += 4.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Competition penalty: many bins fit, prefer the tightest anyway (already
        // handled), but nudge away from bins that are "too roomy" relative to mean.
        score += 0.05 * (open_bins_count as f64).sqrt();
    }

    // Global state: if mean residual is high, packing into open bins is cheap;
    // if mean residual is low, opening a fresh bin is less costly.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.08 * mean_gap;

    // New-bin candidate logic: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged when decent fits exist, but attractive
        // when the item is large relative to typical residuals or late in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0;              // base cost of a new bin
        score -= 15.0 * item_frac;  // large items justify fresh bins
        score -= 10.0 * (1.0 - progress); // early stream: new bins pay off later
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;          // fresh bin can also host next item
        }
        if fitting_bins_count == 1 {
            score += 30.0;          // don't abandon the only fitting bin
        }
    }

    // Late-stream consolidation: as the stream ends, tighten packing to avoid
    // stranding many partially-filled bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty scaling with open bin count to curb bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: tight fits are favored, more so late in the stream.
    let tightness = 1.0 - norm_post; // 1.0 = perfect fit
    let progress_coupling = tightness * tightness * (0.5 + progress);
    score -= 12.0 * progress_coupling * (1.0 + norm_item);

    // Penalize dead space non-linearly: residuals that can't fit typical items (small leftovers)
    let dead = (norm_post - 0.1).max(0.0) * (norm_post - 0.1).max(0.0);
    score += 30.0 * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it expensive unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (0.75 + 0.5 * progress)
            - (mean_residual / bin_capacity as f64) * 20.0;
        // Allow opening a new bin when the next item is large and would fragment a used bin
        if next_item_size > 0 {
            let next_norm = next_item_size as f64 / bin_capacity as f64;
            score -= 10.0 * next_norm * (1.0 - norm_post);
        }
    }

    // Lookahead: reward leaving room for the next item in this bin.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        let gap = norm_post - next_norm;
        if gap >= 0.0 {
            score -= 8.0 * (gap * (1.0 - gap)).max(0.0);
        } else {
            score += 6.0 * (-gap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.15 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual classes mod 10 capture
    // "dead space" granularity. Small residuals that are not multiples of
    // common item sizes (10, 20, ...) are effectively unusable.
    let dead = post_residual < 10;
    let harmonic = post_residual % 10;

    // Penalize dead space heavily, especially near-harmonic waste.
    if dead {
        score += 40.0;
    } else {
        score += (harmonic as f64) * 0.6;
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that are multiples of 10 (likely reusable by future items).
    if !dead && harmonic == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // integer-division threshold on next_item_size vs post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Chain fit: next item leaves a harmonic residual too.
            let chain_residual = post_residual - next_item_size;
            if chain_residual % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // create dead space and the new bin offers better long-run utility.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive early in the stream or when many bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 15.0 + progress * 10.0;
        if dead || post_residual < 5 {
            // current placement creates waste; new bin slightly better
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Mild preference for filling bins with larger residual more when many bins are open.
    score += mean_residual * 0.05 + open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Treat residuals below the minimum plausible item size as pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: hard penalty proportional to how close we are to a perfect fit being wasted.
            score += 40.0 * (10 - post_residual) as f64;
        } else {
            // Usable gap: mildly penalize, but reward larger usable leftovers mildly.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are already open.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin is a fresh resource; only attractive
    // when open bins have poor residuals relative to the item, or when the lookahead
    // item would benefit from a fresh large residual.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 55.0;
        // Reduce the penalty if existing bins are fragmented (mean residual small).
        score -= 0.4 * mean_residual;
        // If the next item is large and this item is small, a fresh bin preserves
        // flexibility for the big item.
        if next_item_size > 50 && item_size < 40 {
            score -= 35.0;
        }
        // Early in the stream, allow more bins (uncertain future distribution).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else {
        // Existing bin: bonus if it can also accommodate the lookahead item afterwards.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize placing an item that leaves a gap just barely below the next item size
        // (near-miss dead space for the lookahead).
        if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
            let gap_deficit = (next_item_size - post_residual) as f64;
            if gap_deficit < 20.0 {
                score += 0.8 * (20.0 - gap_deficit);
            }
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor),
    // scaled by deviation from mean residual to spread load sensibly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            // next item still fits: reward proportionally to tightness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space that the next item cannot use
            score += 15.0 + diff * 0.5;
        }
    }

    // Penalize large leftover relative to mean residual (wasteful fragmentation).
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Brand-new empty bin candidate: only attractive if item is large
    // (poor fit elsewhere) or no open bin fits well; otherwise penalize.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - load_frac);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can still host the next item
        }
    }

    // Slight preference early in the stream to keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization dominates).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        score -= 60.0 / pr.sqrt(); // tighter fit -> bigger discount
    }

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit exactly into the post residual,
    // this placement is excellent (chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 80.0;
        } else if pr >= nxt {
            score -= 20.0 * (nxt / pr);
        } else {
            // post residual cannot host next item: mild penalty scaled by gap
            score += 8.0 * ((nxt - pr) / bin_capacity as f64).min(1.0);
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing capacity is plentiful.
        let slack = mean_residual * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + slack * 0.15 - 20.0 * progress;
        // But reward a fresh bin when item is large and fits poorly elsewhere.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward using bins whose residual is below mean
        // (consolidate the nearly-full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // Mild penalty for spreading across many open bins early on.
        score += open_bins_count as f64 * 0.5;
    }

    // Time horizon: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Normalized post-residual
    let p = post / cap;

    // Non-linear polynomial coupling: dead space penalized super-linearly,
    // with stream-progress-dependent weighting (tight packing matters more late).
    let poly = p * p * (1.0 + 3.0 * progress) - 2.0 * p * (1.0 - progress);

    let mut score = post + 40.0 * poly;

    // Reward near-perfect fits smoothly via gaussian-like term on post_residual.
    let tight = (post / cap - 0.08).powi(2);
    score -= 25.0 * (-tight * 40.0).exp();

    // Lookahead: strongly favor bins whose post-residual accommodates next item.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 + 8.0 * (1.0 - (next_item_size as f64 / post));
    } else if next_item_size > 0 {
        // Waste: next item can't fit here; penalize proportionally to leftover gap
        score += 6.0 * (1.0 - (post / (next_item_size as f64))).max(0.0);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure against spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    // Pull toward mean residual to keep bin states balanced.
    score += 0.05 * (mean_residual - post);

    // New-bin candidate: prefer it only when it's genuinely better (large item,
    // no good fit elsewhere). Penalize slightly so open bins win on equal footing.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/2, 1/3, 1/4 of C)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Dead-space penalty: residuals that are too small to hold typical items
    if post_residual < quarter {
        score += 60.0;
    } else if post_residual < third {
        score += 20.0;
    } else if post_residual < half {
        score -= 5.0;
    } else {
        score -= 15.0; // large residual is reusable
    }

    // Harmonic reward: post_residual exactly on a "nice" fraction
    if post_residual == half || post_residual == third || post_residual == quarter {
        score -= 25.0;
    }

    // Modulo class: residuals divisible by 10 pair well with item sizes 10..80
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect pairing: next item exactly fills or nearly fills
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 45.0;
            } else if gap < quarter {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize more if residual becomes dead space
            score += 10.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 1.5;
    }

    // Prefer bins below mean residual (already tight bins keep tightness)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early in stream: be picky, prefer best fits; late: just fill anything
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.3 * progress;

    // New-bin candidate: make empty bins moderately attractive only when
    // placing here would leave bad dead space
    if bin_residual == bin_capacity {
        let dead = post_residual < quarter;
        if dead {
            score += 40.0; // opening fresh bin is better than wasting this one
        } else {
            score += 25.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Reward tightness relative to bin capacity.
        score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;
    }

    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving space exactly usable by the next item.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 1.2 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Mild stream progression: later items favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (residual fully consumed)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does post_residual match the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly into the leftover: excellent chain
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 60.0 - 0.6 * gap;
        } else {
            // Next item does NOT fit in leftover: penalize creating dead space
            // proportional to how far off the fit is
            let miss = next_item_size as f64 - post_residual as f64;
            score += 0.8 * miss;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far below the mean
    // are "tight" — using them is valuable; bins far above mean are loose and
    // can absorb this item instead.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the ONLY fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize wasting a very tight bin on a small item (poor utilization)
    if (item_size as f64) < 0.5 * bin_residual as f64 && bin_residual < 60 {
        score += 15.0;
    }

    // Late in the stream: prefer closing bins out (favor tighter fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * (post_residual as f64);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base penalty so open bins win unless they're bad fits
        score += 120.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // If current item barely fits anywhere, opening fresh is fine
        if post_residual > 0 && post_residual < 20 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste-based reward).
    let waste = post_residual as f64;
    score -= (bin_capacity as f64 / (1.0 + waste)) * 2.0;
    if post_residual == 0 {
        score -= 40.0; // perfect fit bonus
    }

    // Penalize dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and many bins are open with high mean residual fragmentation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 10.0 * fragmentation / (bin_capacity as f64)
                 - 5.0 * (1.0 - progress);
        // encourage new bin late in stream if mean residual is low
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Global balance: prefer bins below mean residual (keeps residuals even).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post residual
    let x = pr / cap;

    // Base: reward small post_residual (tight fits), non-linearly
    let mut score = x * x * 40.0 + x * 10.0;

    // Smooth stream-progress coupling: early on tolerate loose fits, later demand tightness
    score += (1.0 - progress) * x * 15.0;
    score -= progress * (1.0 - x) * 12.0;

    // Penalty for dead space that next item can't use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = (x - nx).max(0.0);
        score += waste * waste * 60.0 * (0.5 + progress);
        // Reward when next item exactly complements this residual
        score -= (1.0 - (x - nx).abs() * cap / 10.0).max(0.0) * 8.0;
    } else {
        // Last item: strongly prefer tightest fit
        score -= (cap - pr) * 0.5;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mild penalty when many bins are open (consolidation pressure)
    score += open_bins_count as f64 * 0.3 * x;

    // Deviation from mean residual: prefer bins near mean to keep balance
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev.abs() * 6.0;

    // New-bin candidate: neutral-ish score so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = 45.0 - progress * 10.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer-division thresholds
    // into "dead space" bands relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: near-perfect fit (post_residual tiny) -> strong reward.
    if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 25 {
        score -= 5.0;
    } else if post_residual <= 40 {
        // mid-band: residual may still host small items -> mild penalty
        score += 3.0;
    } else {
        // large leftover: wasteful unless item was tiny
        score += 8.0;
    }

    // Modulo-arithmetic harmonic classes on post_residual:
    // residuals divisible by common item sizes (10, 20, 25, 50) are reusable.
    let pri = post_residual;
    if pri > 0 && (pri % 10 == 0 || pri % 25 == 0) {
        score -= 6.0;
    }
    if pri >= 10 && pri % 20 == 0 {
        score -= 3.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item slots perfectly -> reward, scaled by how snug
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 - snug * 0.3;
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; if post_residual is a dead zone
            // (smaller than min plausible item), penalize more.
            if post_residual < 10 {
                score += 10.0;
            } else {
                score += 4.0;
            }
        }
        // Harmonic class of next item vs residual divisibility
        if next_item_size > 0 && pri % next_item_size.max(1) == 0 && pri >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // unless post_residual would be terrible dead space.
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 10.0; // nearly full anyway, great
        }
    } else if fitting_bins_count > 1 {
        // many options: prefer tighter fits, mild spread penalty
        score += (fitting_bins_count as f64).min(6.0) * 0.8;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad
    // or stream is early (building inventory of bins can help).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // baseline score for a fresh bin: its residual equals capacity
        let base = cap * 0.35;
        // early stream: slightly favor opening bins to diversify residuals
        let early_bonus = (1.0 - progress) * 12.0;
        // penalize new bin when many bins already open (avoid bin explosion)
        let open_penalty = (open_bins_count as f64) * 1.5;
        // if next item is huge, a fresh bin is valuable
        let big_next = if next_item_size >= 60 { 15.0 } else { 0.0 };
        score = score.max(base) + base * 0.0 + base + early_bonus + big_next - open_penalty;
        // if the current bin would leave great post_residual, new bin loses
        if post_residual <= 10 {
            score += 50.0;
        }
        return score;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average)
    let dev = mean_residual - pr;
    score += dev * 0.25;

    // Slight preference for filling older bins as stream progresses (first-fit flavor)
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are almost unusable
    // since items are >= 1 but typically larger; punish them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 11.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 11.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits proportionally.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when it enables a much better
    // future fit (lookahead) or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let lookahead_help = if next_item_size > 0 && next_item_size <= item_size {
            0.0
        } else {
            20.0
        };
        score += 45.0 + 0.5 * open_bins_count as f64 + lookahead_help
            - 0.2 * fragmentation;
        // Late in the stream, avoid spawning bins with big leftover space.
        score += 30.0 * progress;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chains two items nicely).
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 18.0;
    }

    // Mild preference for bins already below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin's post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 - leftover * 0.8;
    }
    // Next item does NOT fit the leftover: dead space penalty, scaled by how
    // close the next item comes to filling the residual (wasted potential).
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Favor tight fits in general: small post_residual is good, but avoid
    // unusable slivers (< 10) that can never host any item.
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Relative residual coupling: bins with residual near the mean are
    // "average" candidates; prefer bins tighter than the mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to open new bins (plenty of
    // future items to fill them); late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize less early on, more later.
        score += 10.0 + 30.0 * progress;
        // Opening a new bin is attractive if no open bin gives a good fit
        // (large post_residual relative to mean).
        if post_residual as f64 > mean_residual + 25.0 {
            score -= 20.0;
        }
    }

    // Slight consolidation pressure when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual < 10 {
        score -= 25.0; // perfect fill bonus
    } else if post_residual <= 15 {
        score += 12.0; // awkward dead zone
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bin is a very poor fit
    // or the item barely fits anywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fit_ratio < 0.35 {
            score += 60.0; // plenty of good fits exist elsewhere
        } else {
            score -= 10.0; // poor fit: opening a fresh bin is reasonable
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward if post residual is a near-perfect match for the next item
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 10.0 * (1.0 - slack / 10.0);
            }
        } else {
            score += 6.0; // next item won't fit here afterward
        }
    }

    // Global state: with many open bins, prefer consolidation into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.15 * congestion;
    score -= 10.0 * (1.0 - progress); // early on, be slightly more exploratory (favor tight fits less)

    // Mean-residual alignment: prefer bins close to the mean residual (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, smoothly warped by stream progress.
    // Early: prefer tight fits (low post_residual) strongly.
    // Late: slightly more tolerant of residual to keep bins flexible.
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - progress) * 2.0);

    // Non-linear polynomial coupling of residual with progress:
    // penalize mid-range residuals quadratically, weighted by progress.
    let mid = pr_norm * (1.0 - pr_norm); // peaks at 0.5 residual
    score -= 14.0 * mid * (1.0 - progress) * (1.0 - progress);
    score += 8.0 * pr_norm * pr_norm * progress;

    // Dead-space penalty: residuals too small to be useful later
    let min_useful = (next_item_size as f64).max(10.0);
    if (pr as f64) < min_useful && pr > 0.0 {
        score += 6.0 * (1.0 - pr as f64 / min_useful) * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual fits the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as f64 >= n {
            score -= 5.0 * (1.0 - (pr as f64 - n) / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 3.0 * (n - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.3 * progress);
    }

    // Relative tightness: reward filling a large fraction of current residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill * (1.0 - progress);

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * pr_norm * (1.0 - progress);

    // Prefer bins with residuals below the mean (tighter packing).
    score += 2.0 * (pr as f64 - mean_residual) / cap;

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        score = cap * (0.9 + 0.4 * progress) - 20.0 * scarcity - 8.0 * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues grouped by quarter-capacity bands
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class

    // Reward tight fits (low class = small leftover)
    score -= (4 - class.min(4)) as f64 * 8.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 unknown dist)
    // Use modulo harmonic: leftover in [1, 10] is often unusable unless next item fits
    if post_residual > 0 && next_item_size > post_residual {
        // leftover can't take the lookahead item: penalize proportionally to class
        score += class as f64 * 2.5;
    }

    // Lookahead harmony: if next item exactly fills post_residual, big reward
    if next_item_size == post_residual && post_residual > 0 {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward based on how harmonically it divides leftover
        let div = post_residual / next_item_size.max(1);
        score -= (div.min(4) as f64) * 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make fresh bin moderately expensive so we prefer
    // good fits into open bins, but cheap when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.85;
        // cheaper to open a new bin when many bins are open with large mean residual
        // (fragmentation) or when this item is huge relative to capacity
        score -= (open_bins_count.min(10) as f64) * 0.5;
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        // if the only alternative bins would leave big dead space, new bin is fine
        if mean_residual > cap * 0.5 {
            score -= 10.0;
        }
    }

    // Progression coupling: late in the stream, tighten packing (favor existing bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    // Mean residual coupling: placing into a bin with residual far below mean
    // consolidates space; reward that
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap too small for the smallest plausible item => dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Penalize gaps that cannot fit the known next item (lookahead-aware).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: discourage spreading across many bins; but if this is
    // the only fitting bin, reward using it to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate: penalize opening a fresh bin unless current bin would
    // leave bad dead space. Empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, reduced when item is large (efficient packing).
        let mut new_bin_cost = 30.0;
        if item_size >= 50 {
            new_bin_cost -= 10.0;
        }
        // If the alternative would leave unusable dead space, opening is better.
        if post_residual > 0 && post_residual < 10 {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost;
    }

    // Mild stream-position scaling of dead-space penalties.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if the next item still fits tightly (post_residual close to next_item_size).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 25.0 / (1.0 + gap);
        // Penalize leaving residual too small for the next item (dead space risk).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize post residual that deviates from mean residual (keep residuals uniform/combinable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in the stream
    // or when this placement leaves large unusable residual in an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            post_residual as f64
        } else {
            0.0
        };
        // Prefer existing bins unless waste is large; new bin slightly favored early.
        score = 100.0 - waste * 0.5 - (1.0 - progress) * 5.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to ever hold a future
    // item (smallest item size is 1, but tiny slivers are still wasteful).
    if post_residual > 0 {
        let dead = 1.0 - (post_residual as f64 / 50.0).min(1.0);
        score += 8.0 * dead;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus;
    // if the next item fits, moderate bonus; if not, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 4.0 * (waste / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage it
    // unless the current fit is terrible or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // A new bin costs ~1 unit; make its baseline score sit above good fits.
        score += bin_capacity as f64 * 0.5;
        // Early in the stream, opening bins is cheaper (builds a portfolio);
        // late in the stream, pack tighter.
        score -= 30.0 * (1.0 - progress);
        // If many bins are already open, reuse them instead.
        score += 3.0 * open_bins_count as f64;
        // If the mean residual is large, open bins have room; reuse instead.
        score += mean_residual * 0.5;
    } else {
        // Slight preference for reusing bins with lower residual (best-fit bias
        // is already in post_residual, add a nudge toward consolidation).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Progress-based tightening: as the stream advances, weight residual waste more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping (quartic coupling)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: post_residual shaped by stream progress (later => tighter packing)
    let progress_shaping = 1.0 - 0.5 * progress * (1.0 - norm_pr);
    score *= progress_shaping;

    // Non-linear penalty for small post-residuals scaled by progress (dead space)
    score += (1.0 - norm_pr).powi(3) * cap * (0.15 + 0.35 * progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward if next item fits the post-residual (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = pr - nx;
        if fit_margin >= 0.0 {
            score -= 6.0 * (fit_margin / cap);
        } else {
            score += 4.0 * (-fit_margin / cap);
        }
    }

    // Mild diversity pressure via mean residual (smooth quadratic)
    score += 0.05 * (mean_residual - pr).powi(2) / cap;

    // Slight preference for consolidating into fewer bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into
    // "harmonic" buckets (multiples of small divisors of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit: strongly reward zero / tiny residual.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 2 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Harmonic class penalty: residual that divides capacity evenly (or
    // is a small multiple of a common item size class) is more likely to
    // be filled later, so penalize it less.
    let harmonic = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
    if harmonic {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Dead-space zone: residuals that no item (1..=100) can use well.
    // A residual of 1..=9 is nearly dead unless a future tiny item comes.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, this is a harmonic pair -> reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let after2 = pr - next_item_size;
            // reward tight second fit
            if after2 <= 5 {
                score -= 18.0;
            } else if after2 < 10 {
                score -= 10.0;
            }
            // harmonic alignment of pair
            if (next_item_size + pr) % 50 == 0 || (next_item_size + pr) % 100 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; if this bin was the only fitting
            // one, closing it with minimal waste is fine; otherwise the
            // leftover class matters.
            let waste_class = pr / 10; // integer division threshold
            score += waste_class as f64 * 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * prf;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is bad. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if item is large and would leave a harmonic residual, ease it.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // Early in the stream, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (good packing density).
    score += (mean_residual - prf).max(-30.0).min(30.0) * 0.15;

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A gap is "dead" if no plausible future item (1..=100, min observed 1)
    // can be assumed to fit; treat residual < 10 as pure waste, and
    // penalize quadratically as the gap shrinks toward zero.
    let gap = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - gap) * (10.0 - gap) * 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 25.0;
    } else {
        // Larger usable gaps are mildly favored proportionally to utility.
        score -= gap * 0.1;
    }

    // Dead space relative to what the next item could use:
    // if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // next item can still go here: keep this bin attractive
            score -= (gap - nxt).abs() * 0.5;
        } else {
            // leftover cannot host the next item: penalize proportionally
            score += nxt * 0.3;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize candidates that keep bins open.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 0.05 * (gap / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual deviates favorably
    // (smaller residual than mean), reward consolidation.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.2;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: empty bin should only win when the fit is bad.
    // Penalize the fresh empty bin unless post_residual is very tight.
    if bin_residual == bin_capacity {
        score += 8.0 + gap * 0.05;
    }

    // Slight stream-position scaling: early on, be more tolerant of gaps
    // (more future items to fill them); late, be strict.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += gap * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills, penalize dead space quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            if diff < 0.5 {
                score -= 60.0; // perfect chain: next item fills this bin exactly
            } else {
                score -= (bin_capacity as f64 - diff) / bin_capacity as f64 * 25.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += (nxt - post_residual as f64) * 0.8;
        }
    }

    // Relative-to-mean-residual coupling: bins far below mean residual are
    // "hard to fill later"; reward placing into them now.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when current bins are nearly
    // full on average (mean residual small) or item is huge.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = mean_frac * 0.5 + item_frac * 0.9;
        score = 5.0 + pressure * (bin_capacity as f64 - item_size as f64);
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64 - item_size as f64) {
            score -= 30.0; // fresh bin can also host the next item
        }
    }

    // Slight stream-progression tilt: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    }

    // Tightness ratio: favor bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 120.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly-full bin on a small item.
    let waste = bin_residual - item_size;
    if (item_size as f64) < 0.4 * bin_residual as f64 && bin_residual < bin_capacity {
        score += 40.0;
    }

    // Global state coupling: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = (open_bins_count as f64 / 20.0).min(3.0);
    score -= crowd * 15.0 * (1.0 - progress);

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // more so early in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual == bin_capacity as f64 { 0.0 } else { 0.0 };
        // base cost of a new bin; discount late in stream when consolidation matters less
        let mut new_bin_score = 300.0 + 5.0 * open_bins_count as f64;
        new_bin_score -= 200.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host both item and next item comfortably
            if item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
                new_bin_score -= 120.0;
            }
        }
        if fitting_bins_count <= 1 {
            new_bin_score += 250.0; // opening new bin rarely helps when few alternatives
        }
        score = score.max(score) ; // no-op to keep types happy
        return new_bin_score + poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
