    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (<10, the
    // minimum plausible item size), heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward very tight fits (small positive residual) but not exact fills
    // that waste a large item slot.
    if post_residual > 0 && post_residual < 15 {
        score -= 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 35.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as f64) > 0.0 && (post_residual as f64) < next_item_size as f64 {
        score += 15.0; // creates dead space for the known next item
    }

    // Prefer bins with residuals below the mean (compact them), keep large
    // residual bins available.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Early stream: be more conservative about wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect 2-step matches.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect pair: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits afterwards: good lookahead match.
            let slack = post_residual - next_item_size;
            score -= 40.0 - (slack as f64).min(35.0);
        } else {
            // Next item won't fit: dead space penalty scaled by gap.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: prefer minimal waste.
        score += (post_residual as f64).powi(2) / 100.0;
    }

    // Compare post_residual against mean residual: leaving this bin far below
    // mean residual creates fragmentation; leaving it near mean is neutral.
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.15;
    } else {
        score += diff.abs() * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10).
    if post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    // Prefer filling existing bins over opening new ones, unless residual is large
    // and item is small (poor fit into a mostly-empty bin).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is huge relative to capacity
        // or existing bins are too fragmented.
        score += 15.0;
        if item_size >= 80 {
            score -= 30.0;
        }
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else if open_bins_count > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimizing post_residual, with a mild quadratic penalty
    // on dead space so small residuals are favored disproportionately.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward for near-exact two-item packing.
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space the next item cannot use: penalize, scaled by how
        // large the next item is relative to the gap.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins when mean residual is tight and many bins
    // are open; prefer opening a new bin when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin, adjusted by global state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / (bin_capacity as f64)
        } else {
            0.0
        };
        // Penalize new bin when existing bins have plenty of room.
        score += 30.0 + fragmentation * 40.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            // Large next item: a fresh bin is more attractive.
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;

        // Reward using bins with below-average residual (consolidate space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild late-stream conservatism: reduce new-bin tendency as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr - 0.5 * progress * progress);

    let mut score = poly * cap;

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (1.0 + progress);
        } else {
            score -= (pr - ni).min(20.0) * 0.3;
        }
    }

    // Last-chance bin bonus: strongly prefer using a lone fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight preference for consolidating into fewer bins early on
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Prefer bins tighter than the mean residual (better fill)
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild penalty for very tight fits creating unusable slivers
    if norm_pr < 0.1 && norm_pr > 0.0 {
        score += 3.0 * (0.1 - norm_pr) * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in reusable bands.
    // Class 0: post_residual == 0 (perfect fill) -> huge reward.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Small dead space (< 10) is nearly unusable -> penalize.
        if post_residual < 10 {
            score += 40.0;
        }
        // Modulo-10 band structure: residuals that are multiples of 10
        // align with typical item sizes (10..80 multiples) -> reward.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        // Quarter-band classes of capacity fraction.
        let frac = post_residual as f64 / cap;
        if frac > 0.5 {
            score -= 10.0;
        } else if frac > 0.25 {
            score -= 3.0;
        } else {
            score += 8.0; // tight leftover, risk of dead space
        }
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Great: this bin can also host the next item.
        score -= 25.0;
        // Extra reward if next item exactly fills the bin afterwards.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize proportionally to waste.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity,
    // post_residual == capacity - item_size.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current open bins are
        // fragmented (high mean residual spread) or few bins fit.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative -> new bin fine
        } else {
            score += 15.0; // prefer reusing an open bin
        }
        // Penalize opening new bins early in the stream when bins are plentiful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        // Small dampening by fragmentation signal.
        score -= fragmentation * 0.05;
    }

    // Mild pressure toward bins with above-average residual (consolidate slack).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 3.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Penalize large leftover only mildly; small leftovers are the danger.
    score += (post_residual as f64).powi(2) * 0.01;

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter fill).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Exact match for next item => strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits in the leftover: reward proportionally to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize.
            score += 15.0 * (1.0 - (post_residual as f64) / nxt);
        }
    } else {
        // Last item: prefer minimal residual (best fit).
        score += 10.0;
    }

    // Reward tight fits of the current item relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize bins far below mean residual (they are outliers wasting space),
    // unless this is a last-chance bin.
    if fitting_bins_count == 1 {
        score -= 40.0; // strongly favor using the only bin that fits
    } else {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.15 * dev;
        }
    }

    // Late in the stream, consolidate: favor existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive early or when item is large.
        score += 30.0 + 40.0 * progress - 15.0 * fill_ratio;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space that the next item can still use.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling existing bins as much as possible.
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild reward when many bins compete (more options, keep packing dense).
    if fitting_bins_count > 2 {
        score -= 3.0;
    }

    // Penalize bins that are far below the mean residual (wasteful usage of a fresh bin)
    // and reward bins already fragmented (near mean).
    score += 0.12 * (mean_residual - bin_residual as f64);

    // Time-horizon modulation: early in the stream, be conservative about
    // opening new bins; late in the stream, prioritize finishing tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is huge relative to
    // residual and no bin fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 55.0 * scarcity - 40.0 * big_item * big_item;
        score += 2.0 * open_bins_count as f64 * 0.5; // mild penalty for bin proliferation
    }

    // Small bonus for perfectly filling a bin.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap) / cap;
        let gap = (pr_norm - nx).max(0.0);
        score += 1.5 * gap * gap;
        // Reward when post residual exactly accommodates next item
        let tight = 1.0 - (pr_norm - nx).abs() / cap;
        score -= 0.5 * tight * tight * pr_norm;
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - pr_norm);
    }

    // Slight preference for bins deviating from mean residual (balance residuals)
    let dev = (pr - mean_residual) / cap;
    score += 0.2 * dev * dev;

    // Mild penalty for bin proliferation early in the stream
    score += 0.01 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Perfect fit: post_residual in {0} is ideal; tiny residuals (<5) are nearly ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Modulo classes: residuals divisible by 10 align with item granularity (sizes 1..100,
    // commonly multiples of 10) -> more likely to be filled exactly by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }
    // Odd/prime-ish residuals are hard to fill: penalize.
    if post_residual % 2 == 1 && post_residual > 10 {
        score += 4.0;
    }

    // Integer division thresholds: residual bands relative to typical item sizes.
    let band = post_residual / 20; // 0..5 bands of width 20
    score += band as f64 * 6.0;    // larger leftover bands are worse

    // Lookahead coupling: can next item exactly fill the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let nxt_frac = next_item_size as f64 / post_residual as f64;
            if nxt_frac > 0.8 {
                score -= 20.0;
            } else if nxt_frac > 0.5 {
                score -= 8.0;
            }
            // harmonic class match between next item and residual
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item can't use this residual at all: dead space likely persists
            score += 5.0 + frac * 10.0;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score += frac * 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Mean residual coupling: placing into a bin below-mean residual keeps spread even.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it mildly attractive
    // only when the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        if big_item > 0.6 || next_item_size == 0 {
            score -= 10.0;
        } else {
            score += 12.0; // prefer existing bins for small/medium items
        }
    }

    // Stream progression: late in the stream, tighten packing harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * (10.0 + 20.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are "dead space". Penalize hard.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.05 * pressure * (1.0 - tightness);

    // Mean-residual coupling: if the mean residual across bins is large,
    // opening another bin is wasteful; favor bins that reduce spread.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * spread;

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the lookahead item: dead space for the future.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core lookahead: reward when next item fits perfectly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize wasted space
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Relative to mean residual: prefer bins deviating so mean residual shrinks
    score += 0.3 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible or no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 40.0 - 25.0 * poor_fit;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items,
    // but reward residuals that could still hold a mid-size item.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // unusable sliver
    } else if pr >= 10.0 && pr < 30.0 {
        score += 4.0; // awkward gap
    } else if pr >= 30.0 && pr <= 60.0 {
        score -= 3.0; // still useful
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 8.0; // chainable
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
        // Mild reward if next item fits current bin too (keep big bin for it)
        if bin_residual >= next_item_size + item_size {
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing residuals are poor fits or many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        score += 45.0 - 20.0 * pressure - mean_fit * 0.15;
        // Late in the stream, prefer consolidating into open bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * t;
        // If item would leave a very usable residual in a fresh bin (large item), slightly favor it.
        if item_size >= 50 {
            score -= 5.0;
        }
    }

    // Slight preference for bins with residuals below the mean (consolidate small bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Normalized post-residual, polynomially coupled with stream progress
    let x = pr / cap;
    let p = progress * (1.0 - progress) * 4.0; // peaks at 1.0 mid-stream

    let mut score = pr as f64;
    // Non-linear polynomial coupling: tight fits (small post_residual) rewarded more as stream progresses
    score -= p * (1.0 - x) * (1.0 - x) * 12.0;
    score += p * x * x * x * 18.0; // penalize large dead space super-linearly
    // Smooth interaction with item size: bigger items prefer tighter bins
    score -= (item / cap) * (1.0 - x) * 6.0;
    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 8.0 + p * 6.0;
    }
    // Lookahead: reward residual that can still host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0;
        }
    }
    // Mild deviation from mean residual (prefer bins near average residual)
    score += 0.3 * ((pr - mean_residual) / cap).abs();
    // Slight openness penalty late in stream to consolidate bins
    score += progress * open_bins_count as f64 * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;           // 0..10
    let next_class = (next_item_size as u32).min(bin_capacity) / 10;

    // Post-residual harmonic class: bins partitioned by residual buckets of 10
    let post_class = post_residual / 10;

    // Reward tight fits: post_residual in the lowest classes is excellent.
    // Use quadratic growth so dead space is punished super-linearly.
    score += (post_residual as f64) * (post_residual as f64) / cap;

    // Perfect-fit bonus: post_residual <= 5 is essentially a closed bin.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Modulo-10 coupling: if the leftover can pair with a common small item
    // class (residual mod 10 == 0 means it can host multiples of 10 exactly),
    // reward it; odd leftovers waste space.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m == 5 {
        score -= 3.0;
    } else {
        score += m as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportional closeness of the fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // Harmonic class match: next item in same decade class as residual
            if next_class == post_class && post_class > 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales down late in the stream
        // (fewer chances to consolidate) and with many already-open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - 40.0 * progress - (open_bins_count as f64).min(10.0);
        // If the item is large and would leave a well-usable residual, opening
        // a fresh bin is more attractive.
        if item_size >= 50 {
            score -= 5.0;
        }
    } else {
        // Prefer bins whose residual is below the mean (consolidate fuller bins)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += ((bin_residual as f64) - mean_residual) * 0.2;
        }
    }

    // Small item class penalty: placing tiny items into big residuals wastes
    // the bin's potential; nudge toward bins with small residuals.
    if item_class <= 2 {
        score += (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item (min size 1..10, or the
    // lookahead item) can use are worthless. Penalize them heavily.
    let min_item = 10.0f64.min(bin_capacity as f64);
    if (post_residual as f64) < min_item {
        score += 40.0; // unusable sliver
    }
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0; // gap can't serve the lookahead item
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or open-bin pressure is high; otherwise discourage it.
    if bin_residual == bin_capacity {
        score += 12.0;
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        score += 1.5 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // which correlates with using bins with above-mean residual less.
    if open_bins_count > 4 && bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
