pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good, zero is perfect).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that nothing can ever use (min item size is small).
        // Waste fraction of the bin.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste_frac * waste_frac;
    }

    // Exact-fit lookahead: if next item exactly fills the post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0; // next item can also go here, mild bonus
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 10.0; // near-perfect last-chance fit
        }
    }

    // Many open bins: prefer consolidating into existing bins to avoid sprawl.
    let open_pressure = open_bins_count as f64;
    score -= 0.5 * (open_pressure.ln() + 1.0) * (item_size as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residual close to item_size are ideal.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    // Time horizon: early in the stream, be conservative (favor new bins for
    // large items to keep flexibility); late in the stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
    if big_item && progress < 0.3 {
        score += 8.0 * (1.0 - progress);
    } else if big_item && progress > 0.7 {
        score -= 6.0 * progress;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin: moderate, so that good fits in
        // existing bins (low post_residual) beat it, but poor fits don't.
        score += 30.0;
        // Opening a new bin is more attractive when few bins are open or when
        // the item is large and the stream is early (flexibility matters).
        if open_bins_count < 3 {
            score -= 10.0;
        }
        if big_item && progress < 0.5 {
            score -= 12.0 * (1.0 - progress);
        }
        // If existing bins are all nearly full (low mean residual), new bin is fine.
        if mean_residual < item_size as f64 * 1.5 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post-residual with smooth polynomial shaping (prefer tight fits)
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Smooth coupling of post-residual with stream progress:
    // early on, tolerate residual slack; late, penalize it more (smooth ramp)
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Non-linear interaction: item size vs residual (reward filling large fraction)
    score -= 20.0 * item_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: reward leaving space that still fits the next item,
    // penalize residual too small for next item (smooth quadratic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (nxt / cap) * (1.0 - pr_norm);
        } else {
            score += 15.0 * ((nxt - pr) / cap) * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to use it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, favor best-fit discrimination
        score += 2.0 * ((fitting_bins_count as f64).ln());
    }

    // Mean residual coupling: prefer bins close to mean residual (smooth)
    let diff = (pr - mean_residual) / cap;
    score += 8.0 * diff * diff * (0.5 + progress);

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo 10 classes
    let pr = post_residual;
    let class = pr % 10;
    // Penalize "dead-zone" residuals that few item sizes can fill (sizes 1..100)
    // Residuals near multiples of 10 are more reusable.
    let harmonic_bonus = match class {
        0 => -6.0,
        1 => 4.0,
        2 => 2.0,
        3 => 1.0,
        4 => 0.5,
        5 => -3.0,
        6 => 1.5,
        7 => 2.5,
        8 => 3.5,
        _ => 4.5,
    };
    score += harmonic_bonus;

    // Integer-division thresholds: post_residual / item_size ratio
    let ratio = (pr as f64) / (item_size as f64).max(1.0);
    if ratio < 0.25 {
        score += 8.0; // nearly exact fit wasted? no: small post residual is good
    }
    // Actually small post_residual is good; correct direction:
    if pr <= 5 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr > 50 {
        score += 6.0;
    }

    // Lookahead coupling: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 5.0; // keeps chain alive
            // harmonic match: next_item_size mod 10 == pr mod 10
            if next_item_size % 10 == pr % 10 && pr % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.15; // dead space for next item
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: only prefer when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        score = 60.0 + pressure * 0.2 - (fitting_bins_count as f64) * 3.0;
        if item_size >= 70 {
            score += 5.0; // big items fine in fresh bin
        }
        if pr == 0 {
            score -= 12.0; // perfect fill
        }
    }

    // Fraction of capacity used
    let used_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= used_frac * 10.0;

    // Mild phase adaptation
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 2.0 - (mean_residual / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: dead space below the minimum plausible item size
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Strongly penalize leaving a gap that no future item can use well
    if post_residual > 0 && post_residual < item_size {
        score += (10 - post_residual.min(10)) as f64 * 2.0;
    }

    // Reward tight fits: exact fill is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fitting when this is the last fitting bin (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could still fit the item
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But allow new bin if current item is huge and would leave bad residue elsewhere
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.5 * open_bins_count as f64;

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits but not exactly: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack * 0.5;
        } else {
            // next item won't fit: penalize wasted residual
            score += post_residual as f64 * 0.3;
        }
    }

    // Compare against mean residual: bins with less residual than mean are tighter -> prefer
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening new bins when reasonable alternatives exist
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * 5.0;
        // but allow new bin if item is large relative to mean residual of open bins
        if (item_size as f64) > mean_residual {
            score -= 100.0;
        }
    }

    // Small bonus for tight fits relative to capacity
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual), with non-linear shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual < item_size {
        // Dead space smaller than the smallest plausible next item: mildly good.
        score -= 10.0;
    } else {
        // Post-residual could still host future items: penalize waste proportionally.
        score += 0.15 * (post_residual as f64 - item_size as f64);
