    // Lookahead coupling (k=2): if the next item fits the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0 + 0.25 * next_item_size as f64;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // Next item fits bin now but not after placing: slight penalty for blocking.
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the current
    // fit is terrible (large post_residual relative to item size) or no bin fits.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        let crowded = fitting_bins_count == 0;
        if poor_fit && !crowded {
            score -= 15.0; // prefer fresh bin over stuffing a bad fit
        } else {
            score += 45.0 + 0.3 * open_bins_count as f64;
        }
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
        score += 0.02 * open_bins_count as f64 * fit_ratio;
    }

    // Late stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;                          // normalized residual after placement
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = item_size as f64 / cap;

    // Smooth polynomial coupling: reward tight fits (small post_residual) with
    // a quartic decay, modulated by stream progress.
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Non-linear interaction between progress and residual: early on, tolerate
    // larger residuals; later, penalize them super-linearly.
    score *= 1.0 + 1.5 * progress * norm_post;

    // Reward bins that are well-filled relative to capacity (smooth cubic bonus).
    score -= 12.0 * fit_norm * fit_norm * fit_norm * cap * 0.1;

    // Last-chance bonus: strongly favor the only bin that fits (smooth, not piecewise).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (post - nxt).max(0.0) / cap;
        let waste = if post >= nxt { 0.0 } else { (nxt - post) / cap };
        score += 20.0 * waste * waste * 10.0;           // dead-space penalty
        score -= 8.0 * (1.0 - usable) * (1.0 - usable); // reward leaving a usable gap
    }

    // Slight preference to consolidate: fewer open bins favored mildly.
    score += 0.05 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins close to average fill state.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.5;

    // Harmonic class of post_residual: dead-space quality classes
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score -= 25.0; // near-perfect, unusable residue
    } else {
        // class by divisibility against common item sizes (harmonic classes)
        let mut harm: f64 = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50] {
            if pr % d == 0 {
                harm += 8.0; // residue still reusable by coarse classes
            }
        }
        score -= harm;
        // penalize residues in awkward middle band (35..65): hard to fill
        if pr > 34 && pr < 66 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size < pr {
            // harmonic compatibility: next item divides residue nicely
            if pr % next_item_size == 0 {
                score -= 30.0;
            } else {
                score -= (pr - next_item_size) as f64 * 0.4;
            }
        } else {
            // next item won't fit here: penalize leaving large residue
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // Integer-division threshold on bin fill fraction
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    let k = (fill * 4.0).floor() as i32; // quartile class
    score -= k as f64 * 6.0; // prefer filling fuller (later-quartile) bins

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only open when current fit is bad and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        // opening a new bin costs ~ its wasted space; compete against poor fits
        score = 55.0 + waste * 0.5 - progress * 20.0 - (open_bins_count as f64 * 1.5);
        if next_item_size > 0 && next_item_size <= item_size && item_size + next_item_size <= bin_capacity {
            score -= 25.0; // pair next item into fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    // Mean residual deviation: prefer bins below mean residual (fuller than average)
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (1..100 stream, but typical items >= 10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strongly discourage
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // marginal gap usable only by small items
    }

    // Reward near-perfect fits (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post gap,
    // this placement chains nicely; penalize when it clearly does not.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual {
            score += 8.0; // next item must go elsewhere anyway
        } else {
            let gap_after_next = post_residual as i64 - next_item_size as i64;
            if gap_after_next > 0 && gap_after_next < 10 {
                score += 10.0; // creates a future sliver
            } else if gap_after_next == 0 {
                score -= 30.0; // perfect chain fill
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; also discourage opening new bins.
    let open_pressure = (open_bins_count as f64).powf(1.3) * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += open_pressure * 2.0 + 10.0;
        // But if this bin is the last resort and residual is tiny, opening
        // a fresh bin is better than fragmenting.
        if fitting_bins_count == 1 && bin_residual < item_size + 10 {
            score -= 45.0;
        }
    } else {
        // Existing bin: reward when it is one of few options.
        if fitting_bins_count == 1 {
            score -= 35.0; // last chance before opening a new bin
        } else if fitting_bins_count == 2 {
            score -= 10.0;
        }
        // Favor bins with residual below mean (tighter bins first).
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.5;
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // filling bins completely to avoid leftover fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chains: next item can follow into this bin
            let next_tightness = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * next_tightness;
        } else {
            // Penalize leaving dead space that next item cannot use
            score += 25.0;
        }
    } else {
        // Last item: prefer minimal leftover
        score -= 10.0 * tightness;
    }

    // Compare against mean residual: bins with residual above mean are
    // "loose" bins; penalize wasting a large-residual bin on a small item
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score += 0.5 * (res_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res_f);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: default neutral-ish score; only attractive when
    // no open bin offers a good fit. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * (0.8 + 0.4 * progress);
        // Make new bin less attractive if next item is small enough to
        // pair with this one later anyway
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Slight preference to fill bins with fewer alternatives available
    if fitting_bins_count > 0 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item is wasted. Penalize residuals that no
    // future item (>=1) can usefully fill.
    let tight_fit_bonus = (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);
    score -= 12.0 * tight_fit_bonus;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves more slack: mild penalty vs exact
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin should only win when open
    // bins have poor fits. Make the empty bin moderately attractive by
    // default but push it away when tight fits exist elsewhere.
    if bin_residual == bin_capacity {
        // baseline: slightly worse than a decent fit
        score += 8.0;
        // late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // many open bins with large mean residual: prefer using them
        score += 0.05 * open_bins_count as f64 + 0.1 * mean_residual.max(0.0);
        // small items: cheap to place anywhere, discourage new bins
        if item_size <= 30 {
            score += 6.0;
        }
        // large items near capacity: a fresh bin is often the right call
        if item_size >= 60 {
            score -= 5.0;
        }
    }

    // Global state: penalize placements into bins whose residual is far
    // above the mean (keeps residuals homogeneous, easier to fill later).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Slight preference for bins with larger residual when the item is big,
    // to avoid fragmenting small bins.
    score -= 0.02 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: minimize post residual, with non-linear polynomial shaping.
    let mut score = post;

    // Smooth polynomial coupling with stream progress: later in stream,
    // small residuals become more costly (dead space grows in value).
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += progress_coupling * (pr * pr) * cap * 0.5;

    // Reward tight fits: subtract bonus peaking when post_residual is small.
    let tightness = (-pr * 4.0).exp();
    score -= tightness * cap * (0.3 + 0.4 * progress);

    // Penalize residuals that cannot fit the lookahead item (smooth hinge).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post) / cap;
        if gap > 0.0 {
            score += gap * gap * cap * (1.0 + progress);
        } else {
            // Reward bins that can host the next item too.
            score -= 2.0 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap as f64 * 0.6;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: make it moderately attractive only when open bins
    // would leave large dead space; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) + pr * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // remaining fraction of capacity

    // Dead-space penalty: residuals in (0, 10) are nearly unusable (min item = 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic bucket reward: residuals that are exact divisors / multiples of
    // common item sizes are highly reusable.
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        for d in [10u32, 20, 25, 50, 100] {
            if r % d == 0 && r > 0 {
                h += 8.0;
            }
        }
        h
    };
    score -= harmonic(post_residual);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // penalize leaving awkward slack relative to next item
            if slack < 10 {
                score += 12.0;
            }
            score -= harmonic(slack) * 0.5;
        } else {
            // next item won't fit here regardless; slight penalty for tiny residual
            score += frac * 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling fuller bins (tight packing) via capacity fraction term
    score -= (1.0 - frac) * 15.0;

    // Mild penalty when this bin is far below mean residual (fragmentation)
    if (pr - mean_residual).abs() > 30.0 {
        score += 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are bad
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64) * -8.0;
    }

    // Late-stream consolidation: fewer open bins is better near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size of 1..10 range) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small usable post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Penalize creating a gap that exactly blocks the next item's fit
    // but wastes more than needed.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a fresh empty bin should only win when it's clearly better.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin, modulated by
        // how crowded the current bin set is and how much residual is stranded.
        score += 30.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Existing bins get a mild bonus when many bins are open.
        score -= open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect chain: next item exactly fills post-residual -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // Next item cannot use this residual: penalize wasted potential,
            // scaled by how close the miss is.
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(50.0) * 0.4;
        }
