    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless the current item
    // is large (a big item seeds a useful bin) and existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 5.0;
        }
    }

    // Tight fits (small post-residual) are always good.
    if post_residual <= 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
