    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 20.0;
        // cheaper to open new bin early in the stream
        score -= 15.0 * (1.0 - progress);
        // expensive when many bins are already open and underused
        score += 0.3 * open_bins_count as f64;
        // if this bin is the only fitting option elsewhere, opening is fine
        if fitting_bins_count <= 1 {
            score -= 22.0;
        }
        // if next item is large and current bins are tight, new bin attractive
        if next_item_size > 60 && mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Slight bonus for balancing residuals toward mean (fragmentation control)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, keep slack flexible.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + 0.5 * progress) * cap;
    score += coupling;

    // Reward tight fits (small post_residual) increasingly as stream progresses.
    let tightness = (1.0 - pr_norm).powi(3);
    score -= tightness * cap * (0.3 + 0.7 * progress);

    // Lookahead: bonus if the next item can fit the post-residual (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx) / cap).max(0.0);
        let lookahead_bonus = fits_next * (1.0 - fits_next) * 4.0 * cap * 0.25;
        score -= lookahead_bonus;
    } else {
        // Last item: strongly prefer minimal post residual.
        score -= (1.0 - pr_norm) * cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.4 + 0.6 * progress);
    }

    // Mild penalty for bins far from mean residual (favor balanced filling),
    // damped as progress advances.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * (1.0 - progress) * 0.5;

    // Slight preference for using existing bins over opening new ones,
    // scaled by how many bins are already open (consolidation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 3
    let r10 = post_residual % 10;
    let r3 = post_residual % 3;

    // Dead-space penalty: residual below smallest plausible item is wasted
    if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Favor post_residuals in "harmonic" classes: multiples of 5 and 10 are reusable
    if r10 == 0 {
        score -= 8.0;
    } else if r10 == 5 {
        score -= 4.0;
    } else if r10 == 1 || r10 == 9 {
        score += 6.0; // nearly-full classes -> awkward
    }

    // mod-3 coupling with next item
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly into this bin's remainder -> strong reward
        if next_item_size == post_residual {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
        // exact divisibility harmony
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving this bin as the blocker
        score += 4.0;
    }

    // Integer division threshold on post_residual quarters
    let q = post_residual / 25;
    score -= match q {
        0 => -3.0, // very tight bin, good if it closes
        1 => 2.0,
        2 => 0.0,
        _ => 3.0,  // nearly empty bin: prefer filling elsewhere
    };

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let base = cap * 0.55;
        score = base + 10.0 * (r10 as f64) / 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer closing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Tie-break toward tighter global state
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavy penalty for unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize wasting a large residual on a small item (poor utilization).
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.8;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: strongly reduce score as post_residual -> 0
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Penalize dead space relative to capacity: small leftovers are bad
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * 50.0;

        // 2-step lookahead: if next item fits exactly in post_residual, reward heavily
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else if post_residual >= next_item_size {
                score -= 30.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            } else {
                // next item won't fit here; penalize leftover waste
                score += 20.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless it's a great fit
    if bin_residual == bin_capacity {
        score += 150.0;
        // allow opening a new bin when item is large relative to residual capacity of others
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Late in stream, prefer closing bins tightly (fewer open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Penalize creating unusable dead space relative to the smallest possible item.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 150.0; // residual below min item size is wasted
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement enables a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual > next_item_size {
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 10.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Tightness relative to current residual: prefer bins where the item
    // consumes a large fraction of available space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio;

    // Compare against mean residual: placing into a bin far below mean residual
    // (a "loser" bin) is good consolidation.
    let diff = mean_residual - bin_residual as f64;
    score -= 15.0 * diff; // lower-residual bins get rewarded

    // Time horizon: early in the stream, be conservative about opening new bins
    // (many future items to fill them); late in the stream, prefer tight fits anywhere.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate logic: opening a new bin is attractive early or when
    // item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 120.0;
        let large_item_bonus = if item_size > 50 { 60.0 } else { 0.0 };
        let poor_alternatives = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // Cost of a fresh bin: it only pays off if post_residual leaves usable space
        let usable = if post_residual >= 10 { 0.0 } else { 400.0 };
        score += 100.0 - early_bonus - large_item_bonus - poor_alternatives + usable;
        // With many open bins, discourage spreading further unless necessary.
        score += 5.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild penalty for bins that would be left with awkward mid-range residual
    // (hard to fill later).
    if post_residual > 25 && post_residual < 45 {
        score += 20.0 * progress;
    }

    // Slight preference for keeping number of open bins low late in the stream.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = x;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer tight fills (waste matters less), late, penalize waste more.
    let progress_waste = x * x * (0.5 + progress) * cap * 0.1;
    score += progress_waste;

    // Reward near-perfect fits with a smooth bump around x = 0.
    let fit_bump = -(1.0 - x).powi(8) * (1.0 + progress);
    score += fit_bump * 5.0;

    // Last-chance bin: strongly favor using it (penalize alternatives implicitly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress - x; // x = 1 here
    }

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let lookahead_fit = (1.0 - (nx - x).abs()).max(0.0);
        score -= 2.0 * lookahead_fit * lookahead_fit;
    }

    // Slight preference for bins already below mean residual (consolidation).
    score += (mean_residual - pr) * 0.05;

    // Scale by number of open bins: many open bins -> tighter packing preferred.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 and integer-division bands.
    let band = post_residual / 10;              // integer division band 0..=10
    let residue = post_residual % 10;           // harmonic residue class

    // Perfect-fit reward (post_residual == 0 is the ideal outcome).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post residuals strongly; penalize dead space superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic residue class: residues that combine well with typical item sizes
    // (multiples of 5 and 10) are favored for future packing.
    let residue_bonus: f64 = match residue {
        0 => 40.0,
        5 => 20.0,
        1 | 9 => 5.0,
        _ => 0.0,
    };
    score -= residue_bonus;

    // Band-based coupling: low bands (tight fit) get extra reward.
    score -= (10 - band.min(10)) as f64 * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (50.0 - slack.min(50) as f64) * 0.8;
        } else {
            // Next item cannot use the residual: penalize proportionally to waste.
            score += (next_item_size as f64 - post_residual as f64).min(80.0) * 0.5;
        }
    }

    // Compare against the mean residual: bins below mean are "denser" and preferred.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item fits none of them well.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 30.0;
        let poor_fit = fitting_bins_count == 0;
        if crowded || poor_fit {
            score -= 120.0;
        } else {
            // Discard fresh-bin temptation when decent fits exist; a fresh bin
            // has full residual so its raw score is already high, add a bit more.
            score += 60.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (better future structure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 30.0;
    }

    // Mild penalty for proliferating bins when plenty are already open.
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worthless.
    if post_residual > 0 {
        let r = post_residual as f64;
        // penalize gaps that are too small to hold even the smallest plausible item
        if r < 10.0 {
            score += 60.0 * (10.0 - r) / 10.0;
        }
        // penalize gaps that cannot fit the lookahead item (dead space relative to future)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // gentle convex penalty on any leftover
        score += 0.35 * (r * r) / (bin_capacity as f64);
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward using an existing bin when choices are scarce (avoid opening new bins).
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize mildly so it is chosen only when nothing else is decent;
        // but if no open bin fits, allow it (this call would then be the only one).
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Open-bin pressure: prefer consolidating into existing bins as bin count grows.
    score += 0.25 * open_bins_count as f64;

    // Tightness reward: filling a large fraction of the residual is good.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * gap;

    // Lookahead synergy: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how snug it is.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 50.0 * snug;
        } else {
            // Next item won't fit: penalize dead space creation.
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize large post-residuals relative to mean residual (wasteful gaps).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: only attractive if the item is large relative
    // to capacity or no good fits exist; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 150.0;
        } else {
            score += 120.0 + (1.0 - fill_ratio) * 100.0;
        }
    }

    // Mild encouragement to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small to hold even a typical item.
    if post_residual < 10 {
        score += 22.0;
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.7;
    }

    // Lookahead: if the next item would fit perfectly in the post-residual,
    // reward strongly; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 14.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins by default.
        score += 12.0;
        // But if many bins are open with scattered residual, opening fresh
        // can be better; scale penalty down with open bin count and mean residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // Penalize new bins more as the stream nears its end (waste).
        score += 15.0 * progress;
        // If mean residual is large, existing bins are roomy: prefer them.
        score += 0.08 * mean_residual;
        // If the current item is huge and next item is also huge, a fresh bin
        // may pair them well.
        if item_size > 60 && next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Mild preference to fill bins with larger residual when many bins open.
    score -= 0.02 * bin_residual as f64 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: residual value decays with progress
    score *= 1.0 + 0.35 * progress * (1.0 - progress) * 4.0 * norm_post * (1.0 - norm_post);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (30.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction)
    let wasted = ((post - norm_next * cap).max(0.0)) / cap;
    score += wasted * wasted * 60.0 * (0.5 + progress);

    // Reward bins whose residual matches the next item well
    if next_item_size > 0 && post >= next_item_size as f64 {
        let fit_gap = (post - next_item_size as f64) / cap;
        score -= (1.0 - fit_gap) * 25.0;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 30.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins with residual below mean (consolidate large gaps)
    score += (mean_residual - post) * 0.15;

    // Slight bias against opening a new bin, relaxing as stream progresses
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.5 * progress) + norm_item * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the item: coarse size buckets (integer division thresholds)
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;

    // Fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits strongly (harmonic coupling on fill fraction)
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to host typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Modulo arithmetic: post_residual in residue classes mod 10
    let mod_class = post_residual % 10;
    if mod_class == 0 && post_residual > 0 {
        score -= 6.0; // clean residual, easy to fill later
    } else if mod_class >= 7 {
        score += 4.0; // awkward sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0; // near-perfect two-item chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0 * (next_class as f64 - item_class as f64).abs().min(4.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive
    if is_new_bin {
        score += 55.0;
        // But if current item is huge and no good fit exists, allow opening
        if item_size > 50 && fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Few open bins with large mean residual -> new bin less attractive
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual is "dead" if it is smaller than the smallest plausible item (1..=100, assume ~10).
    let min_item = 10.0f64.min(bin_capacity as f64 * 0.1).max(1.0);
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 50.0; // unusable sliver -> strong penalty
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual as f64 <= min_item {
        score -= 10.0;
    }

    // Prefer bins whose residual tightly matches the item (small relative slack).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current fit is poor and bin is a last chance.
        score += pressure;
        if fitting_bins_count <= 1 {
            score -= pressure * 0.8;
        }
        // Lookahead: if next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && (next_item_size as f64) < mean_residual * 0.5 {
            score -= 5.0;
        }
    } else {
        // Reward using last-chance bins before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Mild preference toward bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportionally to how much of the post-residual is used
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * use_ratio;
            // extra bonus if the pair leaves a tiny remainder (tight 2-step packing)
            let chain_left = post_residual - next_item_size;
            if chain_left <= 5 {
                score -= 100.0;
            }
        } else {
            // next item cannot use the post-residual: penalize proportionally to wasted dead space
            let waste = next_item_size - post_residual;
            score += 50.0 + waste as f64;
        }
    }

    // Reward filling bins whose residual is below the mean (consolidating slack),
    // penalize draining bins that are already slack-rich.
    let diff = mean_residual - post_residual as f64;
    score += 0.5 * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 80.0 + post_residual as f64 * 0.3;
    }

    // Mild pressure to close out nearly-full bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Penalize leaving large dead space, non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Slight preference for keeping the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Penalize dead space: post residual that is too small for any plausible item (1..=100).
    if post_residual > 0 {
        // unusable sliver: nothing can fit (min item size 1) — only exact 0 is perfect
        if post_residual < 10 {
            score += 30.0 * (10.0 - post_residual as f64);
        } else {
            // medium dead space: hard for typical items to fill
            let mid = post_residual as f64;
            if mid > 20.0 && mid < 45.0 {
                score += 12.0 * (1.0 - ((mid - 20.0) / 25.0).abs());
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish: reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty for wasting the lookahead slot
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.75;
        // cheaper to open new bins early in the stream (plenty of future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
        // expensive if many bins already open and mean residual is large (fragmentation)
        score += 0.15 * open_bins_count as f64 + 0.5 * mean_residual;
        // if next item is large, a fresh bin is more valuable
        score -= 0.4 * next_item_size as f64;
        // if only one bin fits, prefer using it instead of opening new
        if fitting_bins_count <= 1 {
            score += 45.0;
        }
    } else {
        // mild preference for bins below mean residual (keeps balance)
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        }
    }

    // Time horizon: late in the stream, be greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress
    let mut score = r * (1.0 + 0.6 * progress * progress);

    // Penalize small dead space quadratically (wasted slivers), scaled by progress
    let dead = (rn * (1.0 - rn)).sqrt(); // peaks at rn=0.5, small near 0
    score += (1.0 - dead) * 25.0 * (0.5 + progress);

    // Reward tight fits: cubic reward as post_residual approaches 0
    score -= (1.0 - rn).powi(3) * 30.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward; otherwise penalize
    if next_item_size > 0 {
        if (next_item_size as f64) <= r {
            score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Coupling with mean residual: prefer bins close to mean residual (smooth quadratic)
    let diff = r - mean_residual;
    score += 0.05 * diff * diff / (1.0 + progress);

    // Slight preference for bins over new bins early; new-bin penalty grows late
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress * progress + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.1 * open_bins_count as f64 * (1.0 - rn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: size modulo capacity quarters
    let quarter = bin_capacity / 4; // 25
    let item_class = item_size % quarter;          // 0..24 residue class
    let next_class = next_item_size % quarter;

    // Reward bins whose post_residual lands in "harmonic" classes:
    // post_residual divisible by 10 or matching next item's class => likely future fit
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            // next item can follow into this bin: strong reward, especially exact harmonic match
            if next_class == item_class {
                score -= 6.0;
            } else {
                score -= 4.0;
            }
        }
    }

    // Penalize dead space: post_residual too small for the smallest plausible item (1..=100)
    // but keep granularity: thresholds at capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 15.0; // nearly-full bin: fine, but tiny slivers are worthless
    } else if frac >= 0.1 && frac < 0.25 {
        score += 6.0;  // dead zone: fits only very small items
    } else if frac > 0.5 {
        score += 3.0;  // wasteful half-empty bin
    }

    // Integer-division thresholds: pair item with next item via combined class
    if next_item_size > 0 {
        let pair = item_size + next_item_size;
        if pair == bin_capacity {
            score -= 20.0; // perfect harmonic pairing: fill exactly
        } else if pair <= bin_residual && bin_residual < bin_capacity {
            // this bin can host both items: reward proportional to leftover harmony
            let leftover = bin_residual - pair;
            score -= 10.0 - (leftover % 10) as f64;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral base, but discourage opening new bins
    // when existing bins fit well (post_residual small) or few bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // allow new bin when stream is early or many bins already open and mean residual low
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 5.0 && progress > 0.5 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (tighter bins)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Small harmonic jitter on item class to break ties deterministically
    score += 0.01 * (item_class as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // Treat gaps <= 15 (below typical item sizes) as near-dead space.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 15.0 {
            score += 40.0 * (1.0 - pr / 15.0); // tiny unusable slivers
        } else if pr <= 30.0 {
            score += 10.0; // awkward medium gap
        }
        // Reward tight fits: post_residual close to zero is good.
        score -= 25.0 * (1.0 - pr / cap);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: this is the only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open-bin pressure
    // is high or the item would leave bad dead space in existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins unless they fit poorly.
        score += 20.0;
        // Pressure: with many open bins, opening another is cheap-ish.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score -= 10.0 * progress;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
    } else {
        // Mild penalty for using a bin whose residual deviates far from mean (fragmentation control).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // If next item could exactly fill this bin's post-residual, reward strongly.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here; slightly penalize leaving a gap it could have used better elsewhere.
            score += 5.0;
        }
    }

    // Open-bin count pressure: discourage spreading across too many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap.min(40.0); // best when gap == 0
        if gap == 0.0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving dead space that next item cannot use
        let dead = if post_residual < next_item_size { post_residual as f64 } else { 0.0 };
        score += dead * 0.5;
    }

    // Compare post_residual relative to mean residual: prefer bins tightened toward mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer fuller bins (smaller residual) slightly super-linearly
    score += (bin_residual as f64).powi(2) / (bin_capacity as f64) * 0.1;

    // Mild penalty for opening a new bin when open bins exist and item fits elsewhere
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    // Early in stream: allow opening bins more freely to build structure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Penalize dead space: post_residual too small to ever be useful (< 10).
    if post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64);
    } else if post_residual > 40 {
        // Large leftover is flexible; mildly reward keeping larger residuals alive.
        score -= 0.05 * post_residual as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            score += 0.10 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > 25.0 {
        score -= 0.08 * mean_residual;
    }

    // Time horizon: late in the stream, waste matters more (no future items to reuse space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let shape = norm_post * norm_post * (1.0 + 0.8 * progress) + 0.5 * norm_post * (1.0 - progress);
    score += 60.0 * shape;

    // Reward tight fits more strongly later in the stream
    let tightness = (1.0 - norm_post) * (1.0 - norm_post);
    score -= 45.0 * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth falloff)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward leaving exactly room for the next item
        let match_term = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 20.0 * match_term.max(0.0) * match_term.max(0.0);
    }

    // Last-chance bonus: avoid opening a new bin when few options remain
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Mild pressure relative to mean residual of open bins
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_post - mean_norm) * (norm_post - mean_norm);
    score -= 5.0 * (mean_norm - norm_post);

    // Encourage consolidation early, spreading later
    score += 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * norm_post * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = norm_item * norm_item;
        score += 15.0 - 35.0 * poor_fit + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * post_frac * post_frac;

    // Dead-space penalty: residual too small for any plausible item (sizes 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (multiples of 10 and small even values are more reusable)
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer division threshold: post_residual bucketing
    let bucket = pr / 20; // 0..5
    score += bucket as f64 * 4.0;

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // great: chain placement possible
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.2;
            // exact match bonus
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize wasted lookahead
            score += 6.0;
            // harmonic mismatch penalty via modulo classes
            if next_item_size % 10 != 0 && pr % 10 != 0 {
                score += 3.0;
            }
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // many options: prefer the best fit, mild bonus
        score -= 2.0;
    }

    // New-bin candidate: empty bin gets baseline treatment.
    // Prefer it only when open bins are very full on average (mean residual low)
    // or the item is large and would leave bad residual in existing bins.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // low => bins nearly full
        let item_frac = item_size as f64 / cap;
        // baseline score so new bin loses unless existing fits are poor
        score = 55.0 - 30.0 * pressure - 10.0 * item_frac;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            score += 45.0; // discourage abandoning the only fitting bin
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // Prefer bins with residual already below mean (filling emptier-of-space bins first)
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome.
        score -= 80.0;
    }

    // Dead space that could still host the lookahead item is less bad.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap cannot fit next item: likely true dead space
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Pressure against proliferation of open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins tighter than the current mean residual (good compaction).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else or there are no open bins; otherwise push it up hard.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 90.0; // opening a fresh bin for a bad fit is wasteful
        } else {
            score += 20.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            // reward tight-but-fitting residual for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's residual: penalize proportionally
            let unusable = (next_item_size - post_residual) as f64;
            score += 8.0 * (unusable / 100.0);
        }
    } else {
        // last item: prefer minimal waste
        score -= 10.0;
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (pack small residuals first)
    let mr = mean_residual;
    if (bin_residual as f64) < mr {
        score -= 3.0 * (mr - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * (bin_residual as f64 - mr) / bin_capacity as f64;
    }

    // Penalize creating tiny unusable dead space (post_residual < 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly as it approaches zero.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 4.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Penalize leaving a gap slightly larger than the next item (bad pairing).
            let gap_waste = post_residual as f64 - (next_item_size as f64);
            if gap_waste > 0.0 && post_residual > 0 {
                score += 0.5 * gap_waste;
            }
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_fraction = (bin_capacity as f64 - bin_residual as f64) / (bin_capacity as f64);
    score -= fill_fraction * (open_bins_count as f64).sqrt() * 3.0;

    // Deviation from mean residual: prefer bins notably fuller than average.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Time horizon: early in stream, be more willing to open new bins (score new bin higher);
    // late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with progress and number of open bins.
        score += 15.0 + 40.0 * progress + 2.0 * (open_bins_count as f64);
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for very large items into nearly-full bins creating tiny leftovers.
    if post_residual > 0 && (post_residual as f64) < 0.25 * (bin_capacity as f64) {
        score += 6.0 * (1.0 - (post_residual as f64) / (0.25 * bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear penalty for small-but-nonzero residuals
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress: later in the
    // stream, tight fits (low post_residual) matter more.
    score -= 12.0 * (1.0 - norm_pr) * (progress * progress);

    // Reward bins whose post-residual could host the next item (smooth interaction)
    if next_item_size > 0 {
        let fit_next = ((pr - norm_next * cap) / cap).max(0.0);
        score -= 10.0 * fit_next * (1.0 - progress) * (1.0 - norm_item);
    }

    // Penalty when this is the last fitting bin but fit is wasteful
    if fitting_bins_count == 1 {
        score += 6.0 * norm_pr * (0.5 + progress);
    }

    // Mild pressure to spread across bins: compare residual to mean residual
    score += 0.05 * (pr - mean_residual);

    // Non-linear dead-space term: residuals below ~item-size granularity are dead
    let dead = (-norm_pr * 8.0).exp() * (1.0 - (norm_pr / 0.35).min(1.0)).max(0.0);
    score += 15.0 * dead * (0.3 + 0.7 * progress);

    // Slight preference to keep many open bins balanced early
    score += (open_bins_count as f64).ln() * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (hard to fill later) get penalized.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Fraction of capacity left after placement.
    let frac = pr as f64 / cap;

    // Penalize dead space in small residue classes modulo 10 (typical item granularity).
    let class = pr % 10;
    let class_penalty = match class {
        0 => -30.0,          // perfectly reusable residual
        1 | 2 | 3 => 12.0,   // awkward slivers
        4 | 5 | 6 => 4.0,    // moderately usable
        _ => 0.0,
    };
    score += class_penalty;

    // Harmonic bonus: residual that exactly matches next item or a divisor class of it.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0; // perfect two-item completion
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 18.0; // next item leaves a clean class-0 residual
        } else if next_item_size > pr {
            // Next item can't fit here; residual becomes dead space unless reusable later.
            score += (next_item_size - pr) as f64 * 0.35;
        }
        // Reward residuals that can hold next item plus a small harmonic remainder.
        if next_item_size <= pr && pr % 5 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when this item fills a large chunk cleanly
    // or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        if tightness > 0.7 {
            score -= 15.0; // large item into fresh bin is fine
        } else {
            score += 20.0 + 30.0 * (1.0 - tightness); // discourage wasting fresh bins on small items
        }
        if mean_residual > 25.0 && next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 15.0; // open bins still have useful space; keep using them
        }
    }

    // Favor tight fits generally.
    score -= (item_size as f64 / cap) * 20.0;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - frac);

    // Slight preference for bins below mean residual (balancing fragmentation).
    score += 0.05 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10, unusable by min item)
    // are heavily penalized; medium leftovers are mildly penalized.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // dead space: nothing can ever fill it
    } else if post_residual <= 20 {
        score += 12.0; // tight gap, risky
    } else {
        // prefer leaving gaps that plausibly match upcoming demand
        score += 0.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // encourage closing out bins with small residuals.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * pr / 10.0;

    // New-bin candidate handling: an empty bin should only win when the item
    // fits poorly everywhere else (large item, few fitting bins, big residual mismatch).
    if bin_residual == bin_capacity {
        let mismatch = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // base cost of opening a new bin, reduced when item is large or stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_cost = 45.0 - 15.0 * fill - 5.0 * (1.0 - progress);
        score += new_bin_cost + 20.0 * desperation * mismatch;
    }

    // Lookahead: if next item would fit exactly in the resulting gap, reward it
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // gap is truly dead even for the lookahead
    }

    // Mild preference for bins whose residual is closest to item (best-fit core)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 900.0;
        } else if post >= nxt && (post - nxt) <= 10.0 {
            score -= 400.0;
        } else if post >= nxt && (post - nxt) <= 25.0 {
            score -= 150.0;
        } else if post < nxt {
            // post-residual too small for next item: dead space unless tiny
            if post <= 10.0 {
                score -= 50.0; // harmless crumb
            } else {
                score += 0.5 * (post - nxt); // stranded space penalty
            }
        }
        // Prefer bins whose post-residual stays close to the stream's
        // typical residual so future items keep fitting.
        let dev = (post - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 200.0;
        if post_residual > 40 {
            score += 100.0; // still wasteful fit; soften the bonus
        }
    }

    // Penalize opening a new bin when good open options exist:
    // the new-bin candidate has bin_residual == bin_capacity; its post_residual
    // is large, so add pressure proportional to remaining stream length.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * (1.0 - progress);
        // But if next item is huge and this bin's post-residual would fit it
        // while no open bin could, opening can pay off (handled implicitly by
        // lookahead rewards above).
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 30.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual non-linearly.
    let post = post_residual as f64;
    score -= 60.0 * (-post / 25.0).exp();

    // Penalize dead space that can never be used again by typical items (post_residual < 10).
    if post_residual < 10 {
        score += 40.0 * (10.0 - post);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (-slack as f64 / 20.0).exp();
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: mild penalty proportional to leftover.
        score += 8.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty proportional to number of open bins to discourage sprawl,
    // scaled by stream progression (late in the stream, consolidation matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a very poor fit in any existing bin.
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.4 * open_bins_count as f64 * (1.0 - progress);
        score += base;
        // Large items leave big residuals anyway; encourage fresh bins early for big items.
        if item_size >= 60 {
            score -= 25.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: dead space matters more as stream progresses
    let dead = pr / cap;
    let coupling = dead * dead * (0.5 + 2.0 * progress) + dead * (1.0 - progress);
    score += 12.0 * coupling;

    // Perfect-fit reward (smooth, non-piecewise)
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_frac * fit_frac * (1.0 - dead);

    // Lookahead: penalize residuals that can't fit the next item, reward those that can
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = pr - nx;
        let compat = 1.0 / (1.0 + (-room / cap * 6.0).exp());
        score += 8.0 * (1.0 - compat) - 6.0 * compat;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many bins; encourage consolidation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * dead;

    // Prefer bins whose residual is near the mean (balanced packing)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only for large items / early stream
    if bin_residual == bin_capacity {
        let tight = 1.0 / (1.0 + (-(item_size as f64 / cap - 0.6) * 8.0).exp());
        score += 15.0 * tight - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 equal classes.
    let class = post_residual / (bin_capacity / 10).max(1);
    match class {
        0 => score -= 30.0,           // near-perfect fit, almost no dead space
        1 => score -= 18.0,           // excellent fit
        2 => score -= 10.0,           // good fit
        3 => score -= 5.0,
        4 => score += 2.0,            // half-full: mediocre
        5 => score += 4.0,
        6 => score += 8.0,
        7 => score += 12.0,
        8 => score += 16.0,
        _ => score += 20.0,           // large dead space
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable.
    let mods = [
        (post_residual % 10 == 0) as i32,
        (post_residual % 20 == 0) as i32,
        (post_residual % 25 == 0) as i32,
        (post_residual % 50 == 0) as i32,
    ];
    let mod_bonus = 4.0 * mods[0] as f64 + 6.0 * mods[1] as f64
        + 8.0 * mods[2] as f64 + 10.0 * mods[3] as f64;
    score -= mod_bonus;

    // Lookahead coupling: does post_residual accommodate next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 25.0; // perfect two-item chain
            } else if gap <= 10 {
                score -= 12.0;
            } else if gap <= 20 {
                score -= 6.0;
            } else {
                score += 1.0;
            }
            // next item lands in a harmonic class of its own
            let nclass = (post_residual - next_item_size) / (bin_capacity / 10).max(1);
            score -= (3 - nclass.min(3)) as f64 * 3.0;
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += 3.0;
            if post_residual > 40 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: empty bin is a fallback, not a favorite.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin grows with stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress;
        // opening a bin is more attractive when few bins fit and mean residual is low
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= 70 {
            score -= 8.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Mild preference for compacting many open bins rather than spreading.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit bonus: reward placements that leave a gap too small for typical items
    // only if it is a near-perfect fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Open-bin pressure: prefer reusing bins when many are open; discourage
    // spreading across bins when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item would be blocked by a small dead gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when the item is large relative to capacity (poor fit elsewhere likely)
    // or when open bins are few; otherwise add a mild penalty to favor consolidation.
    if bin_residual == bin_capacity {
        if item_size >= 60 || open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Mean-residual coupling: if this bin is much tighter than average, it is a good home.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits perfectly-ish: strong reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty: next item won't fit here
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / bin_capacity as f64).min(1.0);
        }
