    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Compare post_residual against mean residual: avoid leaving bins far from mean
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when open bins exist that fit well
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Slight preference for tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 18.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 8.0 * fit_ratio;
    }

    // Penalize dead space that no future item (min size ~1) can plausibly use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin is fine actually; small leftover is good
        score -= 30.0; // net reward
    } else if post_residual < 25 {
        score -= 4.0;
    } else if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.35; // wasteful large leftover
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the item
    // is large or fits nowhere well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let big_item_bonus = if item_size >= 60 { 20.0 } else { 0.0 };
        // Base penalty for opening a new bin, softened late in the stream.
        score += 30.0 * (1.0 - 0.5 * progress) - pressure - big_item_bonus;
    }

    // Lookahead coupling: if the next item could use this bin's post-residual,
    // reward leaving a compatible gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 3.0; // next item won't fit here anyway; slight penalty for bad gap
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into bins below-average residual (fill the emptiest-feeling).
    if open_bins_count > 3 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual interacts with progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += poly * (100.0 + 200.0 * progress);

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (30.0 + 120.0 * progress);

    // Penalize creating dead space that likely can't fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 15.0 + 25.0 * progress;
    } else if next_item_size > 0 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= slack * 20.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 35.0 * progress;
    }

    // Mild penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, prefer filling existing bins
        score += 40.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how close it is to a "nice" fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Class boundaries at 1/8ths of the bin; dead space below 1/8 is nearly useless.
    let eighth = (frac * 8.0).round() / 8.0;
    score -= (1.0 - (frac - eighth).abs() * 8.0) * 4.0; // reward landing on harmonic grid points

    // Penalize tiny dead space classes (0 < post_residual < capacity/8) heavily.
    if post_residual > 0 && post_residual < bin_capacity / 8 {
        score += 25.0 * (1.0 - post_residual as f64 / (bin_capacity / 8) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic pairing: does post_residual modulo next_item_size leave a usable remainder?
    if next_item_size > 0 {
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 && post_residual > 0 {
            score -= 18.0; // next item divides the leftover exactly
        } else {
            score += rem as f64 * 0.15;
        }
        // If next item fits exactly in post_residual, strong bonus.
        if next_item_size == post_residual {
            score -= 22.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 25.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere, must open
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    // Late in stream: consolidate, prefer existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / 10.0).min(3.0);

    // Prefer bins below mean residual (balance avoidance of many half-full bins).
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(-5.0).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

