    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening new bins more as stream progresses
        score += 10.0 + 15.0 * progress;
        // if mean residual of open bins is large, opening new bin is wasteful
        score += 0.05 * mean_residual;
