}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early on, prefer filling bins tightly (penalize large residuals quadratically);
    // later, accept larger residuals slightly more but reward tight fits via cubic term.
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score += 20.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residuals too small for the smallest plausible item are waste.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.5;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 12.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 4.0; // next item cannot use this residual
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Congestion term: many open bins with high mean residual -> discourage spreading.
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += congestion * (mean_residual - pr).max(0.0) * 0.3;

    // New-bin candidate: neutral-ish baseline, penalize opening early, allow late.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 0..7 harmonic class of leftover

    // Dead-space penalty: leftover below the smallest item class is nearly unusable.
    if post_residual < 10 {
