    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Favor bins whose leftover class matches the next item's size class.
            let next_class = (next_item_size as f64 / cap * 8.0).floor();
            if next_class == class {
