            }
            score -= (post_residual.min(next_item_size) as f64) * 0.1;
        } else {
            // Leftover cannot host next item: penalize proportionally to wasted potential.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score = cap + pressure + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Mild consolidation: prefer fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / cap) * (2.0 + 6.0 * progress);
    score += (mean_residual - pr).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

