    }

    // Mild alignment with mean residual: prefer bins deviating below the mean
    // (they are the tightest), pushing looser bins toward the back.
    score += 0.15 * ((bin_residual as f64 - mean_residual).max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item won't fit here: penalize small leftover dead space
            score += 50.0 / (1.0 + post_residual as f64);
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless current bins are nearly full or fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin attractive only if item is large relative to residual of others
        // or there are no fitting bins; give it a baseline penalty otherwise.
        let waste = (bin_capacity - item_size) as f64;
        score = 300.0 + waste - 100.0 * progress;
        if post_residual == 0 {
            score -= 1000.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 150.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a bin anyway
        }
    }

    // Slight preference to consolidate: fewer open bins is better.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual is good, penalize awkward middles.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect, dead space unusable anyway
    } else if post_residual > 60 {
        score += 15.0; // wasteful large gap
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // next item won't fit here; mildly penalize leaving medium gaps
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Slight preference to reuse bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it's early or current fits are terrible.
        score += 25.0 - 20.0 * progress;
        // If no open bin fits well, opening new bin becomes attractive.
        if bin_residual < item_size {
            score -= 1000.0; // cannot happen for empty bin; safety
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If best post-residual among fits is poor (large gaps), prefer new bin.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    } else {
        // Open-bin mild bonus to encourage consolidation.
        score -= 5.0 + 3.0 * progress;
    }

    // Penalize bins with residual just above typical small-item sizes (awkward gaps).
    if post_residual >= 20 && post_residual <= 40 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear coupling to stream progress.
    // Early on, waste matters less; later, tight fits (small post_residual) are prized.
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Quadratic penalty for awkward mid-size dead space, growing with progress.
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits smoothly (post_residual close to 0).
    score -= 15.0 * (-pr / 8.0).exp();

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap / 6.0).exp();
        // Penalize post_residual that is too small for the next item (dead space).
        if next_item_size as f64 > pr {
            score += (next_item_size as f64 - pr) * (0.4 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Mild preference for bins deviating from mean residual (consolidation pressure).
    score += 0.05 * (pr - mean_residual).abs();

    // Slight bias toward fewer open bins early, encouraging filling existing bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if next item can use it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can follow in this bin: reward chaining.
            let chain_bonus = (next_item_size as f64 / bin_capacity as f64) * 30.0;
            score -= chain_bonus;
        } else {
            // Dead space: post_residual too small for the next item.
            let dead = post_residual as f64;
            // Harmonic penalty: harsher for awkward residual classes.
            let class = post_residual % 10;
            let awkward = if class == 0 { 0.0 } else { (10 - class) as f64 * 2.0 };
            score += dead * 0.5 + awkward;
        }
    } else {
        // Last item: minimize leftover.
        score += post_residual as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Open a new bin when item is big and existing bins are too full on average.
        let big_item = (item_size as f64 / bin_capacity as f64) * 50.0;
        score += 60.0 - big_item - fragmentation * 0.3 - progress * 10.0;
    }

    // Slight preference for bins below mean residual (balancing).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Integer-division threshold: post_residual in [1..=5] is near-waste.
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for any item (min size 1, but
    // practically unusable gaps below ~20) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fits (small post_residual) rewarded progressively.
    score -= (bin_residual - post_residual) as f64 * 0.3;

    // Open bins pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by the resulting gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += post_residual as f64 * 0.5;
    }

    // Prefer bins already tighter than the mean residual (compactness).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight preference to fill existing bins more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits here: reward proportional to how well it packs
            let leftover = post_residual - next_item_size;
            score -= 200.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a gap next item can't use
            score += 0.5 * post_residual as f64;
        }
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin's space
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when existing bins fit decently
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual > 40 {
        score += 120.0;
    }

    // Small late-stream conservatism: prefer compacting as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 6.0;
        }
        // Perfect two-item fill
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer minimal waste, strongly.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or open bins are nearly full anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = mean_residual / bin_capacity as f64;
        // If open bins are on average roomy, discourage new bin.
        score += 14.0 + 10.0 * (1.0 - avg_fill);
        // Early in the stream, new bins are cheaper (long horizon to fill them).
        score -= 8.0 * (1.0 - progress);
        // If many bins fit the item, definitely prefer existing bins.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load) when fit is loose.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    }

    // Time horizon: as stream nears end, avoid opening new bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 30.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score -= 25.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize waste that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - pr / (nxt + pr)) * (1.0 - progress);
        }
    }

    // Last-chance bin reward: avoid opening new bins when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: keep it competitive only when open residuals are poor
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - (mean_residual / cap).min(1.0)) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable -> reward them (subtract).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always ideal
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }

        // Integer-division thresholds: small dead space is bad.
        if pr < 10 { score += 45.0; }        // unusable sliver
        else if pr < 20 { score += 12.0; }
        else if pr < 30 { score += 4.0; }

        // Coupling with lookahead item: does next item fit exactly / well?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 35.0; // next item fills this bin perfectly
            } else if next_item_size < pr {
                let gap = pr - next_item_size;
                if gap < 10 { score += 25.0; } // next item would strand a sliver
                else { score -= (gap as f64).min(40.0) * 0.3; }
            } else {
                // next item cannot fit here: residual is a hard remainder
                score += (pr as f64) * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        score += 55.0
            + (open_bins_count as f64) * 1.5
            + mean_residual * 0.4;
    }

    // Late-stream tightness: as stream progresses, waste less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.25;

    // Prefer bins whose residual deviates from mean (consolidate waste).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, the min item size)
    // are worthless; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    } else if post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits (near-perfect packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // If the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to wasted space.
        score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / 8.0;
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.7;
        score += 45.0 - 30.0 * crowded.min(1.5);
        if poor_fit && fitting_bins_count <= 2 {
            score -= 50.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0; // pairing possible in fresh bin anyway
        }
    }

    // Slight late-stream tightening: prefer closing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
