    // Dead space: post_residual too small for the next item -> penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        let dead = post_residual as f64;
        let ratio = dead / next_item_size as f64;
        score += 50.0 * ratio;
    }

    // Tight fit reward relative to mean residual: prefer bins tighter than average.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no open bin fits well (high mean residual waste), new bin is OK.
        if mean_residual > (bin_capacity as f64) * 0.5 {
            score -= 60.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (small post_residual matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
