    // late in the stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate adjustment: an empty bin has high post_residual; make it attractive
    // only when the item is large or the current bin leaves unusable space.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * large_item;
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Reward tight fits: smaller post_residual relative to capacity is good,
    // strengthen this reward as the stream progresses.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize post-residuals that are dead space: too small to fit typical
    // future items (below the minimum plausible size band). Smooth quadratic
    // penalty around the low-residual region.
    let dead_threshold = 12.0;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / dead_threshold;
        score += 25.0 * d * d;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward strongly; if next item would leave a very tight residual, mild reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let post2 = pr - nxt;
            let chain_tightness = 1.0 - (post2 / cap);
            score -= 14.0 * chain_tightness * (0.6 + 0.4 * progress);
            if post2 < 10.0 {
                score -= 8.0; // perfect chaining creates near-zero waste
            }
        } else {
            // Next item does not fit here: mild penalty scaled by overshoot.
            let over = (nxt - pr) / cap;
            score += 6.0 * over;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, discourage fragmenting space further unless the
    // fit is very tight; couple with mean residual.
    let frag_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / cap);
    score += 10.0 * frag_pressure * (pr / cap);

    // Smooth progress-dependent exploration: early in the stream, slightly
    // prefer consolidating into existing bins (lower score for filled bins).
    score -= 6.0 * (1.0 - progress) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Classes: 0 (perfect), tiny (<=10), small (<=25), medium (<=50), large (>50)
    let class = if post_residual == 0 { 0.0 }
        else if post_residual <= 10 { 1.0 }
        else if post_residual <= 25 { 2.0 }
        else if post_residual <= 50 { 3.0 }
        else { 4.0 };

    // Penalize by harmonic class: dead space in multiples of common item sizes is less bad.
    // A residual that is a multiple of 10 (common granularity) is more reusable.
    let harmonic_mod = post_residual % 10;
    let mod_bonus = if harmonic_mod == 0 { 15.0 }
        else if harmonic_mod <= 2 { 8.0 }
        else { 0.0 };
    score -= mod_bonus;

    // Base class penalty
    score += class * 6.0;

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 40.0; // perfect chain
        } else if next_post <= 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize small dead space more than large
        score += class * 4.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer tightening existing bins (low residual) over spreading.
    if open_bins_count > 3 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Early stream: keep residuals large for flexibility; late stream: close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress) * class * 0.25;

    // New-bin candidate: empty bin has huge residual; make it unattractive unless
    // no open bin fits well (handled by last-chance and class logic).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fit (low post residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..=100) are wasted. Penalize "unusable" gaps heavily.
    // A gap is unusable if it is smaller than the smallest plausible item (1),
    // but practically, gaps below ~10-15 rarely get filled in unknown streams.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // tiny sliver: near-certain dead space
        } else if post_residual < 20 {
            score += 10.0; // likely dead space
        } else if post_residual < 35 {
            score += 3.0; // marginal
        } else {
            // large residual is reusable: mild reward proportional to size
            score -= 0.05 * (post_residual as f64 - 35.0);
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Reward when this bin can also fit the lookahead item exactly well
    // (chained packing reduces future dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_gap = post_residual - next_item_size;
            score -= (10.0 - chain_gap as f64).max(0.0); // two-item perfect chain bonus
        } else {
            // lookahead won't fit here: slight penalty if post gap is large but
            // unusable for the next item
            score += 1.5;
        }
    }

    // Open-bin pressure: discourage opening/spreading across many bins when
    // a reasonable fit exists, but allow opening a new bin when this bin
    // would create dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if open bins are already loose (high mean residual),
    // prefer filling them rather than a new bin.
    score -= 0.1 * mean_residual;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // unless it creates severe dead space (handled above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current fit is poor (large post_residual with
    // dead-space risk) — otherwise the empty bin gets a moderate default score.
    if bin_residual == bin_capacity {
        // Neutral-ish score: chosen only if all real bins score worse.
        score = (bin_capacity - item_size) as f64 + 8.0
            + 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress)
            - 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0; // empty bin can chain the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual), with non-linear dead-space penalty.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.08;
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item can chain into this bin: reward closeness of match.
            score -= (30.0 * (1.0 - diff / 100.0)).max(0.0);
            // Exact chain match is excellent.
            if diff == 0.0 { score -= 20.0; }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += diff * 0.35;
            // Small leftover that nothing can use is wasted.
            if post_residual < next_item_size && post_residual < 10 {
                score += 40.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.1;
    }

    // Compare against mean residual: bins already tighter than average are better targets.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= (mean_residual - res) * 0.25;
        } else {
            score += (res - mean_residual) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer opening a fresh bin only for large items or when
    // no open bin offers a reasonable fit; otherwise discourage it mildly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fitting_bins_count == 0 || (post_residual as f64) > 0.55 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 55.0; // keep using existing bins when they fit decently
        }
        // Large items fragment bins; a fresh bin for large items is fine.
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild preference to fill nearly-full bins regardless.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Late in the stream, consolidate harder (fewer lingering open bins).
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize unusable dead space: residuals too small for typical future items
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave this bin stranded, mild penalty
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 8.0;
    }

    // Prefer bins below mean residual (keep balance, save fuller bins)
    score += 0.35 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when existing bins fit poorly or are scarce
    if bin_residual == bin_capacity {
        let poor_options = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let early = 1.0 - t;
        score += 30.0 - 25.0 * poor_options - 10.0 * early;
        // Opening a bin early is fine if item is large
        if item_size >= 50 { score -= 15.0; }
    }

    // Mildly discourage proliferating bins when many are open with slack
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    // Time horizon: later in stream, consolidate more aggressively
    score -= 6.0 * t * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 + 3.0 * progress) + prn * progress * progress;
    score += 2.5 * poly;

    // Tight fits are rewarded more strongly as the stream progresses
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 8.0 * progress;
    }

    // Lookahead: prefer bins whose residual still fits the next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if pr >= nr {
            score -= 4.0 * (nr / cap) * (1.0 - prn);
        } else {
            score += 3.0 * (nr - pr) / cap;
        }
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.15 * open_bins_count as f64 * prn * (1.0 - progress);

    // Penalize residuals far from mean (fragmentation)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight bias against opening a new bin early
    if bin_residual == bin_capacity {
        score += 1.5 * (1.0 - progress) + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Harmonic classes: dead space classes on post_residual.
    // Residuals divisible by 10 pair well with typical item sizes; odd/tiny residuals are dead.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score += 45.0; // unusable dead space
    } else if pr % 10 == 0 {
        score -= 12.0; // aligned residual, likely reusable
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += 6.0;
    }

    // Integer division threshold: how large a class of items still fits.
    let fits_next = if next_item_size > 0 { pr >= next_item_size } else { false };
    if next_item_size > 0 {
        if fits_next {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Waste if next item cannot use this residual
            score += 10.0 * fit_ratio;
        }
    } else {
        // Last item: prefer exact closure, otherwise anything works
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity if open bins exist and fit ratio is poor.
        if open_bins_count > 0 {
            score += 55.0 * (1.0 - fit_ratio); // fit_ratio = 1 for empty bin -> no penalty base
            score -= 20.0; // mild base preference to keep bins tidy
            if fitting_bins_count == 0 {
                score -= 80.0; // no alternative: must open
            }
            if next_item_size > 0 && next_item_size >= 60 {
                score -= 15.0; // large next item benefits from fresh bin
            }
        } else {
            score -= 100.0;
        }
    }

    // Stream progression: early on, be frugal with new bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual / bin_capacity as f64 - 0.5);

    // Prefer filling bins below mean residual (more fragmented bins first).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Many open bins: encourage closing them out.
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += (11.0 - post_residual as f64) * 8.0; // tiny gaps are the worst
        } else if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 2.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward filling a bin nearly completely.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Tight fit reward: item consumes most of the residual.
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_tightness * 10.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer compacting.
    score += (open_bins_count as f64) * 1.5;

    // If next item fits in the post residual, reward leaving useful space.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else {
            // next item can't use the leftover: penalize proportionally to waste
            score += (post_residual as f64) * 0.5;
        }
    }

    // Progression: later in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., mean residual is small relative to item) or bins are all poor fits.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 || mean_gap > 25.0 {
            score -= 20.0; // open a new bin when existing ones are bad fits
        } else {
            score += 15.0; // discourage needless bin proliferation
        }
        // Early stream: allow more bins; late stream: compact.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
