    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.9 * pr / cap * (1.0 - pr / cap));

    // Polynomial coupling with stream progress: late in the stream,
    // waste matters more (fewer future chances to reuse residuals)
    let p2 = progress * progress;
    score += pr * (0.4 + 1.2 * p2) * (pr / cap);

    // Reward tight fits (post_residual near zero) more aggressively as stream advances
    let tight = 1.0 - pr / cap;
    score -= tight * tight * (2.0 + 3.0 * p2) * 10.0;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 8.0 * progress;
    }
    // Penalize residuals too small for likely future items
    if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
        score += 3.0 * (next_item_size as f64 - pr) / cap * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mean-residual context: bins far below mean residual are good targets early,
    // but late in stream prefer filling bins above mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * (2.0 - 4.0 * p2);

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    // New-bin candidate: penalize opening a fresh bin unless item is large
    if bin_residual == bin_capacity {
        score += 18.0 - 0.15 * it - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly rewarded
    } else if post_residual < 20 {
        score += 8.0; // risky small gap
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave another dead sliver, slight penalty.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 10.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced to open new bin
        } else {
            score += 35.0 + mean_residual * 0.3; // prefer existing bins
        }
    }

    // Mild stream-progression adaptation: tighten up toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 150.0;
            } else if gap <= 30 {
                score -= 40.0;
            } else {
                score += (gap as f64) * 0.5;
            }
        } else {
            // Next item won't fit here: leftover is "dead" for the lookahead.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }

        // Chain fit: current + next exactly filling the bin is excellent.
        if item_size + next_item_size == bin_residual {
            score -= 400.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // space; filling them well is valuable. Bins above mean have slack.
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        if resid_f < mean_residual {
            score -= (mean_residual - resid_f) * 0.6;
        } else {
            score += (resid_f - mean_residual) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // badly fragmented (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 180.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can serve the lookahead item too
        }
        if mean_residual < 15.0 {
            score += 120.0; // open bins are tight; opening new bin is wasteful
        }
        if fitting_bins_count <= 2 {
            score += 100.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(2);

    // Perfect or near-perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward if the next item can fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 4.0 * (1.0 - next_item_size as f64 / (post_residual as f64 + 1.0)).abs();
        }
        // If next item exactly fills post residual, big bonus.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: slight penalty to preserve flexibility.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin unless it's necessary.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        // Waste grows with how poorly current bins would fit.
        let poor_fit = if fitting_bins_count > 0 {
            (item_size as f64 - mean_residual.max(item_size as f64)).abs()
        } else {
            0.0
        };
        score += 35.0 + urgency * 0.0 - poor_fit * 0.2;
        // Late in stream, prefer closing out open bins rather than new ones.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 15.0 * (1.0 - progress);
        // If many open bins, discourage yet another.
        score += 2.0 * (open_bins_count as f64);
    }

    // Global state: if mean residual is large, prefer bins that reduce fragmentation
    // (i.e., bins whose post residual is below mean residual).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Time horizon: early on, keep bins flexible (mild penalty for tiny residuals);
    // late in stream, allow aggressive packing.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize post residual, smoothly damped by stream progress
    let mut score = pr * (1.0 + 0.5 * t * t);

    // Smooth non-linear coupling: squared residual term scaled by item fraction
    score += 20.0 * pr_norm * pr_norm * (0.5 + fit);

    // Favor tight fits (low post_residual relative to item size) via smooth ratio
    let tight = 1.0 - pr / (bin_residual.max(1) as f64);
    score -= 15.0 * tight * tight * (1.0 - t);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize early, allow late or when item is huge
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 18.0 / openness + 10.0 * (1.0 - t) - 12.0 * fit * fit;
    }

    // Lookahead: reward leaving space for the next item, smoothly
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let gap = pr_norm - ns / cap;
        score += 8.0 * gap * gap * (0.5 + 0.5 * t);
        if ns <= pr {
            score -= 6.0 * (ns / cap) * (1.0 - t);
        }
    }

    // Mean residual coupling: discourage bins far from the mean state
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space classes (small unusable slivers)
    let pr = post_residual;
    if pr > 0 {
        // dead-space classes: residual < smallest plausible item (<=10) is nearly dead
        if pr < 10 {
            score += 60.0;
        }
        // class-based penalty via integer division thresholds
        let class = pr / 10; // 0..10 harmonic buckets
        score += match class {
            0 => 25.0,
            1 => 8.0,
            2 => 2.0,
            3 => 0.0,
            4 => -3.0,
            5 => -6.0,
            6 => -8.0,
            7 => -6.0,
            8 => -3.0,
            9 => 0.0,
            _ => 4.0, // near-empty bin
        };
        // modulo coupling: residuals that are multiples of common item sizes pair well
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead: does post_residual fit the next item exactly / at all?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize proportionally to wasted opportunity
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // harmonic coupling of next item to capacity fraction
        let frac = next_item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            // big next item: prefer keeping large residuals
            score += (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when item is huge or no good fits
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 30.0;
        }
        if fitting_bins_count > 0 && frac <= 0.6 {
            score += 80.0;
        }
    }

    // Stream progression: later in stream, prefer tighter packing (penalize loose residuals)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Spread-awareness: deviating from mean residual
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Few open bins: encourage consolidation
    if open_bins_count <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Fill efficiency: reward bins whose residual is mostly consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last chance: only one bin can fit this item; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: favor bins that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Pressure from many open bins: prefer tightening existing bins.
    let open_pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score += 8.0 * open_pressure;

    // Prefer bins below mean residual (larger remaining space) slightly less.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it unattractive unless no good fit exists
    // (dead-space penalties above already raise bad fits).
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item's size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap * 0.15);
        // penalize leaving a residual that is too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Reward tight fits relative to mean residual of open bins
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin bonus: avoid wasting the only fitting bin's space carelessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // new bin fine if it perfectly serves next item too
        }
    }

    // Progression: as stream advances, prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly as item size grows.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * tightness * (item_size as f64 / 100.0);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are wasted capacity
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: residual after both items nearly zero.
        let combo = post_residual as i64 - next_item_size as i64;
        if combo == 0 {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: make fresh bins attractive when existing
    // fits are poor, but discourage opening bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when item is large relative to capacity.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // Early stream: opening new bins is cheap and builds flexibility.
        score -= 8.0 * (1.0 - progress);
        // Many open bins with slack: discourage another bin.
        score += 0.5 * open_bins_count as f64;
        if mean_residual > 30.0 {
            score += 5.0;
        }
    }

    // Mild preference for bins below mean residual (consolidating slack).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Late in stream: prioritize filling bins as completely as possible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress + 0.4 * progress * norm_pr);

    // Penalize small dead space quadratically (wasted capacity)
    if pr > 0.0 {
        score += 8.0 * norm_pr * norm_pr;
    }

    // Reward tight fits (small post_residual) with smooth decay
    score -= 6.0 * (-(pr / 12.0)).exp();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: prefer bins whose post_residual can host next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && pr > 0 {
        score += 3.0 * (1.0 - (pr as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Mean-residual drift penalty: avoid bins far from the fleet average
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate handling: penalize mildly, more so early in stream
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 (capacity fractions of 100).
    let post_class = (post_residual % 10) as f64;
    // Penalize "awkward" residues that are hard to fill (1..=9 odd gaps), reward 0.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is always great
    } else if post_residual < 10 {
        // small dead space < 10 is unusable for items >= 1? items min size 1, so still usable,
        // but for the classic 10..80 range it is dead: penalize heavily.
        score += 25.0;
    } else {
        // residue class penalty: gaps congruent to small odd residues are less reusable
        score += post_class * 0.8;
    }

    // Integer-division thresholds: how many "average items" still fit?
    let avg_item = 50.0f64.max(1.0);
    let fits_avg = (post_residual as f64 / avg_item).floor();
    score -= fits_avg * 2.0;

    // Coupling with next item (lookahead harmonic class)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, more so if it fills nicely
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 || next_post == 0 {
                score -= 18.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit: this bin risks becoming dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.5;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 20.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: empty bin gets a mild default preference
    // only when current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.15 {
            score -= 10.0; // open bins nearly full: new bin is fine
        } else {
            score += 12.0; // discourage wasting fresh bins
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Many open bins: favor filling existing ones harder.
    score += open_bins_count as f64 * 0.3;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += ((post_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest item (1) are
    // impossible, but tiny unusable gaps (< 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward very tight fits (post_residual small relative to item).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + fit_ratio);

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless dead space is catastrophic).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else; base penalty keeps it from being chosen by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > item_size {
            score -= 8.0;
        }
    }

    // Lookahead: bonus if the post residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the lookahead item.
        score += 8.0;
    }

    // Late in the stream, tighten packing (less room to recover from waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Slight pull toward bins with larger residuals among comparable fits.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match for the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap <= 5 {
            score -= 12.0 - gap as f64 * 2.0;
        }
    }

    // Penalize unusable dead space (post_residual too small for any future item,
    // assuming min item size ~1 but practically small fragments are waste)
    if post_residual > 0 && post_residual < 8 {
        score += 15.0;
    }

    // Reward tight fits: small post_residual generally good
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }
    // Many fitting bins: mild penalty to prefer the tightest among them (already via post_residual)

    // Prefer bins below mean residual when they fit well (balance residuals)
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= (mr - post_residual as f64) * 0.1;
    } else {
        score += (post_residual as f64 - mr) * 0.05;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // opening fresh bin is attractive if next item is large (may need space)
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (wasted capacity).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) < next {
            score += 12.0 * (next - post_residual as f64) / 100.0;
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 6.0;
        }
        // Perfect pairing: post residual exactly fits next item.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: purely minimize post residual.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Mild bonus for using scarce capacity when many bins compete.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Deviation from mean residual: prefer bins tighter than average early,
    // but later in the stream prefer balancing residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = bin_residual as f64 - mean_residual;
    if progress < 0.5 {
        score += 0.08 * dev;
    } else {
        score -= 0.05 * dev;
    }

    // Penalize very small unusable slivers (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: baseline cost of opening a bin. Make it attractive
    // only when the item fits poorly everywhere else or stream is early.
    if bin_residual == bin_capacity {
        let base_cost = 55.0;
        let time_discount = 20.0 * (1.0 - progress);
        let scarcity_penalty = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let poor_fit_elsewhere = if next_item_size > 0 && (bin_capacity - item_size) < next_item_size { 5.0 } else { 0.0 };
        score = base_cost - time_discount - scarcity_penalty + poor_fit_elsewhere + post_residual as f64;
    }

    // Congestion: many open bins -> discourage new bins implicitly via
    // favoring existing bins slightly.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = post / cap;

    // Base: penalize remaining space, with non-linear (quadratic) growth
    let mut score = post + 12.0 * post_frac * post_frac * cap;

    // Reward tight fits: item filling most of the bin
    score -= 20.0 * fit_frac * (1.0 - post_frac);

    // Stream progress coupling: early on, prefer keeping residuals flexible;
    // late, strongly prefer tight packing (post_residual matters more)
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += 6.0 * (1.0 - progress_weight) * post_frac * cap * 0.0
           + (progress_weight - 1.0) * post;

    // Dead-space penalty: residual too small for the smallest plausible item
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post);
    }

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to gap
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 3.0 * gap / cap * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive early / when existing fits are poor,
    // unattractive when a good fit exists
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = cap as f64 * (1.2 + 0.5 * (1.0 - progress)) + 5.0 * openness;
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size {
            score -= 6.0;
        }
    }

    // Mean residual context: prefer bins close to (below) mean residual for balance
    score += 1.5 * ((post - mean_residual) / cap).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity fraction buckets
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // remaining fraction of capacity

    // Dead-space penalty grows superlinearly for small unusable residuals.
    // Residuals below ~10 (min item size) are pure waste; also penalize
    // residuals that fall into "awkward" harmonic classes via modulo logic.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 50.0; // pure dead space
        }
        // Modulo classes: residuals that are multiples of common item sizes
        // are more reusable. Reward divisibility by 10, 5, 25, 20.
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        if pr % 25 == 0 {
            score -= 2.0;
        }
        if pr % 20 == 0 {
            score -= 1.5;
        }
        // Integer-division thresholds: how many "average" items still fit?
        let avg_item = 40u32;
        let slots = pr / avg_item;
        score -= 4.0 * slots as f64;
    } else {
        score -= 15.0; // perfect fill
    }

    // Fraction-based non-linear coupling: penalize mid-range residuals
    // (neither full nor empty) more than extremes.
    score += 10.0 * (4.0 * frac * (1.0 - frac)).powi(2);

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
            // harmonic match: next item leaves residual in a good class
            let nn = post_residual - next_item_size;
            if nn % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // attractive only when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline competitive score; adjust by stream progress and open bins
        score = 0.5 * cap
            + 0.15 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.2 * mean_residual;
        // If the item is large relative to capacity, new bin is fine.
        score -= 0.1 * item_size as f64;
        // If next item is large too, opening fresh bin helps pair them.
        if next_item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
        // If there are many fitting bins, prefer using an existing one.
        score += 3.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Mean residual coupling: when mean residual is high, filling bins is cheap;
    // when low, conserve space by penalizing waste more.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that the lookahead item could fill.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Lookahead cannot fit in the resulting gap: mild penalty scaled by waste.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Tight fit reward relative to the bin's current fill.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score -= 2.0 * (diff / bin_capacity as f64);
    } else {
        score += 2.0 * (-diff / bin_capacity as f64);
    }

    // Early in the stream, tolerate opening new bins; later, be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, increased late.
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 10.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: post_residual exactly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.4;
        } else {
            // Next item cannot chain here: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Bonus if post_residual exactly equals next item (perfect 2-pack).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average.
    let mean_post = mean_residual - item_size as f64;
    score += (mean_post - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // New-bin candidate: mildly penalize so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bin if no open bin gives a good chain.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize awkward dead space that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it's a genuinely better fit
    // than any open bin (large item, few alternatives, or late stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let scarcity_bonus = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 18.0 - scarcity_bonus - 8.0 * progress
                 - 0.05 * (open_bins_count as f64)
                 - (item_size as f64) * 0.1;
    }

    // Global state: if mean residual is small, hoard space in roomier bins.
    if (bin_residual as f64) > mean_residual * 1.2 && bin_residual >= item_size {
        score += 2.0;
    } else if (bin_residual as f64) < mean_residual * 0.8 {
        score -= 3.0;
    }

    // Early stream: encourage consolidation into few bins.
    if open_bins_count > 3 && post_residual < item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smoothed.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep coupling

    // Normalize residuals into [0,1].
    let pr = (post_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
    let br = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);

    // Non-linear polynomial coupling: penalize large dead space more aggressively
    // as the stream progresses (late waste is more costly).
    score += 18.0 * pr * pr * (0.6 + 0.8 * smooth);

    // Reward tight fits: small post_residual gets a bonus amplified by progress.
    score -= 12.0 * (1.0 - pr) * (1.0 - pr) * (0.5 + smooth);

    // Cubic interaction between fill fraction and progress: bins that are already
    // nearly full are favored late (consolidation), less so early.
    let fill = 1.0 - br;
    score -= 9.0 * fill * fill * fill * (0.4 + 1.2 * smooth);

    // Lookahead coupling: reward if next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = (next_item_size as f64).min(bin_capacity as f64);
        if (post_residual as f64) >= nxt {
            score -= 6.0 * (nxt / bin_capacity as f64) * (0.5 + smooth);
        } else {
            score += 7.0 * (1.0 - nxt / bin_capacity as f64) * (0.4 + smooth);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.6 + 0.6 * smooth);
    } else if fitting_bins_count > 1 {
        // Mild penalty for using a scarce-capacity bin when alternatives exist.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual context: if this bin's residual is far below the mean, it is
    // a good consolidation target; penalize bins that hoard residual space.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * (0.5 + smooth);

    // New-bin candidate handling: an empty bin is attractive early or when the
    // fit into existing bins is poor (large post_residual).
    if bin_residual == bin_capacity {
        let early_bonus = 8.0 * (1.0 - smooth);
        let poor_fit_penalty = 10.0 * pr * pr;
        score = score - early_bonus + poor_fit_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" residue classes (still useful for future items) get rewarded,
    // tiny unusable residues get penalized.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..10 harmonic class
    match class {
        0 => score += 25.0,                       // dead space (<10)
        1 => score += 12.0,                       // nearly dead
        2 => score += 5.0,
        3 => score += 0.0,
        4 => score -= 3.0,
        5 => score -= 6.0,                        // ~half-empty: very reusable
        6 => score -= 5.0,
        7 => score -= 4.0,
        8 => score -= 6.0,
        9 => score -= 3.0,
        _ => score -= 0.0,                        // nearly full bin used well
    }

    // Reward tight fits (small post_residual relative to capacity) non-linearly.
    let tightness = 1.0 - (post_f / cap);
    score -= 8.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - chain_waste / cap);
        } else {
            // next item cannot follow into this bin: slight penalty, more severe
            // if the leftover is awkwardly small.
            score += (post_f / 20.0).min(6.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist;
    // allow it when all open bins would leave very awkward residue.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0;
        // If the item would leave a near-perfect fit for the next item in a
        // fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
        // Late in the stream, prefer reusing bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins that are already below the mean residual (balance
    // toward consolidation).
    score += 0.05 * (mean_residual - post_f).max(0.0);

    // Mild reward for using bins when many are open (contain bin sprawl).
    score -= (open_bins_count as f64).min(20.0) * 0.3 * (1.0 - post_f / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (< smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    // Open-bin pressure: prefer reusing bins when many are already open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more when few bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit: post_residual == 0
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
        } else {
            // dead space relative to next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Penalize tiny unusable post_residual (dead space) but not exact zero
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0 && post_residual == next_item_size;
        let _ = tight_fit_exists;
        score += 90.0;
        if fitting_bins_count > 1 {
            score += 60.0;
        }
        // late in stream, prefer consolidating into open bins less strongly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for larger items filling larger residual bins
    score -= item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize dead space that can never fit a typical item: post_residual below
    // the minimum item size is pure waste.
    if post_residual < 1 {
        score -= 50.0; // perfect fit, strong reward
    } else if post_residual < 10 {
        score += 15.0; // small unusable gap
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 + 5.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; mildly penalize leaving a gap that wastes capacity.
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // is a good home. Penalize opening a new bin progressively with stream
    // progress and when open bins still have usable space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let usable_space = mean_residual.max(0.0);
        let waste_penalty = 30.0 + 40.0 * progress
            + 4.0 * (usable_space / bin_capacity as f64)
            + 2.0 * open_bins_count as f64;
        // If the item is huge relative to typical residual, opening may be right.
        let big_item_relief = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += waste_penalty - big_item_relief;
        // Empty-bin base score is post_residual == capacity, already high.
    }

    // Slight preference for filling bins that are already partially full
    // (keeps number of open bins low).
    let fill_level = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_level * 8.0;

    // Mean-residual coupling: when average residual across bins is small,
    // conserve space more aggressively (reward tight fits even more).
    let residual_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= residual_pressure * (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: penalize wasted space, quadratically amplified by stream progress
    let mut score = pr as f64 * (1.0 + 1.5 * progress) + 40.0 * x * x * (0.5 + progress);

    // Reward tight fits: small post residual strongly subtracted
    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item can use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let slack_fit = (pr - nx) / cap;
            score -= 18.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
        } else {
            // post residual too small for next item: penalize dead space
            score += 12.0 * x * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Many open bins: mild pressure to consolidate into existing bins
    let ob = open_bins_count as f64;
    score -= 2.0 * (ob / (ob + 5.0)) * tightness;

    // Mean residual coupling: prefer bins close to mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize unless current bin would leave unusable sliver
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
        // but allow opening new bin if item is large relative to capacity
        score -= 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 (or near
    // multiples of common item sizes) are more reusable; penalize odd residues.
    let r = post_residual;
    let class = r % 10;
    if class == 0 {
        score -= 12.0;
    } else if class <= 2 || class >= 8 {
        score += 6.0; // awkward sliver
    }

    // Integer-division thresholds: a residual that can exactly host the next
    // item is gold.
    if next_item_size > 0 {
        if r >= next_item_size {
            let slack = r - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack % 10 == 0 { score -= 5.0; }
        } else {
            score += 10.0; // next item cannot follow here
        }
    }

    // Fraction-of-capacity harmonic bands on the post residual.
    let frac = r as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 15.0; // near-dead bin
    } else if frac < 0.3 {
        score += 4.0;
    } else if frac > 0.6 {
        score -= 4.0; // roomy bin still useful
    }

    // Last-chance bin: strongly reward filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but keep it attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 25.0 - 15.0 * fragmentation;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item likes a fresh bin
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (r as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave a dead gap too, discourage.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
        score += 20.0;
    }

    // Open-bins pressure: fewer fitting bins -> keep this bin valuable.
    if fitting_bins_count <= 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 10.0;
    }

    // Mild penalty proportional to open bins count to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual < 10 && item_size < bin_capacity;
        if open_bins_count == 0 || (fitting_bins_count == 0 && !poor_fit) || poor_fit {
            score -= 40.0;
        } else {
            score += 50.0;
        }
    }

    // Late-stream consolidation: reduce new-bin temptation near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Penalize dead space that cannot fit the next item (wasted gap)
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Mild reward when post_residual can still fit the next item (keeps bin usable)
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 5.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // open a new bin only if open bins are very full (low mean residual)
        if fragmentation < 0.25 {
            score -= 10.0;
        } else {
            score += 15.0 + 10.0 * fragmentation;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later, be more frugal with open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tight_fit * tight_fit;

    // Penalize small dead space that likely can't fit future items (typical sizes 10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    let open_f = open_bins_count as f64;
    if open_bins_count > 0 {
        let reuse_bonus = (mean_residual / bin_capacity as f64) * (open_f / (open_f + 5.0));
        score -= 8.0 * reuse_bonus;
    }

    // New-bin candidate handling: empty bin is penalized unless it's clearly better.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
        // Opening a new bin is fine if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late stream: discourage leaving many nearly-empty bins; encourage consolidation.
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small-but-nonzero residuals quadratically (dead space)
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Reward tight fits more strongly late in the stream
    score -= 8.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Lookahead: favor bins whose residual can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (pr / nxt) * (0.5 + progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * (open_bins_count as f64).sqrt();

    // Deviation from mean residual: prefer bins close to mean, slight smoothing
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity-fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "dead zones": too small for typical items (1..100, min 1).
    // Items are integers 1..=100, so any post_residual >= 1 is technically usable,
    // but residuals below ~10 are nearly useless: strong penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fill, best outcome
    } else if post_residual < 10 {
        score += 45.0; // dead space: residual too small for almost anything
    } else if post_residual < 25 {
        score += 12.0; // awkward band
    } else if post_residual < 50 {
        score -= 5.0; // half-bin or more is flexible
    } else {
        score -= 15.0; // roomy residual
    }

    // Modulo arithmetic on post_residual: reward residuals that are "harmonic"
    // with common item sizes (divisible by 5 or 10 align with many sizes).
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0; // non-aligned residual less likely to be exactly filled
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: reward, more if next item exactly fills it
            score -= 10.0;
            if next_item_size == post_residual {
                score -= 25.0; // perfect two-item chain
            }
            // harmonic bonus: post_residual - next_item_size lands on a good class
            let tail = post_residual - next_item_size;
            if tail == 0 {
                score -= 20.0;
            } else if tail % 10 == 0 {
                score -= 6.0;
            } else if tail < 10 {
                score += 10.0; // chain leaves dead space
            }
        } else {
            // next item won't fit here: this bin may become dead after this placement
            score += 8.0;
            if post_residual < next_item_size && post_residual < 15 {
                score += 12.0; // creates stranded capacity
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it only wins
    // when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.25 * (post_residual as f64);
        // open a new bin early when stream is young or many bins would help
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if mean residual across open bins is small, new bin is attractive
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // large current item with small mean residual: new bin preferred
        if item_size > 50 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // lookahead: if next item is large too, a fresh bin can host the pair
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, tighten fits (prefer small post_residual).
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Exact-fit reward relative to current residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Open-bin pressure: prefer using existing bins when many are open.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // Penalize if next item nearly fits but leaves a near-dead gap.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 5.0;
    }

    // Slight preference for fuller bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0
        * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins mildly unattractive unless existing
    // fits are terrible (post_residual dead space handled above).
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight post_residual relative to mean residual
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            let new_residual = post_residual - next_item_size;
            // Reward proportional to how little slack remains after the chain
            score -= 20.0 * (1.0 - new_residual as f64 / bin_capacity as f64);
            if new_residual < 10 {
                score -= 15.0; // nearly dead space after chain
            }
        } else {
            // next item won't fit here after placement: penalize leftover slack
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating small unusable gaps (dead space < 10, min item size 1..10)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Early in stream: be conservative, prefer opening bins for big items later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: attractive when few bins fit or item is large
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if progress < 0.2 && open_bins_count > 4 {
            score += 10.0; // avoid bin explosion early
        }
    }

    // Slight preference for filling bins with high residual (consolidation)
    score -= 0.1 * (bin_residual as f64 / bin_capacity as f64) * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: squared dead-space penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item with unusable slivers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use.
            score += 5.0 + 0.10 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when existing residuals are large relative to the item (poor fits).
    if bin_residual == bin_capacity {
        let avg_fit_pressure = mean_residual - item_size as f64;
        // Penalize new bins when current bins fit reasonably well.
        score += 45.0 - 0.35 * avg_fit_pressure.max(0.0);
        // Late in the stream, avoid opening bins with only a sliver of use left.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are open and none fit well, new bin is less penalized.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild reward for reducing fragmentation across the fleet:
    // placing into bins with below-average residual consolidates space.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference for filling larger-residual bins early (first-fit flavor),
    // fading as the stream progresses to preserve flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * bin_residual as f64;

    // Prefer bins that keep post-residual in "usable" ranges (>= 10, typical item min).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Tie-break: slightly prefer bins with more siblings fitting (keeps options open).
    if fitting_bins_count > 2 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at 0.5 residual, 0 at full/empty
    score -= poly * cap * (0.5 + progress);

    // Penalize near-empty post residual (dead space) more strongly late in stream
    score += (norm_pr * norm_pr) * cap * progress * 0.8;

    // Reward tight fits: small post residual relative to item size
    let tightness = 1.0 - (pr / (item_size as f64 + pr).max(1.0));
    score -= tightness * 12.0 * (1.0 + progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: favor bins whose post residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - norm_pr);
    }

    // Mild penalty for opening new bins early when many bins already open
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - pr) * 0.15 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // classes (multiples of small denominators) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // modulo-10 class: leftovers that are multiples of 10 are highly reusable
        if pr % 10 == 0 {
            score -= 25.0;
        } else if pr % 5 == 0 {
            score -= 10.0;
        }
        // small dead-space penalty: leftover in (0,10) is nearly unusable
        if pr < 10 {
            score += 45.0;
        }
        // integer-division thresholds: leftover in a "half-capable" band
        let half = bin_capacity / 2;
        if pr >= half {
            score -= 18.0 * (pr as f64 / bin_capacity as f64);
        } else if pr >= bin_capacity / 4 {
            score -= 8.0;
        } else {
            score += 12.0; // quarter-leftovers tend to become dead space
        }
    }

    // Coupling with lookahead item: reward leaving exactly enough room,
    // penalize leaving space that neither fits the next item nor is reusable.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 15.0 - (slack as f64).min(40.0) * 0.2;
        } else {
            // next item cannot use this leftover at all
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: prefer it only when this bin would be badly fragmented
    // and the stream still has room to consolidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        score += 20.0 + fragmentation * 0.5 - progress * 15.0;
        if pr >= bin_capacity / 2 {
            score -= 25.0; // fresh bin keeps large flexible residual
        }
    }

    // Mild preference for tighter (more filled) bins as stream progresses.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold the smallest plausible item (<= 5)
    // is "dead space" and should be strongly discouraged.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    } else if post_residual > 5 && post_residual <= 12 {
        // Risky gap: only usable by small items; partial penalty.
        score += 18.0;
    }

    // Reward very tight fits (small post_residual) beyond the raw value.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins; also mild bonus for new bin when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty proportional to open bins pressure,
        // but reward when mean residual of open bins is small (they are full-ish).
        score += 10.0 + pressure * 2.0;
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    } else {
        score -= pressure.min(10.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward
    // this placement strongly (chains a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here afterwards; slight penalty for blocking.
            score += 4.0;
        }
    }

    // Mild preference for bins with residuals close to the mean (keeps
    // residuals balanced, preserving flexibility).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 800.0; // chain of perfect fits
            } else {
                score -= 200.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize leftover dead space relative to smallest items.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Penalize creating small unusable residuals (below min item size ~1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare against mean residual: bins tighter than mean are more valuable.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate: prefer existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress; // new-bin candidate penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let slack = (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 10.0 * (1.0 - slack);
        } else {
            // Next item won't chain here: mild penalty proportional to gap.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins over emptier ones when residuals are similar.
    let fullness = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 6.0 * fullness;

    // Global state coupling: many open bins -> discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 8.0 + 0.5 * pressure;
    } else {
        score -= 2.0 / (open_bins_count as f64).sqrt();
    }

    // Deviation from mean residual: favor bins near or below mean residual
    // (keeps large residuals concentrated for big future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in stream: consolidate aggressively.
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual normalized and squared terms
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    score += 6.0 * prn * prn * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize early, allow late when it preserves large residuals
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let new_bin_penalty = 15.0 * (1.0 - progress * progress);
        score += new_bin_penalty + 0.3 * open_f * (1.0 - progress);
        // Favor opening a new bin if next item won't fit current bin's post_residual
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score -= 5.0 * progress;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (0.3 + 0.7 * progress);
        // Penalize leaving a residual just barely below next item size (dead space)
        let gap = (next_item_size as f64 - pr).abs();
        if pr < next_item_size as f64 {
            score += 0.15 * gap * gap / bin_capacity as f64;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (bin_capacity as f64);

    // Mild preference for fuller bins among many open bins
    score += 0.02 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of the post residual: residuals divisible into
    // capacity-eighth classes behave differently as dead space.
    let r = post_residual;
    let class = r / (bin_capacity / 8).max(1); // 0..8 integer class
    // Small classes (tiny dead space) are excellent; mid classes are worst.
    let class_penalty = match class {
        0 => -6.0,                       // perfect or near-perfect fit
        1 => -3.0,
        2 => 2.0,                        // awkward ~25% dead space
        3 => 4.0,                        // worst zone ~37%
        4 => 1.0,
        5 => 0.5,
        6 => -1.0,
        _ => -2.0,                       // large residual, still reusable
    };
    score += class_penalty;

    // Lookahead: reward if the next item fits into the post residual
    // (chaining placements), penalize if it almost-but-not-quite fits.
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            // Prefer chains that leave small slack again.
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - r) as f64;
            score += 2.0 * (miss / bin_capacity as f64).min(1.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large (keeps a big reusable residual) or many
    // open bins already exist and none fit well.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= bin_capacity / 2 { 3.0 } else { 0.0 };
        let crowded = (open_bins_count as f64 / 8.0).min(1.0);
        score += 12.0 - large_item_bonus - 6.0 * crowded * (1.0 - fill);
        // Early in the stream, opening bins is cheap and flexible.
        score -= 4.0 * (1.0 - progress);
    }

    // Mild pressure toward bins whose residual deviates from the mean
    // (consolidate similar residuals into harmonically compatible groups).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Reward tighter fills slightly nonlinearly.
    score -= 4.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let min_item = 1u32;
    let dead = if post_residual > 0 && post_residual < min_item { 1.0 } else { 0.0 };
    score += dead * 1000.0;

    // Penalize small gaps below typical minimum item size more aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 50.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Post-residual becomes dead space relative to lookahead item.
        score += (next_item_size - post_residual).min(20) as f64 * 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (place into bins with less residual than mean to consolidate).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so early on
    // and when existing fitting bins exist.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 40.0 + 30.0 * (1.0 - progress) + (fitting_bins_count as f64) * 10.0;
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fits (small post_residual) already favored.

    // Aggressive 2-step lookahead: reward bins where the NEXT item fits
    // exactly into the post_residual (perfect chain match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-item chain: subtract heavily.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here: penalize leftover dead space,
            // worse when the leftover is small (unusable).
            let waste = post_residual as f64 / bin_capacity as f64;
            let small_dead = (1.0 - waste).min(0.5);
            score += 25.0 * small_dead;
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 20.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a bin below-average residual is fine; leaving it far above
    // mean suggests we under-filled a relatively empty bin.
    if (post_residual as f64) > mean_residual * 1.5 && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when the current
    // item is large relative to residual and no good chain exists.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score; becomes attractive when
        // item is huge (near capacity) or lookahead suggests poor fits.
        score = 50.0;
        if item_size >= 70 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: discourage opening more.
        score += 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still fit here: reward leaving exactly usable space.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 / (1.0 + gap / 10.0);
        } else {
            // Dead space relative to lookahead item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    } else {
        // Last item: purely minimize leftover.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer reusing existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: only attractive when no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress
        // (later in the stream, reuse matters more; early on, new bins are cheap).
        let mut new_bin_cost = 30.0 + 20.0 * progress;
        // If the item would leave a large unusable gap in any bin, opening
        // a fresh bin becomes relatively more attractive.
        if post_residual > 0 && next_item_size > post_residual as u32 {
            new_bin_cost -= 8.0;
        }
        // If several bins fit, make new bin clearly worse than the best fit.
        if fitting_bins_count > 1 {
            new_bin_cost += 15.0;
        }
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth coupling with stream progress: later in the stream, weight residual waste more
    score *= 1.0 + 0.8 * progress * (1.0 - pr_norm);

    // Reward placements that leave room for the lookahead item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Penalize near-emptying a bin into dead space unless it's the only fitting bin
    if post_residual < 10 && fitting_bins_count > 1 {
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference for consolidating into bins below mean residual (balancing)
    score += 2.0 * ((bin_residual as f64) - mean_residual) / cap;

    // Mild pressure against opening new bins when many are open and fit exists
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: dead-space quality classes.
    // Residuals in [1..10] are near-perfect; [11..30] usable for small items; >30 wasteful.
    if post_residual == 0 {
        score -= 40.0; // perfect closure — best possible outcome
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else {
        score += (post_residual as f64 - 30.0) * 0.3; // penalize big dead space
    }

    // Modulo classes on post_residual relative to typical small-item sizes.
    // A residual that is a multiple of 10 (common item quantum) is more reusable.
    let pr = post_residual as i64;
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    }
    if pr > 0 && pr % 25 == 0 {
        score -= 4.0;
    }
    // Odd tiny residuals (1..5) are hard to reuse.
    if pr > 0 && pr < 10 && pr % 2 == 1 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, huge reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // next fits but leaves another residual — grade by resulting chain residual
            let chain = post_residual - next_item_size;
            score -= 8.0 - (chain as f64) * 0.15;
            if chain <= 10 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: can afford to be picky, penalize mediocre fits
        if post_residual > 40 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a decent fit,
        // or the stream is early and future items are likely large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin: high unless current fits are bad.
        let mut new_bin_cost = 25.0;
        // Early in the stream, keeping bins flexible is cheaper.
        new_bin_cost -= (1.0 - progress) * 10.0;
        // If mean residual is high, open bins are slack; a new bin is less harmful.
        new_bin_cost -= (mean_residual / cap_f).clamp(0.0, 1.0) * 8.0;
        // If next item is large, a fresh bin preserves room for it.
        if next_item_size >= 60 {
            new_bin_cost -= 10.0;
        }
        // If this bin is the only fitting one, opening a new bin is clearly worse.
        if fitting_bins_count <= 1 {
            new_bin_cost += 20.0;
        }
        score += new_bin_cost;
    }

    // Mild pressure against proliferating many open bins with large post_residuals.
    if open_bins_count > 6 && post_residual > 50 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Harsh penalty for mid-range dead space that few items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still accommodate typical small items.
    if post_residual >= next_item_size as f64 && next_item_size > 0 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: this placement creates likely dead space.
        score += 10.0;
    }

    // Last-chance pressure: strongly favor filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing residual.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 8.0 * ob;
    } else {
        // Reward using existing bins, scaled by open-bin count.
        score -= 2.0 * ob.min(20.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter fills)
    // when overall residuals are high.
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Late-stream tightening: as the stream progresses, avoid leaving gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // partial match: closer match gets bigger reward
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here: penalize dead space relative to next item
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow;
        }
    }

    // Compare residual against mean residual across open bins
    let resid_f = post_residual as f64;
    score += 0.2 * (resid_f - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - resid_f).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual_check(bin_residual, item_size, next_item_size) { 0.0 } else { 0.0 };
        // base penalty for opening a new bin
        score += 15.0;
        // less penalty late in the stream? keep constant; but if current item is large
        // and leaves bad residual, opening fresh bin is fine
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin accommodates both current and next item nicely
            score -= 10.0;
        }
        let _ = poor_fit;
    }

    // Mild preference for tighter bins overall
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

#[inline]
fn post_residual_check(_r: u32, _i: u32, _n: u32) -> bool { false }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual >= next_item_size / 2 {
            score += 8.0; // likely dead space for the next item
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread load); later, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins late in the stream.
        score += 10.0 + progress * 40.0;
        // But if open bins are all crowded (high mean residual usage), a new
        // bin may be fine.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - 5 {
            score -= 25.0; // next item is huge; fresh bin helps
        }
    } else {
        // Prefer filling bins that are already relatively full.
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used * 20.0;
        // Late in stream, extra pressure to use existing bins.
        score -= progress * 12.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    // Coupling: item size relative to residual — reward large items filling
    // large residuals.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Penalize placing small items into nearly empty bins (waste of a bin).
    if item_size < 20 && bin_residual > bin_capacity * 3 / 4 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward small post_residual, with a non-linear (quartic) preference
    let mut score = norm_post * norm_post * (1.0 + norm_post * norm_post);

    // Smooth coupling: dead space penalty grows with stream progress
    let dead_space = norm_post * norm_post * norm_post;
    score += dead_space * (0.5 + progress);

    // Interaction: post_residual vs mean residual deviation
    let mean_norm = mean_residual / cap;
    let dev = norm_post - mean_norm;
    score += 0.3 * dev * dev;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 3.0 * progress;
    }

    // Lookahead: reward post_residual that can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_slack = (post - nxt) / cap;
            score -= 0.8 * (1.0 - fit_slack) * (1.0 - 0.5 * progress);
        } else {
            score += 0.5 * (1.0 - post / nxt);
        }
    } else {
        // Last item: prefer tightest fit aggressively
        score -= 1.5 * (1.0 - norm_post);
    }

    // Mild penalty when many bins are open and residual is large (waste)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Perfect-fit reward, smoothly scaled
    if post == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "friendly" sizes.
    // Residuals that are exact multiples of common item sizes (10,20,25,50) are reusable.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fill
    } else if r % 50 == 0 {
        score -= 25.0;
    } else if r % 25 == 0 {
        score -= 15.0;
    } else if r % 20 == 0 {
        score -= 12.0;
    } else if r % 10 == 0 {
        score -= 8.0;
    } else if r < 10 {
        score -= 20.0; // dead space below minimum item size is harmless
    } else {
        score += 6.0; // awkward leftover
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == r {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // Reward proportional to how well next item divides the remaining space.
        let nr = r as f64 / next_item_size as f64;
        if nr.fract() < 1e-9 {
            score -= 20.0;
        } else {
            score -= 10.0 * (r as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    } else if next_item_size > r {
        score += 10.0; // next item can't use this bin's leftover anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins that are much emptier than average (fragmenting capacity).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Tight fits are good: reward small post_residual generally.
    score += 0.1 * (item_size as f64 - bin_residual as f64).abs();

    // Early in stream, be a bit conservative about filling bins (keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (r % 10 == 0 && r > 0) as i32 as f64;

    // New-bin candidate: keep it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.2 * mean_residual - (fitting_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest possible item (1),
    // but practically anything below a small threshold wastes capacity.
    let dead_threshold: f64 = 5.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 40.0; // near-zero gaps are worst
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the next item when it could have.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0; // keeps room for lookahead: good
        } else if pr > 0.0 && (n - pr) <= 10.0 {
            score += 12.0; // just barely breaks the next item's fit: bad
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // but if the fit creates a large dead gap while next item is big, soften
        if pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is loose.
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - tightness) * 2.0;

    // Prefer filling bins with larger mean residual (consolidate space).
    score -= (mean_residual / bin_capacity as f64) * 3.0;

    // Mild preference to use existing bins vs new bin as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so it's only chosen when fits are truly bad.
        score += 20.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.8;
        // Chain reward: if next item fits exactly after this placement
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Penalize creating dead space the next item can't use
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.2;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals near the mean
    let r = post_residual as f64;
    score += (r - mean_residual).abs() * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize wasting a large residual on a small item
    if (bin_residual as f64) > mean_residual * 1.5 && item_size < bin_capacity / 3 {
        score += 40.0;
    }

    // Early stream: be slightly conservative, favor tight fits later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // New-bin candidate: penalize mildly so we prefer good existing fits
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no good fit exists (next item is large and this one leaves big gap), allow opening
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post-residual (tight packing).
    let mut score = post;

    // Reward high fill ratio of the current bin (best-fit-like pressure).
    let fill_ratio = item / resid.max(1.0);
    score -= 12.0 * fill_ratio;

    // Penalize dead space: post residual that is too small to hold typical items.
    // Small unusable slivers are worse than moderate leftover space.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the predicted
    // post-residual, strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large (would leave small waste in a fresh bin) and existing
    // bins are crowded (low mean residual).
    if is_new_bin {
        let crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let waste = post / cap;
        score += 40.0 * waste;                 // fresh-bin waste is penalized...
        score -= 35.0 * crowding;              // ...unless all bins are nearly full
        score -= 10.0 * (item / cap);          // large items start fresh bins well
        // Early in the stream, prefer consolidating; late, allow spreading.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - t);
    }

    // Global state: many open bins with high mean residual -> discourage
    // leaving moderate leftovers anywhere (spread pressure).
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64) * (mean_residual / cap);
    }

    // Mild jitter-free tie-break by residual identity for determinism.
    score - 0.01 * (resid / cap)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), smoothed by a quadratic term
    let mut score = post;

    // Non-linear dead-space penalty: residual that is small but unusable is bad.
    // Penalize squared normalized residual so mid-range leftovers are tolerated.
    let post_norm = post / cap;
    score += 12.0 * post_norm * (1.0 - post_norm);

    // Stream-progress coupling: early on, tolerate slack (favor large post_residual
    // to keep flexibility); late, insist on tight packing. Smooth polynomial blend.
    let tightness = progress * progress;
    score -= 20.0 * tightness * (1.0 - post_norm);
    score += 15.0 * (1.0 - tightness) * post_norm * post_norm;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (nxt / cap));
        } else {
            // penalize leaving residual that neither fits next item nor is near zero
            let gap = (post - nxt) / cap;
            score += 6.0 * gap.max(0.0);
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (balanced packing), smooth Gaussian-like term.
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * (diff * diff);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small item sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Penalize dead space quadratically, but discount if residual is in a
    // "harmonic" class divisible by 10 (typical small item granularity).
    let mut dead = (pr as f64) * (pr as f64) / cap;
    if pr % 10 == 0 {
        dead *= 0.5;
    }
    if pr % 20 == 0 {
        dead *= 0.5;
    }
    score += dead;

    // Integer-division class: leftovers < 10 are almost unusable -> strong penalty.
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let exact = if next_item_size == pr { 12.0 } else { 0.0 };
        let slack = (pr - next_item_size) as f64;
        score -= exact + 6.0 - slack * 0.08;
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item cannot use this leftover; penalize tight fits that strand space.
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when the current fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.15 * (1.0 - progress)) + 20.0 * (1.0 - progress);
        // If this bin is the only fitting option, new bin is worse.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits pack better).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Small nudge: fill fuller bins first (lower post_residual wins).
    score -= frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fills that still leave room for medium items (>= 10 usable).
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate handling: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If the next item would fit in this new bin's leftover after current item,
        // opening a fresh bin can be worthwhile.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        // If no open bin fits well (high mean residual mismatch), soften new-bin cost.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Lookahead: penalize placements that leave a gap just barely too small
    // for the next item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward placements leaving room exactly usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit the minimum item are wasted.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // 2-step lookahead: reward when next item exactly/nearly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward.
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of match.
            score -= 80.0 / (1.0 + gap);
            // Extra bonus if the remainder after next item is dead space (complete fill).
            let after = post_residual as i64 - next_item_size as i64;
            if after > 0 && after < 10 {
                score -= 40.0;
            }
        } else {
            // Next item does NOT fit this bin's leftover: penalize mildly
            // (leftover is one-off dead space relative to the lookahead).
            score += 25.0 + gap * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post_residual stays
    // in line with the fleet's mean residual (balanced packing).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin has large post_residual; make it
    // unattractive unless it would otherwise be the only option. Penalize
    // proportionally to how much capacity is left unused relative to item size.
    if bin_residual == bin_capacity {
        score += 90.0 + 0.5 * item_size as f64;
        // If no other bin fits (fitting_bins_count refers to open bins; the
        // new-bin call sees the count of open fitting bins), soften penalty
        // so new bin can win when necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late-stream tightening: as the stream progresses, avoid leaving
    // medium-sized holes that are unlikely to be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (pr / 10.0).min(5.0);

    // Slight preference for fuller bins overall.
    score -= 0.2 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of the bin before placement
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small to ever be useful for typical items
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress); // early dead space is worse
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave bad dead space or fill is very low anyway
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let escape_bonus = if post_residual < 15 { -22.0 } else { 0.0 };
        // Early in stream, opening bins is cheaper; late in stream, consolidate
        let time_factor = 10.0 * progress;
        score += base_penalty + escape_bonus + time_factor;
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (consolidate waste into fewer bins), scaled by number of open bins
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.05 * residual_gap * (open_bins_count as f64).sqrt();

    // Mild reward for filling already-open bins more fully as stream progresses
    score -= 10.0 * fill * (0.5 + 0.5 * progress);

    // Penalize spreading across many open bins when residuals are large
    if open_bins_count > 3 && bin_residual > 50 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize very small residuals (dead space) with smooth quartic term
    score += cap * norm_pr.powi(4) * (1.0 + progress);

    // Reward tight fits (small post_residual) non-linearly
    score -= (1.0 - norm_pr).powi(3) * item_size as f64 * 0.15;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post residual can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: keep it competitive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 40.0 * (1.0 - progress) - (fitting_bins_count as f64).recip() * 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in (0,10] is nearly unusable
    // for items >= 10; classes via integer division thresholds.
    let dead_class = post_residual / 10; // 0..10
    score += match dead_class {
        0 => -6.0,           // post_residual in 0..=9: near-perfect fill
        1 => 2.0,            // 10..=19: fits smallest items
        2..=3 => 4.0,        // 20..=39: moderately usable
        4..=6 => 6.0,        // 40..=69
        _ => 3.0,            // 70..=99: still very usable, mild penalty
    };

    // Exact / modular fit rewards: post_residual divisible into clean classes
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward if next item fits the post-residual well (harmonic match)
    if next_item_size > 0 && next_item_size <= post_residual {
        let look_fit = (post_residual - next_item_size) as f64;
        score += look_fit * 0.15;      // prefer bins where next item also fits tightly
        if look_fit < 10.0 {
            score -= 5.0;              // chain of tight fits
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 1.5;                  // dead space likely; mild penalty
    }

    // Penalize opening new bins when plenty of open capacity exists
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins' slack
        score += 12.0 + 0.3 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 4.0;              // big upcoming item: fresh bin is attractive
        }
        if post_residual as f64 > mean_residual * 1.5 {
            score -= 2.0;
        }
    }

    // Mild waste-pressure term relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).clamp(-20.0, 20.0) * 0.1;

    // Early-stream: be a bit more willing to consolidate (fewer bins early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1),
    // but practically: gaps below ~10 cannot absorb typical items well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins or leaving bins behind).
    let ob = open_bins_count as f64;
    score += 0.35 * ob;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item would NOT fit in the post residual but would fit a fresh bin,
    // slightly penalize creating a blocking gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Mild preference for tighter bins (closer to mean residual being low).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin, more so when good
    // alternatives exist and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count >= 1 {
            score += 10.0 * (fitting_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * diff; // penalize mismatch with lookahead
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        }
        // if next item cannot fit here anyway, mild bonus for keeping space usable
        if next_item_size > post_residual {
            score -= 3.0;
        }
    } else {
        // last item: prefer tightest fit, no future to plan for
        score -= 5.0;
    }

    // Relative-to-mean residual coupling: bins with residual above mean are more "flexible";
    // favor using below-mean (tight) bins to preserve flexibility elsewhere.
    let resid = post_residual as f64;
    score += 0.35 * (mean_residual - resid);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize opening a brand-new bin when open bins exist and could fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
        // but if lookahead item is large, a fresh bin may be preferable
        if next_item_size > 50 {
            score -= 6.0;
        }
    }

    // Dead-space penalty: very small post-residual that likely can't fit future items
    // (items >= 1, so any residual is usable, but tiny residuals waste capacity)
    if post_residual < 10 && post_residual > 0 {
        score += 4.0;
    }

    // Stream progression: early on, be conservative about filling bins tightly;
    // later, squeeze harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - resid / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale residual by fill ratio so full bins win.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 0.9 * fill * cap * 0.5;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward leaving space exactly for the next item,
    // penalize leaving space that is just barely too small for it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 12.0 * (1.0 - (ni / cap));
        } else if (post_residual as f64) > 0.0 && (post_residual as f64) < ni {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, but the penalty should
    // fade when open bins are crowded (low mean residual => poor fits likely).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 30.0 + 20.0 * progress;
        if mean_residual < 25.0 {
            penalty -= (25.0 - mean_residual) * 1.2;
        }
        penalty -= crowding * 10.0;
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty.max(0.0);
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Slight early-stream preference for keeping bins balanced (avoid
    // committing one bin to slivers while others stay empty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 && bin_residual != bin_capacity {
        score += 3.0 * (1.0 - (bin_residual as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr
        - 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr
        + 8.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: reward tight fits more strongly as stream advances.
    score -= 15.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.2;

    // Penalize dead space that cannot fit typical items, scaled by progress.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (1.0 + 2.0 * progress);
        } else {
            score -= 4.0 * progress * (1.0 - pr / (ns + cap));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when residuals are already high.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Align with mean residual: prefer bins below mean residual (tighter than average).
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 60.0;
    } else if pr > 10 && pr <= 20 {
        score += 25.0;
    } else if pr > 20 && pr <= 50 {
        score += 5.0;
    }

    // Modulo-based awkwardness: residuals of form 100 % k leave small slivers
    if pr > 0 && pr < 34 && (100 % pr.max(1)) < 5 {
        score += 12.0;
    }

    // Lookahead coupling: does the next item fit the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, stronger for tight chains
            score -= 15.0 + 0.2 * (pr as f64 - next_item_size as f64);
        } else {
            // leftover cannot host next item: penalize proportional to closeness of miss
            score += 10.0 + 0.5 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: slight preference for tightest fit emerges naturally,
    // but discourage wasting a nearly-full bin when alternatives abound
    if fitting_bins_count > 2 && pr > 50 {
        score += 8.0;
    }

    // New-bin candidate: keep it attractive only when it beats bad fits,
    // mildly discouraged early when open bins exist
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 20.0 + 0.5 * open_bins_count as f64;
        } else {
            score -= 50.0;
        }
    }

    // Stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap below minimum item size
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfectly reusable residual: post_residual can fit next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no open bin is a good fit (mean residual is tight).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual as f64 - item_size as f64) - mean_residual;
        score = 45.0
            + 0.35 * open_bins_count as f64
            - poor_fit * 0.8
            - progress * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also serve lookahead item
        }
        if post_residual == 0 {
            score -= 35.0; // item exactly fills a fresh bin
        }
    }

    // Mild pressure to consolidate into fewer bins as the stream grows.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize dead space too small for any plausible next item (min size 1, but
        // relative to item scale): dead space below next_item_size wastes capacity.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Reward bins tighter than average (well-filled bins get priority).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: neutral-ish base but penalize slightly so it is
    // chosen only when open bins fit poorly; reward it when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size == item_size {
            // opening fresh bin may allow pairing later; mild relief
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - t) * (1.0 - t);

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // typical items are larger) are wasted; penalize sharply below 10.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when existing bins have ample room.
        if mean_residual >= item_size as f64 {
            score += 6.0 + mean_residual / bin_capacity as f64 * 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
        // Few open bins relative to stream length -> new bins are fine.
        if open_bins_count < 4 {
            score -= 4.0;
        }
    } else {
        // Reward filling existing bins proportionally to how full they get.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 6.0 * fill;
    }

    // Global balance: prefer bins whose residual deviates favorably from the mean.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer minimal post_residual, with non-linear sharpening.
    let base = post * (1.0 + 0.8 * (post / cap).powi(2));

    // Smooth coupling of fit quality with stream progress:
    // early on, be slightly lenient; late, strongly punish wasted space.
    let progress_weight = 1.0 + 1.5 * progress * progress;
    let mut score = base * progress_weight;

    // Dead-space penalty: post_residual too small for any plausible future item
    // (sizes 1..=100), smoothly scaled.
    let dead_threshold = 9.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 4.0;
    }

    // Lookahead synergy: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 * (1.0 - post / cap);
    }

    // New-bin candidate: smooth penalty that decays with progress and with
    // how bad the best alternative fit would be (approximated via mean_residual).
    if is_new_bin {
        let congestion = (open_bins_count as f64).ln1p();
        let penalty = 15.0 + 20.0 * (1.0 - progress) + 3.0 * congestion;
        // If mean residual is small, open bins are nearly full anyway; soften penalty.
        let softening = (mean_residual / cap).powi(2) * 10.0;
        score += penalty - softening;
    }

    // Mild preference to balance residuals across bins.
    score += 0.5 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define
    // "dead-space classes". Small odd residues are nearly unusable for
    // future items (min size 1..100 unknown, but granularity 10 is common),
    // so penalize low-value leftover classes.
    let post = post_residual as u32;
    let class = post % 10;
    let class_val: f64 = match class {
        0 => -6.0,          // perfectly reusable chunk
        1 | 2 | 3 => 5.0,   // nearly dead space
        4 | 5 | 6 => 2.0,
        7 | 8 | 9 => 0.0,
        _ => 0.0,
    };
    score += class_val;

    // Integer-division threshold: post_residual bucketed by fifths of capacity.
    let fifth = (cap / 5.0) as u32;
    let bucket = post / fifth;
    score -= match bucket {
        0 => 8.0,           // bin almost exactly filled -> excellent
        1 => 4.0,
        2 => 0.0,
        3 => -2.0,
        _ => -4.0,          // barely dented bin, fine to keep loose
    };

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
            // Harmonic bonus: next item leaves another class-0 residue
            if (post_residual as u32 - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; penalize more if this was the last chance.
            score += 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer terrible fits. Base-penalize the fresh bin slightly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Mean-residual coupling: when open bins are generally loose, tighten
    // preference toward best-fit (small post_residual) even more.
    let tight = (mean_residual / cap).clamp(0.0, 1.0);
    score += (post_residual as f64 / cap) * (1.0 - tight) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are small but nonzero are nearly unusable.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward filling bins deeply (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer compacting into existing ones.
    score += 0.8 * open_bins_count as f64;

    // Penalize bins whose residual deviates upward from mean (prefer balanced small residuals).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit now but not after this placement: mild penalty.
        score += 8.0;
    }

    // New-bin candidate handling: make empty bin attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; dead-space logic above already applies via post_residual.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual to next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if gap == 0.0 {
            score -= 20.0; // exact 2-step fit bonus
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space: next item cannot follow here
        score += 8.0 + (post_residual as f64) * 0.15;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin when item would leave very tight fit anyway
        if post_residual <= 5 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for filling bins deeply early vs late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Penalize large dead space relative to typical future item sizes.
    score += 0.15 * (post_residual as f64).powf(1.3) / 10.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // stranded sliver that next item cannot use
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large or state is crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let penalty = 55.0
            - 25.0 * (item_size as f64 / 100.0)
            - 10.0 * progress
            - 0.5 * crowding;
        score += penalty.max(5.0);
    }

    // Mild preference for bins with below-average residual (keep tight bins tight).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    // Prefer consolidating into fewer bins when many are open.
    if bin_residual < bin_capacity && open_bins_count > 4 {
        score -= 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // base: prefer small post residual
    let mut score = post;

    // non-linear polynomial coupling of post residual with stream progress
    let poly = norm_post * norm_post * (1.0 - norm_post);
    score += 40.0 * poly * (0.5 + progress);

    // penalize large dead space more as stream progresses
    score += 25.0 * norm_post * norm_post * progress;

    // reward tight fits (small post residual) with smooth term
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - 0.5 * progress);

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (next_item_size as f64 / cap);
    }

    // mean residual coupling: prefer bins below mean residual (tighter bin)
    let mean_norm = mean_residual / cap;
    score += 10.0 * (norm_post - mean_norm) * (0.3 + progress);

    // new-bin candidate: penalize opening new bin unless residual very large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 8.0 * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact halves/quarters are reusable slots
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 25.0; // round residual, easy to pair later
    } else if pr % 5 == 0 {
        score -= 10.0;
    } else {
        score += 8.0; // odd dead space
    }

    // Integer-division threshold classes on residual fraction
    let frac = post_residual as f64 / cap;
    if frac < 0.1 {
        score -= 5.0; // nearly closed bin, good
    } else if frac > 0.5 {
        score += 15.0; // wasting a large residual on a small item
    }

    // Lookahead coupling: can next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0; // chain placement possible
            // harmonic bonus if next item lands on a round class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 12.0; // placing here blocks next item from this bin
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0; // strongly prefer using the only fitting bin
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive when open bins are crowded
        let crowded = mean_residual / cap < 0.15 && open_bins_count > 0;
        if crowded {
            score -= 10.0;
        } else {
            score += 40.0 + (open_bins_count as f64) * 2.0; // discourage proliferation
        }
    }

    // Mild progression-aware tightening: later in the stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += frac * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to ever hold a
    // future item (min item size 1..100 unknown; treat tiny gaps < 10
    // as dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Gaps that can only fit very small items are mildly penalized.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // If the lookahead item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If lookahead item cannot fit in post residual (creating likely
    // dead space for the next step), penalize proportionally.
    if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading and
    // favor tight fills; with few bins, tolerate more spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, softened when many bins
        // are already open and mean residual is low (poor fits likely).
        score += 30.0 - 0.1 * open_bins_count as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Mild preference for filling bins with large residuals relative to mean.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 == n {
            score -= 40.0; // perfect chain: post residual matches next item
        } else if post_residual >= next_item_size {
            // slack after the next item would also be placed
            let slack = post_residual as f64 - n;
            score -= 25.0 - slack * 0.15;
        } else {
            // next item cannot follow: penalize leftover dead space
            score += 6.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.5;

    // Last chance: only fitting bin, avoid opening a new bin if fit is decent.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // Penalize very small post residuals that create unusable slivers (unless next item uses them).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 12.0;
    }

    // Late in the stream, prefer closing bins out (lower open-bin residual diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild penalty for spreading across many bins when mean residual is high.
    if mean_residual > 30.0 && open_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fills are perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    } else {
        // Penalize large dead space quadratically.
        score += (post_residual as f64) * (post_residual as f64) * 0.02;
    }

    // Lookahead: strongly reward leaving exactly room for the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 18.0 * (1.0 - gap / (bin_capacity as f64));
        }
        // If this placement makes the bin useless for the (small) next item, penalize.
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: prefer exact fill even more.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // Time horizon: early in the stream, be more selective (avoid fragmenting);
    // late in the stream, just close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    if progress < 0.2 {
        score += 6.0 * (1.0 - progress / 0.2) * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state: if many bins are open and this bin is near the mean residual,
    // slight bonus to consolidate; if mean residual is high, prefer filling fat bins.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 4.0 / (1.0 + dev);
        if mean_residual > bin_capacity as f64 * 0.5 && bin_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 35.0 - 20.0 * desperation + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let p = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let n = next_item_size as f64;
    let mut score = p;

    // Reward tight fits: subtract proportional to how much of the bin is consumed.
    score -= 0.5 * (cap - p);

    // Dead-space penalty: if the leftover cannot hold the lookahead item,
    // that residual is likely wasted; penalize more as the stream progresses.
    if n > 0.0 && p > 0.0 && p < n {
        let waste = (n - p) / cap;
        score += 60.0 * waste * (1.0 + t);
    }

    // Mild reward when the residual can still accommodate the next item.
    if n > 0.0 && p >= n {
        score -= 8.0 * (1.0 - p / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin, more so later in the
    // stream and when many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + 20.0 * t + 3.0 * open_bins_count as f64;
    }

    // Smooth non-linear coupling: penalize residuals far from the mean residual
    // (encourages homogeneous residual profiles across bins).
    let dev = p - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in the lowest class (tight fit)
    // are rewarded; large leftover classes are mildly penalized.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as u32; // 0..=3 harmonic classes
    score -= match class {
        0 => 12.0, // residual < 25% of capacity: excellent compaction
        1 => 4.0,
        2 => 0.0,
        _ => 6.0,  // large leftover: wasteful class
    };

    // Lookahead coupling: if the next item can still fit in the leftover,
    // this placement preserves usability (reward); otherwise the leftover
    // becomes potential dead space (penalize, scaled by next item size).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 0.08 * next_item_size as f64;
        }
    } else {
        // Last item: any residual is pure waste; prefer the tightest.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin, but relax
    // the penalty when existing residuals are small relative to the item
    // (poor fits available) or the item is large.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If mean residual across open bins is much smaller than the item,
        // opening a bin is more acceptable.
        if mean_residual < item_size as f64 {
            new_bin_penalty -= (item_size as f64 - mean_residual).min(20.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 10.0 * progress;
        // Large items fragment bins less if placed fresh.
        if item_size >= bin_capacity / 2 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Integer-division threshold: leftover space that cannot hold even a
    // mid-size item (>= 20) is near-dead; treat small-but-nonzero leftovers
    // more kindly than mid-size gaps (harmonic modulo classes).
    if post_residual > 0 && post_residual < 20 {
        score -= 3.0; // tiny scraps are cheap
    } else if post_residual >= 20 && post_residual < 50 {
        score += 2.0; // awkward middle gap
    }

    // Mild pressure to fill bins that are already mostly full.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any future
    // item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Gaps that could only fit tiny items are near-waste too.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit: strongly reward closing a bin exactly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit the post residual, mildly penalize.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: residual == capacity. Only attractive when current bins
    // are fragmented (low mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset when open bins are crowded.
        score += 20.0;
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Later in the stream, prefer reusing bins to keep bin count low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for bins whose residual is close to the item (tight fit).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item uses leftover space
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted residual that's too small to be useful
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - waste);
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        // opening a new bin costs ~1 bin; only attractive if best existing fit leaves big waste
        score = 100.0 - 0.0;
        // if next item is large, a fresh bin is more attractive
        score -= 0.1 * next_item_size as f64;
        // if many open bins with high mean residual, prefer consolidating into open bins
        score += 0.2 * mean_residual;
        // early in stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        // if this is the only fitting bin scenario, discourage new bin
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    }

    // mild penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.35 * progress * progress);
    // Penalize small unusable residuals with a smooth bump around low pr
    let waste = 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;
    // Reward tight fits (low post residual) more strongly as stream progresses
    let tight_bonus = -8.0 * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
    // Lookahead: reward leaving room for the next item, penalize otherwise
    let lookahead = if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr { -4.0 * (ni / cap) } else { 6.0 * ((ni - pr) / cap) }
    } else { 0.0 };
    // Last-chance bin: smooth reward for using it
    let last_chance = if fitting_bins_count == 1 { -10.0 } else { 0.0 };
    // Slight penalty when bin residual far deviates from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    let dev_pen = 2.0 * dev * dev;
    // Mild new-bin penalty that decays with progress
    let new_bin_pen = if bin_residual == bin_capacity { 15.0 * (1.0 - progress) + 2.0 } else { 0.0 };

    base + waste + tight_bonus + lookahead + last_chance + dev_pen + new_bin_pen
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common small item sizes) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 6.0;
            }
        }
        // small dead-space penalty grows superlinearly for tiny leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 4.0;
        }
        score -= harmony;
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
            // harmonic bonus: post_residual - next_item leaves a clean class
            let diff = post_residual - next_item_size;
            if diff % 10 == 0 || diff % 25 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize large waste
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        // early in stream, new bins are cheap; later, discourage
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * pressure + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size >= 80 {
            score -= 15.0; // big next item favors a fresh bin
        }
    } else {
        // mild penalty per extra open bin to consolidate load
        score += (open_bins_count as f64) * 0.5;
        // favor bins with residual close to mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // integer-division threshold on post_residual tiers
    let tier = post_residual / 20; // 0..5
    score -= tier as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize small unusable gaps harder than large ones.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for any item (min size 1..100, but small gaps waste capacity)
        score += (10.0 - pr) * 6.0; // strong penalty for tiny useless gaps
    } else if pr >= 10.0 && pr <= 30.0 {
        // awkward mid-range gap: only items <= pr fit; penalize moderately
        score += (30.0 - pr) * 0.8;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize unless current bins are badly fragmented
        score += 12.0 + pressure * 0.5;
        // Allow new bin early in stream or when mean residual is large (fragmented state)
        score -= mean_residual * 0.05;
        if progress < 0.1 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // next item won't fit here; slight penalty for stranding capacity
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.35 * next_item_size as f64;
    }

    // Penalize dead space that cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.30 * (mean_residual - post_residual as f64);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless it enables a perfect pair.
    if bin_residual == bin_capacity {
        let pair_bonus = if next_item_size > 0 && post_residual >= next_item_size { 12.0 } else { 0.0 };
        score += 10.0 - pair_bonus;
    }

    // Tight-fit reward for near-perfect fills.
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Late-stream consolidation: tighten selectivity as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    }
    if post_residual >= 10 {
        // usable residual is fine; slight reward proportional to item consumed
        score -= 0.15 * item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to mismatch
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.10 * gap;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_capacity as f64).max(0.0) / bin_capacity as f64;
        // Base cost of a fresh bin, discounted when bins are fragmented
        // or item is big (poor fits likely elsewhere).
        let big_item_bonus = if item_size >= 50 { 10.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.9
            - fragmentation * 40.0
            - big_item_bonus
            - 15.0 * (1.0 - progress)
            + 10.0 * progress;
        // If a decent fit exists among open bins, discourage new bin.
        if fitting_bins_count > 0 {
            let best_possible = post_residual; // same value but compare via mean
            if mean_residual > item_size as f64 * 1.5 {
                score += 20.0;
            }
            let _ = best_possible;
        }
        // If next item is huge, a fresh bin may chain well.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are healthy.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score += 0.3 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); late in stream,
    // tolerate larger residuals slightly since fewer items remain.
    let mut score = pr * (1.0 + 0.35 * progress * norm_pr);

    // Smooth cubic term: penalize mid-range residual dead space more than
    // very tight or very loose residuals (non-linear dead-space curve).
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5).abs() * cap * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly reward use.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward residuals that still fit the next item,
    // penalize residuals that waste space just below next_item_size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - progress);
        } else {
            // near-miss penalty scaled by how close the miss is (smooth)
            let miss = (ni - pr) / ni;
            score += 8.0 * (1.0 - miss * miss);
        }
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * ((mean_residual - pr).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues modulo small integers
    // classify "usable" leftovers. Residues divisible by 10 pair well
    // with typical item sizes (10..80 grid), tiny odd residues are dead space.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 12.0; // grid-aligned leftover, reusable
        }
        if r < 10 {
            score += 25.0; // dead space below smallest item
        }
        if r % 2 == 1 {
            score += 4.0; // odd residue less likely to be matched
        }
        // integer-division thresholds: how many "average" items fit
        let avg_item = 45u32;
        let slots = r / avg_item;
        score -= slots as f64 * 8.0;
    }

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // guaranteed perfect chain
        } else if next_item_size <= post_residual {
            score -= 30.0;
            // harmonic coupling: gcd-like class match
            let g = gcd(next_item_size, if post_residual == 0 { 1 } else { post_residual });
            if g > 5 {
                score -= g as f64 * 0.5;
            }
        } else {
            // next item won't fit here: leftover becomes waiting space
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fill
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin would leave a large awkward remainder
    if bin_residual == bin_capacity {
        // fresh bin: neutral baseline, slight preference when item is large
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced open
        }
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items start fresh bins well
        }
        // avoid opening bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    } else {
        // mild penalty for spreading across many bins
        score += open_bins_count as f64 * 0.2;
        // deviation from mean residual: prefer bins near mean (balanced)
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).sqrt() * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open-bin pressure is high.
        score += 15.0 + pressure;
        // But if current item is large and few bins can take it, allow new bin.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, scaled by pressure.
        score -= pressure * 0.3;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if next item cannot use the leftover space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let residual_gap = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += residual_gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary term: dead space, weighted more for small unusable residuals.
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Penalize tiny dead space harshly (wasted capacity that's hard to fill).
        if dead < 10.0 {
            score += 30.0 * (10.0 - dead);
        } else {
            score += dead * 0.5;
        }
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.6; // exact match (slack 0) gets biggest bonus
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; mildly penalize tight fits that block lookahead.
        score += 8.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates from the mean
    // in a way that reduces fragmentation (place into tighter-than-average bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Prefer opening a new bin for large items; penalize for small items.
        score += 20.0 - 30.0 * fill_ratio;
        if fitting_bins_count > 0 {
            score += 10.0; // discourage ignoring existing open bins
        }
    }

    // Early stream: be a bit more open to new bins (build structure early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Slight preference for tighter fits overall.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, but dead space
    // below the minimum item size is pure waste — penalize it extra.
    if post_residual < 10 {
        score -= 30.0 - (post_residual as f64); // perfect fill gets biggest bonus
    } else {
        // gentle quadratic penalty on larger leftovers
        score += (post_residual as f64).powi(2) / 400.0;
    }

    // Fit ratio: reward bins whose residual is close to the item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item could use this bin's post_residual,
    // reward leaving a compatible gap; otherwise penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx && (post_residual as u32) >= next_item_size {
            score -= 12.0; // chain potential
        } else if post_residual > 0 && (post_residual as f64) < nx {
            score += 6.0; // gap too small for next item: dead space risk
        }
    }

    // Global state: many open bins with high mean residual → prefer reusing
    // existing bins rather than opening new ones.
    let mean_r = mean_residual;
    if open_bins_count > 0 {
        score -= 5.0 * (mean_r / bin_capacity as f64);
        if open_bins_count > 4 {
            score -= 3.0; // consolidation pressure when many bins are open
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize it mildly so it only wins when fits are poor, but reduce the
    // penalty late in the stream (less future to amortize bin count).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress;
        // If the current bin would leave a large unusable remainder, opening
        // a fresh bin becomes attractive.
        if post_residual > 0 && post_residual < item_size {
            score -= 25.0;
        }
    }

    // Time-horizon term: early in the stream, keep bins flexible (favor
    // moderate post_residual); late, maximize fill regardless.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with stream progress.
    // Late in the stream, large dead space is increasingly costly.
    score += 0.6 * (pr * pr / c) * (0.5 + 0.5 * progress);

    // Reward bins whose residual can still host the lookahead item (smooth, not hard threshold).
    let next = next_item_size as f64;
    if next > 0.0 {
        let fit_gap = (pr - next) / c;
        let reward = if fit_gap >= 0.0 {
            fit_gap.exp() - 1.0
        } else {
            -((-fit_gap).exp() - 1.0)
        };
        score -= 4.0 * reward;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // (avoid opening a new bin), scaled smoothly by how full the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - pr / c;
        score -= 8.0 + 6.0 * tightness;
    }

    // Penalize opening a brand-new bin when existing bins are reasonably fragmented:
    // new-bin candidate has bin_residual == bin_capacity; make it attractive only
    // if the item is large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / c;
        let fragmentation = mean_residual / c;
        score += 12.0 * (1.0 - size_ratio) * (0.5 + fragmentation);
    }

    // Mild preference for tighter fits among comparable residuals (non-linear in fill ratio).
    let fill = (bin_residual as f64) / c;
    score -= 2.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // modulo 10 (aligned with capacity fractions of C=100). Small residues that
    // cannot host the smallest item (size >= 1) are dead space -> penalize.
    let residue_class = post_residual % 10;
    if post_residual > 0 && residue_class != 0 {
        // Fractional dead space penalty: smaller unusable slivers hurt more.
        score += (10 - residue_class) as f64 * 0.8;
    }
    if post_residual < 10 && post_residual > 0 {
        score += 12.0; // near-dead sliver
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Integer-division thresholds: how many "typical" items (size ~ next_item_size)
    // could still fit in the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits = post_residual / next_item_size;
        score -= fits as f64 * 6.0;
        // If the next item exactly matches the leftover, strongly favor.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual - next_item_size < 10 {
            score -= 8.0; // leaves a small but possibly usable remainder
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; this bin becomes dead space after placement.
        score += 10.0;
    }

    // Last-chance bin: only one open bin fits the item -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class.
    if bin_residual == bin_capacity {
        // Compare against expected leftover quality: opening fresh is good only if
        // the item is large relative to capacity (harmonic class of item itself).
        let item_class = item_size / 10;
        score = 55.0 - (item_class as f64) * 4.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can also host the lookahead
        }
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // Stream progression: late in the stream, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= post_residual as f64 * progress * 0.5;
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space pressure grows as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Prefer bins tighter than average (better packing density).
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += 20.0 * (1.0 - fit_ratio);

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly/nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted lookahead space.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Penalize deviating from mean residual (avoid stranding outliers).
    score += 0.5 * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it's early or residual is unusable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = post_residual as f64 > 0.0 && item_size > bin_capacity / 2;
        score += 30.0 - 10.0 * progress;
        if dead { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        let mut penalty = 25.0 - 20.0 * tightness;
        if next_item_size > 0 && next_item_size <= post_residual {
            penalty += 40.0; // next item could use this new bin too
        }
        if fitting_bins_count == 0 {
            penalty -= 60.0;
        }
        if post_residual < 20 {
            penalty -= 35.0; // big item nearly fills a fresh bin
        }
        score += penalty;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            score += 5.0;
        }
    }

    // Global state: with many open bins, prefer consolidating into existing ones.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near/below mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Time horizon: early in the stream, be conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - x));

    // Smooth polynomial coupling: penalize mid-range residuals more as stream advances
    let mid = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += 12.0 * mid * mid * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 20.0 * progress * (-pr / cap).exp();

    // Last-chance bin bonus: smooth reward when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    let small = (x * 10.0).min(1.0);
    if x > 0.0 && x < 0.05 {
        score += 10.0 * (1.0 - small / 0.05) * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward; smooth via ratio
    if next_item_size > 0 {
        let fits = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let near = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / cap).min(1.0);
        score -= 8.0 * fits * near;
        score += 4.0 * (1.0 - fits) * near * progress;
    }

    // Mild penalty for scattering across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    // New-bin candidate: neutral-ish baseline, slightly penalized so good fits win
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod capacity fractions
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Penalize residuals in "dead zones" that few item sizes can use
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 12.0; // nearly-full, tiny dead space
    } else if post_residual <= quarter {
        score += 4.0;
    } else if post_residual < half {
        score += 10.0; // awkward mid-low residual
    }

    // Harmonic bonus: residual exactly divisible by common item sizes
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // extra reward for tight chain fit
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin if current bin would waste a lot
    if bin_residual == bin_capacity {
        // neutral baseline with slight preference for good future packing
        score = (bin_capacity - post_residual) as f64 + 2.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0;
        }
    }

    // Progress-based mild pressure to consolidate early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (mean_residual / bin_capacity as f64);

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically mid/large), so penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Medium gaps (11..=25) are moderately wasteful.
    else if post_residual > 10 && post_residual <= 25 {
        score += 6.0;
    }

    // Reward tight fits (post_residual near 0) proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Perfect fit: strong bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // New-bin candidate: penalize so it's only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * (open_bins_count as f64);
        // But if the next item would combine well with a fresh bin strategy,
        // soften slightly when current item is large.
        if item_size >= 70 {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the leftover: the gap is truly dead space.
        score += 8.0;
    }

    // Slight preference for bins with residuals close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but heavily penalize tiny dead space
    // that can't fit a typical small item (<= 20).
    if post_residual < 20 {
        score -= 25.0; // near-perfect fill, excellent
    } else if post_residual < 35 {
        score -= 8.0;
    } else if post_residual > 70 {
        score += 12.0; // leaving a huge hole is wasteful
    }

    // 2-step lookahead: if the next item fits exactly in the post_residual,
    // this is a perfect chain placement — reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 40.0;
        } else if post_residual as f64 >= nxt {
            score -= 10.0; // next item still fits here: good chaining
        } else {
            // next item won't fit: dead space unless another bin takes it
            score += (post_residual as f64 - nxt).abs() * 0.3;
        }
        // Bonus when this bin's residual matches next item while current fit is tight
        if next_item_size <= post_residual && item_size + next_item_size == bin_residual {
            score -= 15.0; // exact two-item fill of the bin
        }
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (i.e., fuller bins) to consolidate waste.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score -= 20.0; // nearly perfect last-chance fit
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when no reasonable open bin exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 5.0 + progress * 20.0;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 10.0; // next item is huge, a fresh bin may serve it
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits elsewhere, new bin is fine
        }
    }

    // Mild consolidation pressure: with many open bins, favor filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

