    }

    // New-bin candidate: penalize opening a new bin, more so later in the stream
    // and when many bins are already open with usable mean residual.
    if bin_residual == bin_capacity {
        score += 60.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        score += 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Opening a new bin is acceptable if item is huge and fits nothing else well.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for bins with larger residuals when many bins are open (consolidation).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Early stream: be slightly more willing to spread items (exploration).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Core: prefer small post-residual, with non-linear polynomial shaping
    let mut score = norm_post * (1.0 + 2.0 * norm_post * norm_post);

    // Stream-progress coupling: tighten packing as stream advances
    score += 0.8 * progress * norm_post * norm_post;

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 1.5 * ((nxt - pr) / cap) * (0.5 + progress);
        } else {
