            score -= 0.6 * (1.0 - ((pr - nxt) / cap).abs()) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * norm_post;

    // Deviation from mean residual: prefer bins whose residual is near/below mean
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make empty bins moderately attractive only when
    // post-residual would be large (good for future big items)
    if bin_residual == bin_capacity {
        score = 1.2 - 0.8 * item_size as f64 / cap + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
