        score += (next_item_size as f64 / post_residual.max(1) as f64) * 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: it's only attractive when current leftover is truly bad.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when few bins open or stream is young
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let cost = 30.0 + 20.0 * (1.0 - progress);
        score = post_residual as f64 + cost;
