    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted early, penalized late.
        score = bin_capacity as f64 * (0.9 - 0.4 * progress);
        // Opening a bin is fine if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Late in the stream, favor using existing bins even more.
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, tolerate larger
    // post_residual less (dead space increasingly costly).
    score += 15.0 * norm_pr * norm_pr * progress;

    // Reward using bins that are the only fitting option (avoid opening new bins).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score -= 4.0 * (1.0 - 1.0 / (fitting_bins_count as f64 + 1.0));
    }

    // Lookahead coupling: if next item fits exactly into the projected residual,
    // strongly favor this bin; penalize residuals that nearly-but-not fit next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 10.0 * (1.0 - (diff / cap).powf(2.0));
        } else {
            score += 5.0 * ((-diff) / cap);
        }
    }

    // Slight penalty proportional to deviation of bin residual from mean residual,
    // encouraging homogenization of open-bin residuals (smooth quadratic).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild incentive to keep number of open bins low, scaled by progress.
    score += 0.5 * open_bins_count as f64 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/2, 1/3, 1/4, 1/5)
    let cap = bin_capacity as f64;
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;
    let fifth = cap * 0.2;

    let pr = post_residual as f64;

    // Reward near-exact fits at harmonic class boundaries
    if pr <= fifth {
        score -= 40.0; // tiny dead space, excellent
    } else if pr <= quarter {
        score -= 22.0;
    } else if (pr - third).abs() < 4.0 {
        score -= 15.0; // post-residual close to 1/3 capacity: harmonically reusable
    } else if (pr - half).abs() < 4.0 {
        score -= 10.0; // half-capacity residual: very reusable class
    } else if pr < third {
        score += 12.0; // awkward middle zone: dead-space risk
    } else if pr < half {
        score += 6.0;
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 8.0; // aligns with typical item granularity
    } else {
        score += (5 - (m10 as i32).abs_diff(0).min(5)) as f64 * 0.5;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack.min(18.0); // reward chains: next item fits well
            if slack == 0 {
                score -= 15.0; // perfect pair completion
            }
        } else {
            score += 10.0; // next item won't fit here: residual likely wasted
        }
    } else {
        // Last item: prefer tightest fit only
        score = pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual = cap - item_size; judge by how much space is left
        score += 25.0; // baseline penalty for opening new bin
        if post_residual <= (cap * 0.2) as u32 {
            score -= 60.0; // big item nearly fills new bin: good reason to open
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative
        }
    }

    // Progress-based bias: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.15 * progress);

    // Open bins pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * pr * 0.05;

    // Mean residual alignment: bins far from mean residual are less attractive
    score += ((pr - mean_residual).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post_residual that exactly matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect 2-step match: strong bonus.
        if gap == 0.0 {
            score -= 25.0 + item_size as f64 * 0.2;
        } else {
            // Partial reward decaying with the gap; small gaps still attractive.
            score -= 15.0 * (-gap / 12.0).exp();
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this bin's remainder.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize post_residual that is too small to ever hold typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Favor tight fits: small post_residual relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Relative to mean residual: bins with residual far below mean are already tight;
    // prefer filling tighter bins rather than fragmenting looser ones.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Late in the stream, avoid opening new bins; prefer existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // can't hold typical items (<= 100) matters more later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large unusable gaps more as stream progresses.
    let dead_penalty = (post_residual as f64 / bin_capacity as f64).powf(1.5);
    score += 20.0 * dead_penalty * (0.3 + 0.7 * progress);

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty for wasting the lookahead chance.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate space usage).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // When many bins are open, encourage filling existing ones rather than
    // opening new bins; when few bins are open, allow exploration.
    let crowd = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + 1.5 * crowd;
        // But early in stream, new bins are cheap.
        score -= 10.0 * (1.0 - progress);
        // If next item is large and current item is large, opening a fresh bin
        // preserves flexibility.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 12.0;
        }
    } else {
        // Existing bin: reward using it more when the bin count is high.
        score -= 1.0 * crowd.min(10.0);
    }

    // Slight preference for bins whose residual is close to a multiple of
    // common item sizes (modular alignment heuristic).
    let r = post_residual % 25;
    if r == 0 {
        score -= 4.0;
    } else if r < 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + 0.9 * t - 0.7 * t * t;
    score *= poly;

    // Tightness reward: quadratic in fill fraction.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill;

    // Dead-space penalty: residuals too small to fit typical items.
    let dead = (pr / cap).powi(3);
    score += 8.0 * dead;

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage opening many bins early; new-bin candidate gets a progress-dependent penalty.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) + 2.0 * open_bins_count as f64;
    }

    // Mild mean-residual coupling to balance load across bins.
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and 25
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;

    // Reward (subtract) when post_residual lands in "usable" harmonic classes.
    // Small usable slivers (<=10) are ideal: subtract heavily.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Exact residue-0 classes are harmonically reusable by mid-size items.
    if mod10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if mod25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd, awkward residues create dead space risk.
    if mod10 != 0 && mod10 != 5 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is perfect — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / 50.0).max(0.0);
        } else {
            // Next item cannot use this residual at all: penalize large residuals.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin when good open fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        // Opening a new bin is attractive only if the item is huge relative to capacity
        // or existing bins fit poorly.
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.9;
        let penalty = 35.0 + waste * 0.4 - 20.0 * progress;
        if poor_fit_elsewhere || item_size >= 70 {
            score -= 15.0; // big item: fresh bin is fine
        } else {
            score += penalty;
        }
        // New bin residual after placement is just capacity - item; keep base score.
    }

    // Mild preference for filling already-partly-used bins when many bins are open.
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.05;
    }

    // Tie-break toward bins whose residual is close to mean (keeps balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 5.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    let pressure = open_bins_count as f64 / 10.0;
    if bin_residual != bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: penalize unless current placement would create bad dead space
        score += pressure * 2.0;
        if post_residual >= 30 {
            score += 20.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as i64) > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late stream: tighten dead-space tolerance
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post_residual (tight fit)
    let mut score = post;

    // 2-step lookahead: perfect match bonus if next item exactly fills post_residual
    if next > 0.0 {
        if next == post {
            score -= 1000.0; // perfect chain: next item seals this bin
        } else if next <= post {
            // next item fits here: reward proportionally to how well it fills remainder
            score -= 40.0 * (next / post.max(1.0));
        } else {
            // next item cannot fit: penalize leftover dead space relative to item scale
            score += 0.5 * (next - post).min(post);
        }
    }

    // Penalize post_residual that is too small to ever be useful
    // (items are >= 1; residual below typical small item is dead space)
    if post > 0.0 && post < 10.0 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins with decent fits,
    // but allow opening a new bin when post_residual would be wasteful.
    if bin_residual == bin_capacity {
        score = post + 25.0;
        if next > 0.0 && next == post {
            score -= 500.0; // fresh bin perfectly chains with next item
        }
        if fitting_bins_count == 1 {
            // existing last-chance bin exists; only open new bin if it's a terrible fit
            if post > 0.0 && post < 10.0 {
                score -= 200.0;
            }
        }
    }

    // Mild context: prefer consolidating into bins with below-average residual
    // (packs fuller bins first, keeping emptier bins flexible)
    if bin_residual != bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * rel;
    }

    // Slight preference for packing earlier bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins whose post residual is small relative to capacity.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tight * tight;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 14.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 8 {
        score += 10.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits exactly or snugly: strong reward.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 8.0 + 10.0 * snug;
        } else if post_residual > 0 && nx > post_residual {
            // Next item won't fit here; penalize leaving awkward residuals.
            let waste = nx - post_residual as f64;
            if waste < 12.0 {
                score += 5.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Global state coupling: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_f = open_bins_count as f64;
    let consolidation = (mean_residual / cap) * (open_f / (open_f + 3.0));
    score -= 5.0 * consolidation;

    // Early in stream: allow opening new bins more freely (exploration);
    // late in stream: strongly prefer filling existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        let early_bias = (1.0 - progress) * 12.0;
        let crowded_bias = if open_bins_count == 0 { 0.0 } else { (open_f - 1.0) * 1.5 };
        let mean_gap = (mean_residual - post_residual as f64).max(0.0);
        score += 8.0 + crowded_bias + mean_gap * 0.3 - early_bias;
    }

    // Mild penalty for very large item into nearly-full bin creating tiny leftover.
    if item_size as f64 > 0.7 * cap && post_residual > 0 && post_residual < 15 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Base: prefer low post_residual (tight fit), non-linearly.
    let mut score = pr_norm * (1.0 + 0.5 * pr_norm);

    // Smooth interaction: waste matters more later in the stream.
    score += 2.0 * pr_norm * pr_norm * progress;

    // Penalize post_residual that is small but unusable for the next item
    // (dead space), smooth via ratio of next item to post_residual.
    if next_item_size > 0 {
        let unusable = (next_frac - pr_norm).max(0.0) / (next_frac + 0.05);
        score += 1.5 * unusable * (1.0 - pr_norm) * (0.5 + progress);
    }

    // Reward tight fits: subtract when item fills most of the bin.
    score -= 1.2 * item_frac * item_frac * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Slight penalty for bins far from mean residual (keeps balance),
    // scaled smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev;

    // New-bin candidate: make it attractive only when its residual beats
    // what open bins can offer, smoothly via its own post_residual.
    if bin_residual == bin_capacity {
        score = pr_norm * (1.0 + 2.5 * progress) + 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead space bands".
    // Residues 1..9 are awkward (nothing 10..80 fits well), residue 0 is ideal.
    let residue = post_residual % 10;
    score += match residue {
        0 => -12.0,
        1 | 2 | 3 | 4 | 5 => 6.0 + 1.5 * (5 - residue.min(&5)) as f64,
        _ => 2.0,
    };

    // Integer-division thresholds: post_residual in [0,10) is nearly perfect fill.
    if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 6.0;
    } else if post_residual > 50 {
        // Large leftover wastes a bin's potential; penalize proportionally.
        score += (post_residual as f64 - 50.0) * 0.4;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_res = post_residual - next_item_size;
        score -= 15.0;
        if next_res % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead space unusable by next item: mild penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when current bin would be badly fragmented
    // or no good fit exists. Fresh bin residual == capacity gets a calibrated handicap.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        if bad_fit {
            score -= 8.0; // opening fresh bin beats wasting an open bin's large residual
        } else {
            score += 25.0; // prefer existing bins when fit is decent
        }
    }

    // Fraction of stream progressed: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.05;

    // Mean residual coupling: if this bin is far below mean residual, it is the "emptiest"
    // bin; using it consolidates fragmentation.
    let diff = mean_residual - post_residual as f64;
    if diff > 10.0 {
        score -= diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward leaving room exactly for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize post_residual that cannot fit the next item while being large.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: penalize unless current fits are very poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin when the stream is early and few bins are open.
        if open_bins_count < 3 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // slack after also placing next item
            let slack2 = post_residual - next_item_size;
            score -= 20.0 - (slack2 as f64).min(20.0) * 0.4;
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare residual against mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: only one bin fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        score += 30.0 + 0.5 * open_bins_count as f64 - 0.2 * pressure;
    }

    // Late in the stream, consolidate: favor bins with less remaining space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dynamic time horizon: progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Tight-fit rewards: near-perfect fills are gold ---
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual <= 3 {
        score -= 6.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: reward, strongest when
            // the next item exactly consumes the leftover (chained packing).
            let chain = next / post.max(1.0);
            score -= 4.0 + 6.0 * chain;
            if post_residual == next_item_size {
                score -= 5.0; // perfect two-item packing
            }
        } else if (bin_residual as f64) >= next {
            // Placing here destroys space the next item could have used.
            let wasted_for_next = next - post;
            score += 4.0 + 0.5 * wasted_for_next;
            score += progress * 0.15 * wasted_for_next;
        }
        // Sliver dead-space: tiny leftover the next item cannot use.
        if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
            score += 2.0;
        }
    }

    // --- Last-chance bonus: only open bin that fits; avoid proliferation ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // --- Global-state consolidation vs. new-bin reluctance ---
    if is_new_bin {
        // Reluctance to open a new bin: stronger late in the stream and when
        // existing bins still hold plenty of collective slack.
        let slack_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 + 25.0 * progress + 10.0 * slack_pressure;
        // A fresh bin hosting a large item leaves a predictable canvas: soften a bit.
        score -= 0.04 * item_size as f64;
    } else {
        // Consolidation pressure: many open bins and loose mean slack both
        // favor pouring this item into an existing bin.
        score -= 0.05 * open_bins_count as f64;
        score -= 0.02 * (cap - mean_residual.clamp(0.0, cap));
    }

    // --- Time-horizon sharpening: enforce tighter best-fit as the stream ends ---
    score += progress * 0.05 * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals (keep bins flexible); later,
    // aggressively minimize dead space via amplified polynomial terms.
    let progress_amp = 1.0 + 2.5 * progress * progress;
    let mut score = post * (1.0 + 0.02 * progress_amp) + 0.004 * post * post * progress_amp;

    // Reward tight fits (small post_residual relative to capacity) smoothly.
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 10.0 * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual (balance portfolio),
    // with smooth non-linear deviation term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item can also fit into the resulting
    // residual, reward; if the next item would be blocked, penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap) * (0.5 + progress);
        } else {
            score += 5.0 * (nxt - post) / cap * (0.3 + 0.7 * progress);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are open; relax only for large items late in stream.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // Smooth relief when item is large (poor fit elsewhere anyway).
        score += new_bin_penalty * (1.0 - 0.4 * fit_frac);
    }

    // Mild penalty for opening many bins relative to stream length.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes of capacity fractions
    let pr = post_residual as i64;
    let quarter = (bin_capacity / 4) as i64;
    let eighth = (bin_capacity / 8) as i64;

    // Reward residuals that are harmonic multiples of capacity fractions
    // (residuals near 0, C/8, C/4, 3C/8, C/2 are more reusable for common item sizes)
    let harmonics = [0i64, eighth, 2 * eighth, 3 * eighth, 4 * eighth, 5 * eighth, 6 * eighth, 7 * eighth, 8 * eighth];
    let mut harmonic_bonus = 0.0f64;
    for h in harmonics.iter() {
        let d = (pr - h).abs() as f64;
        if d <= eighth as f64 {
            harmonic_bonus = harmonic_bonus.max(1.0 - d / (eighth as f64));
        }
    }
    score -= 12.0 * harmonic_bonus;

    // Penalize dead space in the awkward band (residual just above half capacity is hard to fill)
    if pr > (bin_capacity / 2) as i64 && pr <= (3 * bin_capacity / 4) as i64 {
        score += 6.0;
    }

    // Lookahead coupling: harmonic class of next_item_size vs post_residual
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n <= pr {
            // next item fits exactly or nearly exactly into post residual -> strong reward
            let slack = pr - n;
            if slack == 0 {
                score -= 25.0;
            } else if slack <= eighth {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's residual: penalize proportionally
            score += 4.0 + (n - pr).min(bin_capacity as i64) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Tight fit reward: near-perfect packing
    if pr == 0 {
        score -= 30.0;
    } else if pr <= eighth {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good open option exists.
    // Base it on mean residual and stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = cap * 0.55;
        // If open bins have small mean residual, opening new bin is reasonable
        if mean_residual < 0.25 * cap {
            nb -= 0.35 * cap;
        }
        // Early stream: keep bins open; late stream: prefer consolidation
        nb += 15.0 * (1.0 - progress);
        if fitting_bins_count > 2 {
            nb += 8.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // future item are worthless; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Gap that cannot fit the lookahead item is partially dead unless tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to a new bin
    // and prefer bins with larger residuals (consolidation).
    score += open_bins_count as f64 * 0.6;
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., residual is large but waste would be huge), otherwise push it up.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 1.2;
        // Opening a new bin is fine if the item is large and lookahead is big
        // (fresh bin gives flexibility).
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect 2-chain: post_residual == next_item_size -> strong reward.
        if diff < 0.5 {
            score -= 12.0;
        } else if post_residual as f64 >= nxt {
            // Next item still fits: partial reward scaled by tightness.
            score -= 6.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize leaving a gap that is nearly usable.
            let gap_frac = 1.0 - (post_residual as f64 / nxt);
            score += 4.0 * gap_frac;
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 2.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all large.
    if bin_residual == bin_capacity {
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let avg_tight = mean_residual / bin_capacity as f64;
        // Open new bin if existing bins are mostly full (avg residual small) or few bins open.
        let penalty = 25.0 * (1.0 - avg_tight) - 8.0 * open_frac.min(1.0);
        score += penalty.max(0.0);
    }

    // Mild progression pressure: later in stream, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping by stream progress
    let mut score = pr * (1.0 + 0.6 * progress * (norm_pr * norm_pr - 0.5 * norm_pr));

    // Reward tight fits (low post residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.3 + 0.7 * progress);

    // Penalize creating dead space that next item likely can't use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 3.0 + 4.0 * progress * (nxt - pr) / cap;
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    } else {
        // Last item: any residual is pure waste
        score += pr * 0.5;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress * 0.5);
    }

    // Slight preference to spread load when many bins are open
    score += (open_bins_count as f64).ln() * 0.3 * norm_pr;

    // Coupling with mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: penalize opening a fresh bin unless residual would be very usable
    if bin_residual == bin_capacity {
        score += 4.0 - 3.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer-division thresholds and modulo arithmetic on capacity.
    let post = post_residual as f64;

    // Perfect fit: post_residual in {0} -> strongly reward.
    if post_residual == 0 {
        score -= 3.0 * cap;
    }

    // Dead-space classes: leftover too small for any plausible item (min 1..10).
    // Class A: post_residual < 10 -> unusable dead space, penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0 * cap;
    }

    // Class B: post_residual in 10..=20 -> only fits tiny items, mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 0.5 * cap;
    }

    // Harmonic class via integer division: post_residual / 25 buckets
    // (0: tiny, 1: quarter, 2: half, 3: three-quarter).
    let harmonic_bucket = post_residual / 25;
    score += harmonic_bucket as f64 * 0.75 * cap;

    // Modulo coupling: post_residual divisible by 5 or 10 pairs well with
    // typical item sizes (multiples of 5/10) -> reward aligned leftovers.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 0.3 * cap;
    }
    if post_residual % 10 == 0 {
        score -= 0.2 * cap;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 2.0 * cap;
        } else if next_item_size <= post_residual {
            // Next fits: reward proportional to how tightly it packs.
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 0.8 * cap * tight;
        } else {
            // Next item won't fit here: penalize bins whose leftover is
            // "just barely" too small (wasted potential).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 0.6 * cap * (1.0 - miss / 10.0);
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5 * cap;
    }

    // New-bin candidate handling: empty bin gets a mild default penalty so we
    // only open new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 0.4 * cap;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 0.5 * cap;
        // If mean residual across open bins is small, new bin is attractive.
        if mean_residual < 15.0 {
            score -= 0.5 * cap;
        }
    }

    // Late-stream consolidation: as stream ends, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.25 * cap * (post / cap);

    // Deviation from mean residual: prefer bins whose residual is below mean
    // (fill the emptier-feeling bins first keeps many bins usable).
    score -= (mean_residual - post).clamp(-cap, cap) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: ideal, heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps
    // (gap too small for the minimum plausible item, here < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Moderately awkward gap for small items (1..100 range).
        score += 12.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating
    // into existing bins rather than spreading out.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (they are the "fuller" ones).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New empty bin candidate: only attractive when the item is large
    // (poor fit elsewhere) or no open bin is genuinely tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Large items justify a fresh bin (they leave little dead space anyway).
        score -= 40.0 * fill_ratio;
        // If other bins fit, discourage the new bin unless it's a last resort.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        // Strong reward when next item fits perfectly after this placement
        let perfect = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 60.0 * (1.0 - perfect / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item
        score += 25.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are preferred targets
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.4;

    // Last-chance bonus: avoid wasting the only fitting bin's residual on bad fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: discourage unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly prefer placements that leave little waste.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fill_ratio * (post_residual as f64);

    // Penalize residuals that are "dead space" — too small to hold even the
    // smallest plausible item, but not zero. Perfect closure (0) is best.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) < dead_threshold {
            score += 15.0 * (1.0 - post_residual as f64 / dead_threshold);
        }
    } else {
        score -= 8.0; // exact fit bonus
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 {
            score += 6.0; // next item likely can't use this bin
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Global congestion: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score += congestion * 0.3 * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win when the fit
    // here is bad or the item is huge relative to available residuals.
    if bin_residual == bin_capacity {
        let bad_fit = fill_ratio < 0.5;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if bad_fit || big_item || open_bins_count == 0 {
            score -= 10.0 + 8.0 * (1.0 - fill_ratio);
        } else {
            // discourage opening new bins when decent fits exist
            score += 14.0 + 6.0 * progress;
        }
    }

    // Mild preference for larger items going into emptier bins early on.
    score -= 1.5 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by smooth progress terms
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward tight fits via cubic shaping of normalized fill
    score -= 12.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Penalize residuals that are too small to be useful (dead space), smooth quadratic
    let dead = ((14.0 - pr) / 14.0).max(0.0);
    score += 8.0 * dead * dead;

    // Lookahead coupling: reward leaving room for the next item, smooth kernel
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        let kernel = (-d * d * 40.0).exp();
        score -= 6.0 * kernel;
        // penalize if next item cannot fit at all
        if nx > pr {
            score += 4.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: smooth sigmoid on fitting_bins_count == 1
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 10.0 * last_chance;

    // Mean residual deviation: prefer bins close to mean (mild regularization)
    score += 0.05 * (pr as f64 - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin progressively as stream advances
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonically
    // compatible" with typical future items (small, or multiples of common classes).
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class (0..10)
    match class {
        0 => score -= 12.0,            // near-perfect fit, almost no dead space
        1 => score -= 6.0,             // small residual, still harvestable
        2 | 3 => score -= 2.0,         // mid-small residuals
        4 | 5 | 6 => score += 3.0,     // awkward dead space zone
        7 | 8 => score += 1.0,         // large residual, still flexible
        _ => {}
    }

    // Perfect modulo classes: residual exactly divisible by common item sizes
    if pr > 0 {
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 4.0;
                break;
            }
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
            if slack <= 10 {
                score -= 5.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally
            score += 4.0;
        }
    } else {
        // last item: minimize leftover strongly
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // here is poor (large post_residual) or many bins are open with slack.
    if bin_residual == bin_capacity {
        score = cap * 0.55
            + 6.0 * (open_bins_count as f64).sqrt()
            + (post_residual as f64) * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin gives next item a clean home
        }
        if fitting_bins_count == 1 {
            score += 20.0; // never open new bin when a sole bin fits
        }
    }

    // Mild global pressure: when mean residual is high, encourage filling bins.
    score -= 0.05 * mean_residual;

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap that the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap exactly usable by next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if this bin would be a great fit
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if post_residual == 0 {
            score -= 100.0; // perfect fill in a fresh bin
        }
        if item_size >= 70 {
            score -= 25.0; // large items are fine in fresh bins
        }
    } else {
        // Mild reward for filling existing bins deeper
        score -= 0.1 * (bin_capacity - bin_residual) as f64 * 0.1;
        if post_residual == 0 {
            score -= 50.0; // perfect closure of an open bin
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
