pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize dead space: post residual that is small but unusable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra bonus if it fits snugly too
            let n_tight = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * n_tight;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, keep bins flexible (prefer balanced residuals);
    // late in the stream, just fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.3;
    score -= progress * 10.0 * tightness;

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // If the only alternative is bad (no other fitting bins), allow new bin.
        if fitting_bins_count == 0 {
            score = 0.0;
        } else {
            // Open new bin only for large items or when mean residual is very low.
            score = base + (100.0 - item_size as f64) * 0.4 - mean_residual * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: small post_residual gets a non-linear discount.
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful later (smooth quadratic).
    let dead = (post - 10.0).max(0.0);
    score += 0.15 * dead * dead / cap;

    // Lookahead: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = post - nx;
            score -= 30.0 * (1.0 - gap / cap).powi(2);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 0.1 * (nx - post);
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Non-linear stream-progress coupling: early on prefer consolidating into
    // existing bins (minimize open bins); later allow tighter packing bias.
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score += consolidation * (2.0 + 6.0 * progress * progress);

    // Pull score toward mean residual alignment: bins far below mean residual
    // (i.e., already full) are good targets; smooth sigmoid coupling.
    let sig = 1.0 / (1.0 + (-(mean_residual - post) / 20.0).exp());
    score += 10.0 * sig * (0.5 + progress);

    // Brand-new empty bin candidate: penalize opening a new bin unless the
    // item leaves a large, reusable residual or no good fit exists.
    if bin_residual == bin_capacity {
        let reusable = (post / cap).powf(0.5);
        score += 18.0 * (1.0 - reusable) * (1.0 + 3.0 * progress);
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10
    let cls = post_residual % 10;
    // Dead-space penalty: residuals that are hard to fill (1..=9 but not "nice" like 0, 50)
    match cls {
        0 => { score -= 12.0; }          // perfect fill
        5 => { score -= 6.0; }           // half-class, still fillable by mid items
        1 | 2 | 3 => { score += 8.0; }   // sliver dead space
        4 | 6 => { score += 3.0; }
        7 | 8 | 9 => { score += 5.0; }
        _ => {}
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 10;
    if q <= 1 { score += 15.0; }         // nearly full bin: excellent, but check lookahead
    else if q <= 3 { score -= 4.0; }
    else if q >= 8 { score += 6.0; }     // mostly empty bin: weak use

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's residue class compatible
            let ncls = (post_residual - next_item_size) % 10;
            if ncls == 0 { score -= 14.0; }
            else if ncls <= 3 { score += 6.0; }
            else { score -= 4.0; }
        } else {
            // next item won't fit here; slight penalty unless this is a perfect fill now
            if cls != 0 { score += 7.0; }
        }
    }

    // Last-chance bonus: only bin that fits avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let good_fit = (bin_capacity - item_size) % 10 == 0;
        if good_fit { score += 5.0; } else { score += 25.0; }
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Mean residual coupling: if open bins are slack, tighten selection
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score += 20.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits generally (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Pressure from many open bins: encourage filling existing bins.
    score += 2.0 * open_bins_count as f64;

    // Favor bins whose residual is below the mean (consolidate large gaps).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity and no good fit exists (high residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if large_item || (fitting_bins_count <= 1 && mean_residual < item_size as f64) {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 50.0; // discourage opening new bins when open bins suffice
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and next_item_size (perfect two-item packing).
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect 2-step fit
        } else if diff > 0 {
            // Penalize leftover that next item cannot use well
            let waste = diff as f64;
            score += 0.4 * waste;
            if waste < 10.0 {
                score -= 5.0; // small usable gap is fine
            }
        } else {
            // next item cannot fit here afterwards; mild penalty scaled by gap
            score += 0.15 * (-diff) as f64;
        }

        // Reward when post_residual can hold next item at all
        if post_residual >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: just minimize final residual (already done by base score)
        score -= 1.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist that fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin is attractive only if item is large relative to typical residuals
        let tight_mean = mean_residual < item_size as f64 * 1.2;
        if !tight_mean {
            score += 15.0;
        } else {
            score += 3.0;
        }
    }

    // Prefer filling bins with larger residual utilization early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Perfect setup for the next item: strong reward.
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            // Dead space too small for likely future items: penalize.
            score += 8.0 * (10.0 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Early in the stream, be more willing to spread items (favor larger residuals
    // less aggressively); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly more so when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * (open_bins_count as f64).min(20.0) * dev / bin_capacity as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && (fitting_bins_count == 0 || post_residual < 10);
        if poor_fit {
            score -= 6.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual fraction
    let post_frac = post / cap;

    // Smooth non-linear polynomial penalty on wasted space: cubic coupling
    let mut score = post + 40.0 * post_frac * post_frac * cap + 25.0 * post_frac.powi(3) * cap;

    // Stream progress coupling: later in stream, penalize waste more aggressively
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= 0.6 + 0.4 * progress_coupling;

    // Reward if the next item exactly fills the post-residual (perfect chaining)
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post - next).abs();
        let match_frac = 1.0 - (gap / cap).min(1.0);
        // Smooth quadratic reward for lookahead match
        score -= 30.0 * match_frac * match_frac;
        // Extra reward if next item fits exactly into post residual
        if next <= post {
            score -= 10.0 * (next / cap);
        }
    }

    // Last-chance bin: strong reward to use it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Reward using bins with residuals below the mean (consolidate small residuals)
    let mean_frac = mean_residual / cap;
    let this_frac = bin_residual as f64 / cap;
    score -= 20.0 * (mean_frac - this_frac);

    // Penalize very tight fits that leave unusable slivers (< 10 units) more sharply
    let sliver = ((post - 9.0).abs()) / cap;
    if post < 9.0 {
        score += 15.0 * (1.0 - post / 9.0);
    }
    let _ = sliver;

    // New-bin candidate: residual == capacity. Prefer it only if it beats waste elsewhere;
    // add a mild exploration bonus that decays with stream progress.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
        // Encourage opening a new bin when many open bins already exist
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits (post_residual in low harmonic classes).
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual <= eighth {
        score -= 25.0; // nearly perfect
    } else if post_residual <= quarter {
        score -= 12.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 6.0;
    } else {
        score += 18.0; // large dead space
    }

    // Modulo-10 harmonic class of post_residual: small residues divisible by
    // common item sizes (10/20/50) are more reusable.
    let pr = post_residual as i64;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nr = (post_residual - next_item_size) as i64;
            if nr <= eighth as i64 {
                score -= 15.0;
            } else {
                score += (nr as f64) * 0.15;
            }
        } else {
            // next item cannot use this bin's residue: penalize wasted potential
            score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.1;
        }
        // harmonic class match: next item size class aligns with residual class
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is huge and
    // current residual is awkwardly small (poor fit).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        let penalty = 30.0 - 40.0 * tightness; // large items make new bins cheaper
        score += penalty.max(-10.0);
        if next_item_size > 0 && next_item_size > post_residual.min(bin_capacity) {
            score -= 10.0; // next item won't fit anyway, keep fresh bins
        }
    }

    // Stream progression: late in stream, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += (open_bins_count as f64) * 0.5;

    // Mean residual anchoring: prefer bins near the mean (keeps balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are worthless.
    if post_residual < 10 {
        score += 45.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 18.0; // risky small gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins unless the current fit is poor
    // or the next item can use the fresh bin well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 55;
        let lookahead_ok = next_item_size == 0 || next_item_size as f64 >= post_residual as f64;
        if !poor_fit && !lookahead_ok {
            score += 40.0;
        } else {
            score += 5.0;
        }
    }

    // Lookahead synergy: prefer bins whose leftover accommodates the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 12.0;
        } else if gap < 10 {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 0.5;
    }

    // Deviation from mean residual: prefer bins tighter than average (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to wasted space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize very small unusable post_residual (dead space) unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Late-stream consolidation: favor filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open
        score += 120.0 + 200.0 * progress + 5.0 * open_bins_count as f64;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly as post_residual shrinks.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Penalize dead space: residuals too small for any plausible item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Prefer bins with below-average residual (concentrate fullness).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Many open bins: encourage closing them out (prefer fuller bins).
    if open_bins_count > 3 {
        score += (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 2.0;
    }

    // Time horizon: early on, keep bins flexible (mild); late, chase tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - tightness) * progress * 20.0;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let best_possible_gap = post_residual as f64; // == capacity - item for new bin
        score += 15.0 - (best_possible_gap / bin_capacity as f64) * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // opening a bin early in the stream is fine; late is costly
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;

    // Smooth non-linear reward for tight fits, amplified as stream progresses.
    score -= 24.0 * fill3 * (0.35 + 0.65 * progress);

    // Penalize dead space quadratically; weight grows late in the stream.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * dead * dead * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            let over = (nxt - pr) / bin_capacity as f64;
            score += 12.0 * over * over;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fill2;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild pressure toward consolidating among few open bins early on.
    score += 1.5 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // New-bin candidate: smooth penalty that relaxes when the item is large
    // relative to residuals of open bins (encourage opening for big items late).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 22.0 * (1.0 - size_frac) * (0.5 + 0.5 * progress);
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue classes
    // modulo small divisors to detect "reusable" vs "dead" leftover capacities.
    let pr = post_residual;
    let cls10 = (pr % 10) as f64;          // sub-decade residue
    let cls20 = (pr % 20) as f64;          // fine harmonic class
    let cls5 = (pr % 5) as f64;            // micro residue
    let int_div = pr / 10;                 // integer division tier (decades of leftover)

    // Penalize leftover space that is NOT a harmonic multiple of common item classes
    // (items 1..100 tend to cluster; leftovers divisible by 10/20 are more reusable).
    score += cls10 * 0.6 + cls20 * 0.35 + cls5 * 0.5;

    // Reward large integer-division tiers only when they stay harmonic (multiple of 10).
    if pr % 10 == 0 {
        score -= int_div as f64 * 1.5;
    } else {
        score += int_div as f64 * 0.3;
    }

    // Perfect fits: leftover zero is ideal; tiny dead space (< 10) is nearly useless.
    if pr == 0 {
        score -= 25.0;
    } else if pr < 10 {
        score += 12.0; // dead space penalty
    }

    // Lookahead coupling: harmonic class of the next item vs leftover.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            // Next item fits here: reward strongly, especially if it harmonizes (mod 10 == 0 leftover chain).
            score -= 8.0;
            if (pr - nxt) % 10 == 0 {
                score -= 4.0;
            }
            if pr - nxt == 0 {
                score -= 10.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit: leftover risks becoming dead space.
            score += 6.0;
            if pr < 20 {
                score += 6.0;
            }
        }
        // Penalize when leftover and next item share an awkward harmonic class
        // (both odd residues mod 10 -> poor future packing granularity).
        if pr % 2 == 1 && nxt % 2 == 1 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_ratio = item_size as f64 / cap;
        // Prefer new bin when the item is large and open bins are fragmented.
        let fragmentation = (mean_residual / cap).abs();
        score = cap - (score * 0.15);
        score -= fit_ratio * 10.0 + fragmentation * 5.0 + progress * 3.0;
        // Discourage opening new bins when plenty of low-residue space exists.
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 20.0;
        }
    } else {
        // Slight preference for bins whose residual is harmonically close to the item.
        let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
        score += diff * 0.05;
        // Prefer bins below mean residual (tighter bins first) mildly.
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    // Global pressure: with many open bins, be greedy about filling them.
    score -= (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small waste relative to item size).
    if item_size > 0 {
        score -= 25.0 * (item_size as f64 / (item_size + post_residual) as f64);
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 20.0 * (10.0 - gap as f64); // next item would leave dead space
            } else {
                score -= 8.0; // next item can use leftover space
            }
        } else {
            // next item cannot use this residual; residual becomes dead weight
            score += 0.05 * post_residual as f64;
        }
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mild penalty if this bin's residual is far below the mean (already well used).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: make empty bins attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress
        score += 40.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // if no other bin fits well, allow opening
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        } else if post_residual < next_item_size {
            // dead space for the next item: penalize unless this is the only fitting bin
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: pure tightness
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    score += 0.12 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-full bin on a small item
    if item_size < bin_residual / 3 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - next_item_size as f64).abs();
        score += 55.0 - 20.0 * progress + 0.4 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight_fit * tight_fit;

    // Penalize dead space that cannot plausibly fit future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (1.0 - progress); // small gaps less useful late
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting large residuals.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins with least residual after placement.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with global mean residual: prefer bins below mean residual
    // (fill the emptier-trending bins to consolidate).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make an empty bin attractive only when
    // no open bin fits well or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let pressure = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64) / open_bins_count as f64
        } else {
            0.0
        };
        // Base penalty so new bins aren't opened frivolously.
        let mut new_bin_score = 55.0;
        // If current item is huge and residuals are fragmented, opening is fine.
        if large_item > 0.6 && pressure < 0.35 {
            new_bin_score -= 30.0;
        }
        // If this bin is the only fitting option, opening a new bin is bad.
        if fitting_bins_count == 1 {
            new_bin_score += 40.0;
        }
        // Lookahead: if next item is large, fresh capacity is valuable.
        if next_item_size > 50 {
            new_bin_score -= 10.0;
        }
        // Late in the stream, avoid opening new bins.
        new_bin_score += 15.0 * progress;
        return new_bin_score;
    }

    // Mild consolidation bonus for bins already well-filled.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 30.0
                 - norm_pr * progress * 20.0
                 + norm_pr * norm_pr * norm_pr * progress * 15.0;
    score += coupling;

    // Penalize dead space relative to next item fit
    if next_item_size > 0 && (next_item_size as f64) > pr {
        let gap = (next_item_size as f64 - pr) / cap;
        score += gap * gap * 40.0;
    } else if next_item_size > 0 {
        let tight = (next_item_size as f64) / pr.max(1.0);
        score -= tight * 8.0;
    }

    // Last-chance bin reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (item_size as f64 / cap);
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual deviation term (smooth)
    score += (mean_residual - pr) * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize unless residual would be very tight
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 100.0 - (post_residual as f64) * 5.0;
    }

    // Class of residual modulo capacity fractions: residuals divisible by
    // common item sizes (10,20,25,50) are "usable" classes; reward them.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 20.0; }
        if r % 25 == 0 { score -= 15.0; }
        if r % 50 == 0 { score -= 15.0; }
        // Dead-space class: tiny unusable remainders.
        if r < 10 { score += 60.0; }
        // Integer-division threshold: residual in "half-bin" harmonic band.
        if r >= 45 && r <= 55 { score -= 25.0; }
        if r >= 90 { score -= 10.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: penalize leaving stranded space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 5.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good harmonic fit (large item, few fitting bins, early stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_bonus = (open_bins_count as f64) * 2.0;
        // Default: new bin is worse than reusing (penalty), unless item is huge.
        score += 40.0 - open_bonus;
        if item_size > 60 && fitting_bins_count == 1 {
            score -= 120.0; // big item with only one fit: new bin may be better
        }
        if progress > 0.8 && mean_residual < item_size as f64 {
            score -= 50.0; // late stream, open bins are full-ish
        }
    }

    // Mild preference for tighter (fuller) bins overall.
    score += (bin_residual as f64) * 0.05;

    // Tie-break noise-free deterministic coupling with step index.
    score -= (step_index as f64 % 7.0) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // by typical future items (<= 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Residuals too small for the lookahead item are also risky dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this empty-bin call would otherwise be a last resort).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 55.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let gap = post - next;
            if gap <= 5.0 {
                score -= 300.0; // next item fits almost perfectly here
            } else {
                score -= 150.0 / gap; // partial reward for lookahead compatibility
            }
        } else {
            // next item cannot fit here; penalize wasted space relative to gap
            let gap = next - post;
            score += gap * 0.5;
        }
    } else {
        // Last item: prefer minimal post_residual strongly.
        score -= 500.0;
    }

    // Relative-to-mean-residual coupling: bins tighter than average are more precious.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let tightness = (mean_residual - res) / mean_residual;
        score += tightness * 30.0; // tighter-than-average bins get priority (lower score)
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize creating large dead space (< smallest plausible item ~10) that nothing may use.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Slight preference to keep many open bins consolidated as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }
    // Penalize large dead space with nonlinearity
    let pr = post_residual as f64;
    score += 0.02 * pr * pr;

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space that next item can't use: penalize mildly
        score += 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state: many open bins with slack -> prefer reusing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let openness = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    score += 0.05 * openness * (1.0 - progress);

    // Mean residual coupling: prefer bins close to mean residual (balanced usage)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual as f64 > 0.6 * bin_capacity as f64 && next_item_size > post_residual {
            score += 20.0; // avoid wasteful new bins early in stream
        }
    }

    // Time horizon: late in stream, be greedier with existing bins
    score -= 15.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial decay of residual value with stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized post-residual and its smooth non-linear coupling
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let pr_sq = pr_norm * pr_norm;

    // Late in the stream, small residuals are more valuable (tight packing)
    score -= 18.0 * prog3 * (1.0 - pr_sq) * pr_norm;

    // Penalize awkward mid-range dead space, stronger as stream progresses
    let awkward = 4.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 25.0 * awkward * (0.4 + 0.6 * progress);

    // Last-chance bonus: only bin that fits -> reward using it smoothly
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * pr_norm);
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64) / cap;
        score -= 20.0 * fit_quality * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Next item won't fit: penalize leaving this residual shape
        score += 8.0 * pr_norm * (0.5 + 0.5 * progress);
    }

    // Crowd penalty: many open bins -> prefer filling existing ones
    let crowd = (open_bins_count as f64).ln1p();
    score += crowd * (2.0 + 6.0 * pr_norm) * (0.3 + 0.7 * progress);

    // Mean-residual alignment: prefer bins close to the mean residual (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev * cap * 0.1;

    // Smooth penalty on very tight fits creating near-zero residual early on
    score += 10.0 * prog2 * (1.0 - pr_norm) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes in capacity fractions
    let q = (bin_capacity / 4) as f64; // quarter-capacity quantum
    let post = post_residual as f64;
    let class = (post / q).floor(); // 0..4 harmonic class

    // Reward near-perfect fits (post_residual in the lowest class)
    if class == 0.0 {
        score -= 12.0;
    } else if class == 1.0 {
        score -= 3.0;
    } else if class == 3.0 {
        score += 4.0; // large dead space penalty
    }

    // Integer-division thresholds: post_residual divisible chunks
    if post_residual % 10 == 0 {
        score -= 2.0; // residual is a round multiple of 10 -> reusable by typical items
    }
    if post_residual % 3 == 0 {
        score -= 1.0;
    }

    // Lookahead coupling: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // harmonic match: next item exactly fills or leaves a small class-0 remainder
            let rem = post_residual - next_item_size;
            if rem <= bin_capacity / 10 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize slightly unless current bin fit is bad
    if bin_residual == bin_capacity {
        let good_fit = post_residual as f64 <= q;
        if good_fit && next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // fresh bin good if it can chain the lookahead
        } else {
            score += 5.0 + 0.02 * open_bins_count as f64;
        }
    }

    // Stream progression: early on, be more tolerant of spreading items
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.5;

    // Mean residual alignment: prefer bins close to mean (balanced packing)
    score += (mean_residual - post).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creates gap the next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residuals are large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins tighter than the mean (consolidation of small residuals).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral baseline with slight opening cost,
    // so it only wins when existing bins score very poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let tight = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        // Perfect chain fit (next item exactly fills remaining space) gets big reward.
        if post_residual == next_item_size {
            score -= 40.0 + 20.0 * tight;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 4 {
            score -= 12.0 + 10.0 * tight;
        } else {
            // Penalize wasted space that next item cannot use.
            score += 0.35 * gap * (0.5 + tight);
        }
        // If next item cannot fit here but this bin would be nearly full anyway, mild bonus.
        if next_item_size > post_residual && post_residual <= 8 {
            score -= 6.0;
        }
    } else {
        // Last item: minimize final residual strongly.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins whose residual is below average (tighter bins),
    // unless this is the last fitting bin (then keep it attractive).
    let residual_dev = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_dev;
    if fitting_bins_count == 1 {
        // Last chance before opening a new bin: strong reward to use this bin.
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fit; small penalty spread across candidates.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let best_possible_gap = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else { 0.0 };
        // Opening a new bin is justified only when no open bin chains with next item
        // and current fit is poor.
        let poor_fit = (post_residual as f64) > 0.45 * bin_capacity as f64;
        if poor_fit && best_possible_gap > 10.0 {
            score -= 8.0;
        } else {
            score += 30.0;
        }
    }

    // Slight preference to consolidate late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Reward reducing mean residual dispersion (fill bins below mean residual).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
