    // Last-chance bonus: only one bin fits -> reward using it, scaled by progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.4 + 0.6 * progress);
    }

    // New-bin candidate: mild penalty early, decaying late so fresh bins
    // become acceptable when open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 6.0 * progress;
    }

    // Discourage scattering across many open bins when mean residual is large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
