    // Prefer fuller bins overall (tightness coupling).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Slight penalty for opening a new bin when decent fits exist late in stream.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Stream-progression modulation: late in stream, prioritize perfect packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= harmonic_bonus * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize hard in the "unusable gap" band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 6.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to lookahead item
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (filling fuller bins first).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score worse.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large unusable dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills what remains.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0;
            score -= (10.0 - slack.min(10.0)) * 1.5;
        } else {
            // Next item won't fit here; penalize more if it's a near miss.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.6;
        }
    } else {
        // Last item: prefer tightest fit, small residuals are fine.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean residual are already tight,
    // placing there keeps loose bins available for future awkward items.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when current item leaves a bad fit
    // everywhere (large item with poor packing potential).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 60.0 + tightness * 20.0;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mild stream-progression pressure: pack tighter as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 120.0 / openness + 60.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this bin (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 30.0 + 40.0 * tightness;
    }
    // If next item is big and won't fit here anyway, slight penalty for leaving tiny gap
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Prefer bins with residual close to item (best-fit flavor), coupled with mean residual
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;
    score -= mean_residual * 0.1;

    // Late in stream: be greedy, fill existing bins harder
    if progress > 0.7 {
        score -= post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress * 2.0);
    score -= 12.0 * coupling;

    // Penalize small-but-nonzero dead space more as stream advances
    let dead = 1.0 - (pr / cap).powi(3);
    score += 8.0 * dead * progress;

    // Reward tight fits (low post_residual) especially when bin is a last chance
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item can use post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Mild preference for consolidating into fewer bins
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - item_size as f64 / cap) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but avoid tiny useless slivers.
    if post_residual == 0 {
        score -= 500.0; // perfect fill is ideal
    } else if post_residual < 10 {
        score -= 80.0; // small dead space is acceptable
    }

    // Harmonic classes: classify post_residual by residue mod 10.
    // Residues that pair well with small items (mod 10 classes) get rewards.
    let r = (post_residual % 10) as f64;
    score -= (10.0 - r) * 0.8; // prefer post_residual close to a multiple of 10

    // Integer-division thresholds on post_residual: large leftover space is
    // valuable only if it can host future items; penalize mid-range leftovers.
    let q = post_residual / 20; // coarse class: 0..5
    match q {
        0 => score -= 40.0,               // 0..19: tight
        1 => score += 10.0,               // 20..39: awkward zone
        2 => score -= 5.0,                // 40..59: ok
        3 => score += 15.0,               // 60..79: wasteful
        _ => {}                           // 80..100: nearly empty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers less
            // if bin residual class matches next item's complement class.
            let complement = bin_capacity - next_item_size;
            if item_size <= complement && post_residual >= 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.5 + 60.0;
        // At stream start, opening bins is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 80.0;
        // If many bins are open and mean residual is fragmented, new bin is attractive.
        score -= (open_bins_count as f64).sqrt() * 5.0;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 40.0;
        }
        // If next item is small, an empty bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 30.0;
        }
    } else {
        // Prefer filling bins with low residual relative to mean (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Modulo-class synergy: harmonic class of item vs post_residual.
    let cls = |x: u32| x / 10;
    if post_residual > 0 && cls(item_size) == cls(post_residual) {
        score -= 25.0; // same decade: likely good pairing with similar items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but typical sizes make gaps < 15 poor). Penalize them hard.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 + (15 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 40.0;
    }

    // Reward residual gaps that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.25;
    } else if next_item_size > 0 {
        // Gap cannot host the next item: mild dead-space penalty.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only allow opening a new bin when the current item
    // would leave a large, useful gap anyway (i.e., poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
    }

    // Mild trend term: as the stream progresses, prefer tightening existing bins.
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // penalize leaving awkward small gap after the chain
            let post2 = post_residual - next_item_size;
            if post2 > 0 && post2 < 10 {
                score += 25.0;
            }
        } else {
            // next item cannot follow; dead-space penalty grows with waste
            score += 0.35 * (post_residual as f64);
        }
    } else {
        // last item: prefer tightest fit
        score += 10.0;
    }

    // Prefer bins with residual close to mean (avoid fragmenting outliers)
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when good fits exist late in stream
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin sensible if next item is big
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Mild pressure to fill fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}
